        var darkSites = ['youtube.com', 'twitter.com', 'x.com', 'github.com',
                         'reddit.com', 'twitch.tv', 'netflix.com', 'spotify.com',
                         'discord.com', 'steampowered.com', 'store.steampowered.com',
                         'vk.com', 'startpozi.com'];
