// ============== PER-TAB AUTO-CLOSE TIMER ==============
var _tabCloseTimers = {};
var _tabCloseAt = {};
function setTabCloseAfter(tabId, minutes) {
  cancelTabCloseAfter(tabId);
  var ms = Math.max(1, parseInt(minutes)) * 60000;
  var tab = tabs.find(function(t) { return t.id === tabId; });
  if (!tab) return;
  _tabCloseAt[tabId] = Date.now() + ms;
  _tabCloseTimers[tabId] = setTimeout(function() {
    delete _tabCloseTimers[tabId];
    delete _tabCloseAt[tabId];
    _setTabCloseIndicator(tabId, 0);
    if (tabs.length > 1) closeTab(tabId);
  }, ms);
  _setTabCloseIndicator(tabId, _tabCloseAt[tabId]);
  if (!_tabCloseTicker) {
    _tabCloseTicker = setInterval(function() {
      Object.keys(_tabCloseAt).forEach(function(id) { _setTabCloseIndicator(id, _tabCloseAt[id]); });
    }, 30000);
  }
}
