// Horizontal wheel scroll for tabs bar
(function setupTabBarWheelScroll() {
  var tabsBar = document.querySelector('.tabs-bar');
  if (!tabsBar) return;
  tabsBar.addEventListener('wheel', function(e) {
    if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) {
      e.preventDefault();
      tabsBar.scrollLeft += e.deltaY;
    }
  }, { passive: false });
})();

(function setupTabBarContextMenu() {
  var tabsBar = document.querySelector('.tabs-bar');

  tabsBar.addEventListener('contextmenu', function(e) {
    e.preventDefault();
    var tabEl = e.target.closest('.tab');
    var targetTabId = tabEl ? tabEl.dataset.tabId : null;
    var tabUrl = '';
    var tabPinned = false;
    var tabGroupId = null;

    if (tabEl) {
      var targetTab = tabs.find(function(t) { return t.id === targetTabId; });
      if (targetTab && targetTab.isReady) {
        try { tabUrl = targetTab.webview.getURL ? targetTab.webview.getURL() : ''; } catch(e) {}
      }
      if (targetTab) {
        tabPinned = !!targetTab.pinned;
        tabGroupId = targetTab.groupId || null;
      }
    }

    var tabGroupsList = [];
    if (_tabGroups && _tabGroups.length > 0) {
      tabGroupsList = _tabGroups.map(function(g) { return { id: g.id, name: g.name }; });
    }

    if (window.electronAPI && window.electronAPI.showContextMenu) {
      window.electronAPI.showContextMenu({
        type: 'tabbar',
        x: e.clientX,
        y: e.clientY,
        tabId: targetTabId,
        tabUrl: tabUrl,
        tabPinned: tabPinned,
        tabGroupId: tabGroupId,
        tabGroups: tabGroupsList,
        closedTabs: closedTabsHistory.slice(0, 5).map(function(c) {
          return { url: c.url, title: (c.title || c.url).substring(0, 50) };
        }),
      });
    }
  });
})();

// ============== READING MODE ==============
(function setupReaderMode() {
  var readerBtn = document.getElementById('readerBtn');
  var readerOverlay = document.getElementById('readerOverlay');
  var readerClose = document.getElementById('readerClose');
  var readerContent = document.getElementById('readerContent');
  var readerTitle = document.getElementById('readerTitle');
  var readerFontSelect = document.getElementById('readerFontSelect');
  var readerFontMinus = document.getElementById('readerFontMinus');
  var readerFontPlus = document.getElementById('readerFontPlus');
  var readerSizeLabel = document.getElementById('readerSizeLabel');
  var readerThemeToggle = document.getElementById('readerThemeToggle');
  var readerFontSize = 18;
  var readerTheme = 'dark';

  function toggleReader() {
    if (readerOverlay.classList.contains('active')) {
      closeReader();
      return;
    }
    var tab = getActiveTab();
    if (!tab || !tab.webview || !tab.isReady) return;
    var wv = tab.webview;
    var url = '';
    try { url = wv.getURL ? wv.getURL() : (wv.src || ''); } catch(e) { url = wv.src || ''; }
    if (!url || url.indexOf('about:') === 0 || url.indexOf('chrome') === 0 || url.indexOf('file://') === 0) {
      customAlert('Reader mode unavailable for this page');
      return;
    }
    wv.executeJavaScript(
      '(function(){' +
      'function score(el){if(!el||!el.tagName)return 0;var t=(el.innerText||"").trim();' +
      'if(t.length<50)return 0;var tag=el.tagName.toLowerCase();' +
      'var b=0;if(tag==="article")b=200;if(tag==="main")b=150;' +
      'if(el.id&&/content|article|post|entry/i.test(el.id))b+=100;' +
      'if(el.className&&typeof el.className==="string"&&/content|article|post|entry/i.test(el.className))b+=80;' +
      'var p=0;if(/nav|header|footer|aside|form|sidebar|comment|social|share|related/i.test(tag+" "+(el.id||"")+" "+(el.className||"")))p=500;' +
      'return t.length+t.split(/[.!?]/).length*20+b-p;}' +
      'var cs=document.querySelectorAll("article,main,section,div,td");var best=null,bs=-1;' +
      'for(var i=0;i<cs.length;i++){var s=score(cs[i]);if(s>bs){bs=s;best=cs[i];}}' +
      'if(!best||bs<50)best=document.body;' +
      'function walk(el){if(!el)return"";var r="";' +
      'for(var i=0;i<el.children.length;i++){var c=el.children[i],tg=c.tagName.toLowerCase();' +
      'if(/script|style|nav|footer|aside|iframe|noscript/.test(tg))continue;' +
      'if(/^h[1-4]$/.test(tg)){r+="<"+tg+">"+c.innerText+"</"+tg+">";continue;}' +
      'if(tg==="img"){var s=c.getAttribute("src");if(s)r+="<img src=\\""+s+"\\" alt=\\""+(c.alt||"")+"\\">";continue;}' +
      'if(tg==="blockquote"){r+="<blockquote>"+c.innerText+"</blockquote>";continue;}' +
      'if(tg==="pre"){r+="<pre>"+c.innerText+"</pre>";continue;}' +
      'if(tg==="ul"||tg==="ol"){r+="<"+tg+">"+c.innerHTML+"</"+tg+">";continue;}' +
      'var tx=(c.innerText||"").trim();if(tx.length>20)r+="<p>"+tx+"</p>";' +
      '}return r;}' +
      'var t=document.querySelector("h1");t=t?t.innerText:document.title;' +
      'var a=document.querySelector("meta[name=\\"author\\"]");a=a?a.content:"";' +
      'var d=document.querySelector("time");d=d?d.getAttribute("datetime")||d.innerText:"";' +
      'return JSON.stringify({title:t,author:a,date:d,html:walk(best)});})()'
    ).then(function(result) {
      if (!result) return;
      var data = JSON.parse(result);
      if (!data.html || data.html.length < 20) { customAlert('Failed to extract content'); return; }
      readerTitle.textContent = data.title;
      readerContent.innerHTML = '<div class="reader-article">' +
        '<h1>' + escapeHtmlSimple(data.title || '') + '</h1>' +
        '<div class="reader-meta">' + escapeHtmlSimple([data.author, data.date].filter(Boolean).join(' · ')) + '</div>' +
        sanitizeInlineHtml(data.html) +
        '</div>';
      readerContent.style.fontFamily = readerFontSelect.value;
      readerContent.style.fontSize = readerFontSize + 'px';
      readerOverlay.classList.add('active');
      var bc = document.querySelector('.browser-content');
      if (bc) bc.style.visibility = 'hidden';
    }).catch(function(err) {
      customAlert('Reader mode error: ' + (err.message || err));
    });
  }

  function closeReader() {
    readerOverlay.classList.remove('active');
    readerOverlay.classList.remove('light');
    readerContent.innerHTML = '';
    var bc = document.querySelector('.browser-content');
    if (bc) bc.style.visibility = '';
  }

  window._toggleReader = toggleReader;
  document.getElementById('darkModeBtn').addEventListener('click', function() {
    // Click opens the professional Dark Reader panel (the master switch
    // inside does what the old single-purpose toggle did).
    var panel = document.getElementById('darkReaderPanel');
    if (!panel) return;
    var open = !panel.classList.contains('open');
    panel.classList.toggle('open', open);
    if (open && window._drSyncPanel) { try { window._drSyncPanel(); } catch(e) {} }
  });

  var qrScanBtn = document.getElementById('qrScanBtn');
  qrScanBtn.style.color = '#1da1f2';
  qrScanBtn.addEventListener('click', function() {
    _qrEnabled = !_qrEnabled;
    qrScanBtn.style.color = _qrEnabled ? '#1da1f2' : '';
    if (!_qrEnabled) {
      _qrStop();
    } else {
      _qrStart();
    }
  });
  readerClose.addEventListener('click', function(e) {
    e.preventDefault();
    e.stopPropagation();
    closeReader();
  });

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && readerOverlay.classList.contains('active')) {
      e.preventDefault();
      e.stopPropagation();
      closeReader();
    }
  });

  readerFontSelect.addEventListener('change', function() {
    readerContent.style.fontFamily = this.value;
  });
  readerFontMinus.addEventListener('click', function() {
    if (readerFontSize > 12) {
      readerFontSize -= 2;
      readerContent.style.fontSize = readerFontSize + 'px';
      readerSizeLabel.textContent = readerFontSize;
    }
  });
  readerFontPlus.addEventListener('click', function() {
    if (readerFontSize < 32) {
      readerFontSize += 2;
      readerContent.style.fontSize = readerFontSize + 'px';
      readerSizeLabel.textContent = readerFontSize;
    }
  });
  readerThemeToggle.addEventListener('click', function() {
    readerTheme = readerTheme === 'dark' ? 'light' : 'dark';
    readerOverlay.classList.toggle('light', readerTheme === 'light');
  });
})();

// ============== COLOR PICKER ==============
var _colorPickerActive = false;
var _cpRafId = null;
var _cpCapTimer = null;
var _cpPollTimer = null;
var _cpMouse = { x: -1, y: -1 };
var _cpCache = null;
var _cpCacheSize = null;
var _cpWvRect = null;
var _cpLastHex = '';
var _cpPending = false;

function _cpCreateUI() {
  if (document.getElementById('__cpWrap')) return;
  var wrap = document.createElement('div');
  wrap.id = '__cpWrap';
  wrap.style.cssText = 'position:fixed;z-index:99999;pointer-events:none;display:none;will-change:transform;';
  wrap.innerHTML =
    '<canvas id="__cpLoupe" width="120" height="120" style="width:120px;height:120px;border-radius:50%;border:3px solid rgba(255,255,255,0.5);box-shadow:0 2px 16px rgba(0,0,0,0.6);display:block"></canvas>' +
    '<div id="__cpInfo" style="margin-top:6px;display:flex;align-items:center;gap:8px;background:rgba(15,15,20,0.95);color:#fff;font:12px/1.3 monospace;padding:6px 12px;border-radius:6px;box-shadow:0 2px 12px rgba(0,0,0,0.5);white-space:nowrap">' +
    '<div id="__cpSw" style="width:18px;height:18px;border-radius:3px;border:1px solid rgba(255,255,255,0.3);flex-shrink:0"></div>' +
    '<span id="__cpHex" style="font-weight:700;font-size:13px"></span>' +
    '</div>';
  document.body.appendChild(wrap);
}

function _cpFrame() {
  if (!_colorPickerActive) return;
  _cpRafId = requestAnimationFrame(_cpFrame);
  if (_cpMouse.x < 0) return;
  var wrap = document.getElementById('__cpWrap');
  if (!wrap || !_cpWvRect) return;

  var px = _cpMouse.x;
  var py = _cpMouse.y;
  var ax = _cpWvRect.left + px + 24;
  var ay = _cpWvRect.top + py - 150;
  if (ax + 140 > window.innerWidth) ax = _cpWvRect.left + px - 155;
  if (ay < 4) ay = _cpWvRect.top + py + 24;
  wrap.style.transform = 'translate(' + ax + 'px,' + ay + 'px)';

  if (!_cpCache || !_cpCacheSize) return;
  var sx = Math.round(px * (_cpCacheSize.w / _cpWvRect.width));
  var sy = Math.round(py * (_cpCacheSize.h / _cpWvRect.height));
  sx = Math.max(0, Math.min(_cpCacheSize.w - 1, sx));
  sy = Math.max(0, Math.min(_cpCacheSize.h - 1, sy));

  var ctx = _cpCache.getContext('2d');
  try {
    var p = ctx.getImageData(sx, sy, 1, 1).data;
    var hex = '#' + [p[0], p[1], p[2]].map(function(v) {
      var h = v.toString(16); return h.length < 2 ? '0' + h : h;
    }).join('').toUpperCase();
    _cpLastHex = hex;
    var sw = document.getElementById('__cpSw');
    var hx = document.getElementById('__cpHex');
    if (sw) sw.style.background = hex;
    if (hx) hx.textContent = hex;
  } catch(e) {}

  var lc = document.getElementById('__cpLoupe');
  if (lc) {
    var lctx = lc.getContext('2d');
    var half = 10;
    lctx.imageSmoothingEnabled = false;
    lctx.clearRect(0, 0, 120, 120);
    lctx.save();
    lctx.beginPath();
    lctx.arc(60, 60, 58, 0, Math.PI * 2);
    lctx.clip();
    lctx.drawImage(_cpCache, sx - half, sy - half, half * 2, half * 2, 0, 0, 120, 120);
    lctx.restore();
    lctx.strokeStyle = '#fff';
    lctx.lineWidth = 2;
    lctx.beginPath();
    lctx.moveTo(60, 54); lctx.lineTo(60, 66);
    lctx.moveTo(54, 60); lctx.lineTo(66, 60);
    lctx.stroke();
  }
}

function _cpCapture() {
  var t = getActiveTab();
  if (!t || !t.webview) return;
  try { if (t.webview.isDestroyed && t.webview.isDestroyed()) return; } catch(e) { return; }
  t.webview.capturePage().then(function(img) {
    if (!img || img.isEmpty()) return;
    var size = img.getSize();
    if (!size || size.width < 1) return;
    var c = document.createElement('canvas');
    c.width = size.width;
    c.height = size.height;
    var ctx = c.getContext('2d');
    var imgEl = new Image();
    imgEl.onload = function() {
      ctx.drawImage(imgEl, 0, 0);
      _cpCache = c;
      _cpCacheSize = { w: size.width, h: size.height };
    };
    imgEl.src = img.toDataURL();
  }).catch(function() {});
}

function toggleColorPicker() {
  _colorPickerActive = !_colorPickerActive;
  var btn = document.getElementById('colorPickerBtn');
  if (btn) btn.classList.toggle('active', _colorPickerActive);
  _cpCreateUI();
  var wrap = document.getElementById('__cpWrap');

  if (_colorPickerActive) {
    wrap.style.display = 'block';
    wrap.style.left = '0';
    wrap.style.top = '0';
    var t = getActiveTab();
    if (!t || !t.webview || !canExecInWebview(t.webview)) return;
    _cpWvRect = t.webview.getBoundingClientRect();
    _cpCache = null;
    _cpMouse = { x: -1, y: -1 };
    // Inject NAMED, guarded handlers: the old anonymous capture listener kept
    // swallowing every click FOREVER after the picker finished (finishCP had
    // no way to remove it) — links on the page were dead until reload. The
    // __cpActive guard + named removal below fix both the leak and repeat
    // activation stacking multiple listeners.
    t.webview.executeJavaScript(
      '(function(){' +
      'window.__cpActive=true;' +
      'if(!window.__cpInstalled){window.__cpInstalled=true;' +
      'window.__cpOnMove=function(e){window.__cpMX=e.clientX;window.__cpMY=e.clientY;};' +
      'window.__cpOnClick=function(e){if(!window.__cpActive)return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();window.__cpClick=true;};' +
      'window.__cpOnKey=function(e){if(!window.__cpActive)return;if(e.key==="Escape")window.__cpEsc=true;};' +
      'document.addEventListener("mousemove",window.__cpOnMove,true);' +
      'document.addEventListener("click",window.__cpOnClick,true);' +
      'document.addEventListener("keydown",window.__cpOnKey,true);}' +
      '})()'
    ).catch(function() {});
    _cpCapture();
    _cpCapTimer = setInterval(_cpCapture, 1500);
    _cpRafId = requestAnimationFrame(_cpFrame);
    _cpPollTimer = setInterval(function() {
      if (_cpPending) return;
      var t = getActiveTab();
      if (!t || !t.webview || !canExecInWebview(t.webview)) { finishCP(); return; }
      _cpPending = true;
      t.webview.executeJavaScript(
        '(function(){var mx=window.__cpMX||0,my=window.__cpMY||0,cl=window.__cpClick||false,es=window.__cpEsc||false;if(cl)window.__cpClick=false;if(es)window.__cpEsc=false;return JSON.stringify({x:mx,y:my,click:cl,esc:es});})()'
      ).then(function(raw) {
        _cpPending = false;
        var d = JSON.parse(raw);
        if (d.esc) { finishCP(); return; }
        _cpMouse.x = d.x;
        _cpMouse.y = d.y;
        if (t.webview) _cpWvRect = t.webview.getBoundingClientRect();
        if (d.click) {
          if (_cpLastHex) {
            navigator.clipboard.writeText(_cpLastHex).catch(function() {});
            customAlert('Color copied: ' + _cpLastHex);
          }
          finishCP();
        }
      }).catch(function() { _cpPending = false; });
    }, 60);
  } else {
    finishCP();
  }
}

function finishCP() {
  _colorPickerActive = false;
  var btn = document.getElementById('colorPickerBtn');
  if (btn) btn.classList.remove('active');
  var wrap = document.getElementById('__cpWrap');
  if (wrap) wrap.style.display = 'none';
  if (_cpRafId) { cancelAnimationFrame(_cpRafId); _cpRafId = null; }
  if (_cpPollTimer) { clearInterval(_cpPollTimer); _cpPollTimer = null; }
  if (_cpCapTimer) { clearInterval(_cpCapTimer); _cpCapTimer = null; }
  _cpCache = null;
  _cpCacheSize = null;
  _cpPending = false;
  // Deactivate + remove the page-side capture listeners injected above
  // (best effort: tab may be gone — the __cpActive flag alone already
  // unblocks clicks even if the removal never runs).
  try {
    var t = getActiveTab();
    if (t && t.webview && canExecInWebview(t.webview)) {
      t.webview.executeJavaScript(
        '(function(){window.__cpActive=false;' +
        'if(window.__cpInstalled){document.removeEventListener("mousemove",window.__cpOnMove,true);' +
        'document.removeEventListener("click",window.__cpOnClick,true);' +
        'document.removeEventListener("keydown",window.__cpOnKey,true);' +
        'window.__cpInstalled=false;}})()'
      ).catch(function() {});
    }
  } catch(e) {}
}

// ============== BOOKMARKS SIDEBAR ==============
(function setupBookmarksSidebar() {
  var sidebarBtn = document.getElementById('sidebarBtn');
  var sidebar = document.getElementById('bookmarksSidebar');
  var sidebarOverlay = document.getElementById('sidebarOverlay');
  var sidebarClose = document.getElementById('sidebarClose');
  var sidebarAddFolder = document.getElementById('sidebarAddFolder');
  var sidebarList = document.getElementById('sidebarList');
  var sidebarEmpty = document.getElementById('sidebarEmpty');
  var sidebarSearch = document.getElementById('sidebarSearch');
  var _bookmarks = [];
  var _openFolders = {};

  function openSidebar() {
    sidebar.classList.add('open');
    sidebarOverlay.classList.add('active');
    loadBookmarks();
  }
  function closeSidebar() {
    sidebar.classList.remove('open');
    sidebarOverlay.classList.remove('active');
  }
  function toggleSidebar() {
    if (sidebar.classList.contains('open')) closeSidebar();
    else openSidebar();
  }
  // Shared toggle used by the customizable toolbar Bookmarks button and the
  // Quick Commands `:sidebar` command.
  window._toggleBookmarksSidebar = toggleSidebar;

  if (sidebarBtn) sidebarBtn.addEventListener('click', openSidebar);
  if (sidebarClose) sidebarClose.addEventListener('click', closeSidebar);
  if (sidebarOverlay) sidebarOverlay.addEventListener('click', closeSidebar);

  sidebarSearch.addEventListener('input', function() {
    renderBookmarks(this.value.toLowerCase());
  });

  sidebarAddFolder.addEventListener('click', function() {
    customPrompt('Folder name:').then(function(name) {
      if (!name) return;
      if (window.electronAPI && window.electronAPI.addBookmark) {
        window.electronAPI.addBookmark({ url: '', title: name, folder: '__folder__' }).then(function() {
          loadBookmarks();
        });
      }
    });
  });

  function loadBookmarks() {
    if (!window.electronAPI || !window.electronAPI.loadBookmarks) return;
    window.electronAPI.loadBookmarks().then(function(bm) {
      _bookmarks = bm || [];
      renderBookmarks(sidebarSearch.value.toLowerCase());
    });
  }

  function renderBookmarks(filter) {
    sidebarList.innerHTML = '';
    var items = _bookmarks;
    if (filter) {
      items = items.filter(function(b) {
        return (b.title || b.url || '').toLowerCase().indexOf(filter) > -1;
      });
    }

    var folders = {};
    var rootItems = [];
    items.forEach(function(b) {
      if (b.folder === '__folder__') {
        folders[b.id] = { folder: b, items: [] };
      } else if (b.folder && b.folder !== '') {
        if (!folders[b.folder]) folders[b.folder] = { folder: null, items: [] };
        folders[b.folder].items.push(b);
      } else {
        rootItems.push(b);
      }
    });

    if (items.length === 0) {
      sidebarEmpty.style.display = 'block';
      return;
    }
    sidebarEmpty.style.display = 'none';

    Object.keys(folders).forEach(function(fId) {
      var f = folders[fId];
      if (!f.folder) return;
      var isOpen = _openFolders[f.folder.id];
      var header = document.createElement('div');
      header.className = 'sidebar-folder-header';
      header.innerHTML = '<span class="sidebar-folder-arrow' + (isOpen ? ' open' : '') + '">▶</span>' +
        '<span>' + _icon('📁') + ' ' + escapeHtmlSimple(f.folder.title || 'Folder') + '</span>';
      header.addEventListener('click', function() {
        _openFolders[f.folder.id] = !_openFolders[f.folder.id];
        renderBookmarks(filter);
      });
      sidebarList.appendChild(header);

      if (isOpen) {
        var container = document.createElement('div');
        container.className = 'sidebar-folder-items';
        f.items.forEach(function(bm) {
          container.appendChild(createBookmarkItem(bm));
        });
        sidebarList.appendChild(container);
      }
    });

    rootItems.forEach(function(bm) {
      if (bm.folder === '__folder__') return;
      sidebarList.appendChild(createBookmarkItem(bm));
    });
  }

  function createBookmarkItem(bm) {
    var div = document.createElement('div');
    div.className = 'sidebar-item';
    var domain = '';
    try { domain = bm.url ? new URL(bm.url).hostname : ''; } catch(e) {}
    var favicon = domain ? spzFaviconUrl(domain) : '';
    div.innerHTML =
      '<span class="sidebar-item-icon">' + (favicon ? '<img src="' + favicon + '" alt="">' : _icon('🔗')) + '</span>' +
      '<div class="sidebar-item-text">' +
        '<div class="sidebar-item-name">' + escapeHtmlSimple(bm.title || bm.url || 'Untitled') + '</div>' +
        '<div class="sidebar-item-url">' + escapeHtmlSimple(domain || bm.url || '') + '</div>' +
      '</div>' +
      '<button class="sidebar-item-del" title="Delete">' + _icon('✕') + '</button>';
    // Favicon fallback: no inline onerror (CSP forbids it and the SVG quotes
    // broke the attribute) — attach the handler from JS instead.
    var favImg = div.querySelector('.sidebar-item-icon img');
    if (favImg) {
      favImg.onerror = function() {
        try { this.outerHTML = _icon('🔗'); } catch (e) { this.remove(); }
      };
    }
    div.addEventListener('click', function(e) {
      if (e.target.closest('.sidebar-item-del')) return;
      if (bm.url) {
        createNewTab(bm.url);
        closeSidebar();
      }
    });
    div.querySelector('.sidebar-item-del').addEventListener('click', function() {
      if (window.electronAPI && window.electronAPI.removeBookmark) {
        window.electronAPI.removeBookmark(bm.id).then(function() { loadBookmarks(); });
      }
    });
    return div;
  }
})();

// ============== SPLIT VIEW ==============
var _splitActive = false;
var _splitTab2 = null;
var _splitTab2Id = null;
var _splitPct = 50;
(function setupSplitView() {
  var splitBtn = document.getElementById('splitBtn');
  var splitDivider = document.getElementById('splitDivider');
  var browserContent = document.querySelector('.browser-content');
  var _splitDragging = false;

  splitBtn.addEventListener('click', function() {
    if (_splitActive) closeSplit();
    else openSplit();
  });

  document.getElementById('newTabBarBtn').addEventListener('click', function() { createNewTab(); });
  document.getElementById('bookmarksBtn').addEventListener('click', function() { if (window._toggleBookmarksSidebar) window._toggleBookmarksSidebar(); });
  document.getElementById('historyBtn').addEventListener('click', function() { createNewTab('Library.html#history'); });
  document.getElementById('readerBtn').addEventListener('click', function() { if (window._toggleReader) window._toggleReader(); });
  var _ttsBtnEl = document.getElementById('ttsBtn');
  if (_ttsBtnEl) _ttsBtnEl.addEventListener('click', function() { if (window._ttsToggle) window._ttsToggle(); });
  document.getElementById('screenshotBtn').addEventListener('click', function() { openScreenshotTool(); });
  document.getElementById('incognitoBtn').addEventListener('click', function() { if (window.startIncognitoMode) window.startIncognitoMode(); });
  document.getElementById('translateBtn').addEventListener('click', function() {
    var t = tabs.find(function(tt) { return tt.id === activeTabId; });
    if (t && t.webview && t.isReady && canExecInWebview(t.webview)) {
      t.webview.executeJavaScript('window.getSelection().toString()').then(function(sel) {
        var text = sel || '';
        if (text) {
          if (window.electronAPI && window.electronAPI.translateText) {
            window.electronAPI.translateText(text, 'auto', 'ru').then(function(r) { if (r && r.success && r.translated) customAlert('Translate:\n' + r.translated); }).catch(function() {});
          }
        } else {
          customPrompt('Text to translate:').then(function(input) {
            if (input && window.electronAPI && window.electronAPI.translateText) {
              window.electronAPI.translateText(input, 'auto', 'ru').then(function(r) { if (r && r.success && r.translated) customAlert('Translate:\n' + r.translated); }).catch(function() {});
            }
          });
        }
      }).catch(function() {});
    }
  });
  document.getElementById('findAllBtn').addEventListener('click', function() {
    var t2 = tabs.find(function(tt) { return tt.id === activeTabId; });
    if (t2 && t2.webview && t2.isReady && canExecInWebview(t2.webview)) {
      t2.webview.executeJavaScript('window.getSelection().toString()').then(function(sel) {
        if (typeof toggleFindAll === 'function') toggleFindAll(sel || '');
      }).catch(function() { if (typeof toggleFindAll === 'function') toggleFindAll(''); });
    } else {
      if (typeof toggleFindAll === 'function') toggleFindAll('');
    }
  });
  document.getElementById('autoscrollBtn').addEventListener('click', function() {
    if (_autoscrollActive) stopAutoscroll(); else startAutoscroll();
  });

  var vtabNewBtn = document.getElementById('vtabNewBtn');
  if (vtabNewBtn) {
    vtabNewBtn.addEventListener('click', function() { createNewTab(); });
  }

  function showTabPicker(callback) {
    var overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);z-index:10000;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(8px);';

    var panel = document.createElement('div');
    panel.style.cssText = 'background:rgba(40,40,55,0.95);border:1px solid rgba(255,255,255,0.15);border-radius:16px;padding:24px;width:380px;max-height:70vh;overflow-y:auto;color:white;font-family:system-ui,sans-serif;';

    var title = document.createElement('h3');
    title.textContent = 'Select a tab for the second panel';
    title.style.cssText = 'margin:0 0 16px;font-size:16px;font-weight:600;';
    panel.appendChild(title);

    var otherTabs = tabs.filter(function(t) { return t.id !== activeTabId; });
    if (otherTabs.length > 0) {
      otherTabs.forEach(function(t) {
        var item = document.createElement('div');
        item.style.cssText = 'padding:10px 14px;border-radius:8px;cursor:pointer;margin-bottom:6px;border:1px solid rgba(255,255,255,0.1);transition:background 0.15s;display:flex;align-items:center;gap:10px;';
        var icon = document.createElement('span');
        icon.innerHTML = _icon('\uD83C\uDF10');
        icon.style.fontSize = '14px';
        icon.style.display = 'inline-flex';
        var label = document.createElement('span');
        label.textContent = t.title || 'New tab';
        label.style.cssText = 'flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;';
        item.appendChild(icon);
        item.appendChild(label);
        item.addEventListener('mouseenter', function() { item.style.background = 'rgba(255,255,255,0.1)'; });
        item.addEventListener('mouseleave', function() { item.style.background = ''; });
        item.addEventListener('click', function() {
          document.body.removeChild(overlay);
          callback(t.id);
        });
        panel.appendChild(item);
      });
    }

    var urlBtn = document.createElement('div');
    urlBtn.style.cssText = 'padding:10px 14px;border-radius:8px;cursor:pointer;margin-bottom:6px;border:1px dashed rgba(255,255,255,0.25);transition:background 0.15s;display:flex;align-items:center;gap:10px;';
    var urlIcon = document.createElement('span');
    urlIcon.textContent = '\u2795';
    urlIcon.style.fontSize = '14px';
    var urlLabel = document.createElement('span');
    urlLabel.textContent = 'Enter URL...';
    urlLabel.style.cssText = 'font-size:14px;';
    urlBtn.appendChild(urlIcon);
    urlBtn.appendChild(urlLabel);
    urlBtn.addEventListener('mouseenter', function() { urlBtn.style.background = 'rgba(255,255,255,0.1)'; });
    urlBtn.addEventListener('mouseleave', function() { urlBtn.style.background = ''; });
    urlBtn.addEventListener('click', function() {
      document.body.removeChild(overlay);
      customPrompt('URL for second panel:').then(function(url2) {
        if (url2 && url2.trim()) {
          if (!/^https?:\/\//i.test(url2)) url2 = 'https://' + url2;
          callback(null, url2.trim());
        }
      });
    });
    panel.appendChild(urlBtn);

    var cancelBtn = document.createElement('div');
    cancelBtn.textContent = 'Cancel';
    cancelBtn.style.cssText = 'padding:10px 14px;border-radius:8px;cursor:pointer;margin-top:8px;text-align:center;color:rgba(255,255,255,0.5);font-size:13px;transition:color 0.15s;';
    cancelBtn.addEventListener('mouseenter', function() { cancelBtn.style.color = 'white'; });
    cancelBtn.addEventListener('mouseleave', function() { cancelBtn.style.color = 'rgba(255,255,255,0.5)'; });
    cancelBtn.addEventListener('click', function() { document.body.removeChild(overlay); });
    panel.appendChild(cancelBtn);

    overlay.appendChild(panel);
    document.body.appendChild(overlay);
  }

  function openSplit() {
    var tab = getActiveTab();
    if (!tab) return;

    showTabPicker(function(chosenTabId, customUrl) {
      _splitActive = true;
      _splitPct = 50;
      browserContent.classList.add('split-active');
      splitDivider.classList.add('active');

      tab.webview.style.cssText = 'position:absolute;top:0;left:0;width:calc(50% - 3px);height:100%;display:flex;';

      var wv2 = document.createElement('webview');
      wv2.id = 'split-wv-' + Date.now();
      wv2.setAttribute('autosize', 'on');
      wv2.setAttribute('allowpopups', '');
      wv2.setAttribute('webpreferences', 'backgroundThrottling=false');
      if (webviewPreloadPath) wv2.setAttribute('preload', webviewPreloadPath);
      wv2.style.cssText = 'position:absolute;top:0;left:calc(50% + 3px);width:calc(50% - 3px);height:100%;display:flex;';
      browserContent.appendChild(wv2);

      _splitTab2 = { webview: wv2, isReady: false };
      wv2.addEventListener('dom-ready', function() {
        _splitTab2.isReady = true;
        try { if (wv2.setUserAgent) wv2.setUserAgent(userAgent); } catch(e) {}
      });
      wv2.addEventListener('did-finish-load', function() { _splitTab2.isReady = true; });

      if (chosenTabId) {
        var chosenTab = tabs.find(function(t) { return t.id === chosenTabId; });
        if (chosenTab) {
          var url2 = '';
          if (chosenTab.pendingUrl) {
            url2 = chosenTab.pendingUrl;
          } else {
            try { url2 = chosenTab.webview.getURL ? chosenTab.webview.getURL() : (chosenTab.webview.src || ''); } catch(e) { url2 = chosenTab.webview.src || ''; }
          }
          if (!url2 || url2 === 'about:blank') url2 = 'https://www.google.com';
          wv2.src = url2;
          _splitTab2Id = chosenTabId;
        }
      } else if (customUrl) {
        wv2.src = customUrl;
        _splitTab2Id = null;
      }

      splitDivider.style.left = 'calc(50% - 3px)';
      splitDivider.addEventListener('mousedown', startDrag);
    });
  }

  function startDrag(e) {
    _splitDragging = true;
    splitDivider.classList.add('dragging');
    e.preventDefault();
  }

  document.addEventListener('mousemove', function(e) {
    if (!_splitDragging) return;
    var bc = document.querySelector('.browser-content');
    if (!bc) return;
    var rect = bc.getBoundingClientRect();
    var pct = ((e.clientX - rect.left) / rect.width) * 100;
    pct = Math.max(20, Math.min(80, pct));
    _splitPct = pct;

    var tab = getActiveTab();
    if (tab) {
      tab.webview.style.left = '0';
      tab.webview.style.width = 'calc(' + pct + '% - 3px)';
    }
    splitDivider.style.left = 'calc(' + pct + '% - 3px)';
    if (_splitTab2 && _splitTab2.webview) {
      _splitTab2.webview.style.left = 'calc(' + pct + '% + 3px)';
      _splitTab2.webview.style.width = 'calc(' + (100 - pct) + '% - 3px)';
    }
  });

  document.addEventListener('mouseup', function() {
    if (_splitDragging) {
      _splitDragging = false;
      splitDivider.classList.remove('dragging');
    }
  });

  function closeSplit() {
    _splitActive = false;
    _splitPct = 50;
    splitDivider.classList.remove('active');
    browserContent.classList.remove('split-active');
    splitDivider.removeEventListener('mousedown', startDrag);
    if (_splitTab2 && _splitTab2.webview) {
      _splitTab2.webview.remove();
    }
    _splitTab2 = null;
    _splitTab2Id = null;
    var tab = getActiveTab();
    if (tab) {
      tab.webview.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;display:flex;';
    }
    setActiveTab(activeTabId);
  }
})();

// ============== TAB TEAR-OUT (drag a tab out of the window) ==============
// Three independent paths, because no single one works everywhere:
//   A (primary, all platforms): releasing the drag anywhere OUTSIDE the tab
//     strip (page content, navbar, bottom of the window) detaches the tab —
//     Chrome-style. All events carry reliable in-window coordinates. While a
//     tab drag is active, webviews get pointer-events:none so the host (not
//     the guest page) receives the dragover/drop.
//   B: the main-process cursor poller (works on X11; on Wayland cursor
//     queries are frozen, so it stays silent there).
//   C: dragend + outside-cursor check (platforms where dragend fires for
//     outside releases).
var _tearDragActive = null;
var _tearDropHandled = false;
var _tearHintEl = null;

function _tearShowHint() {
  if (!_tearHintEl) {
    _tearHintEl = document.createElement('div');
    _tearHintEl.id = 'tearOutHint';
    _tearHintEl.textContent = 'Release to open tab in a new window';
    document.body.appendChild(_tearHintEl);
  }
  _tearHintEl.classList.add('visible');
}
function _tearHideHint() {
  if (_tearHintEl) _tearHintEl.classList.remove('visible');
}

function _tearBeginDrag(tabId, e, meta) {
  _tearDragActive = tabId;
  _tearDropHandled = false;
  // Webviews must not swallow the drop — the host document handles it.
  document.body.classList.add('tear-dragging');
  // Cross-window move: the payload lets ANOTHER shell window accept this
  // drag (custom MIME types survive the native drag loop between windows).
  if (e && e.dataTransfer && meta) {
    try {
      e.dataTransfer.setData('application/x-startpozi-tab', JSON.stringify({
        v: 1,
        tabId: tabId,
        url: meta.url || '',
        title: meta.title || '',
        incognito: !!meta.incognito,
        partition: meta.partition || ''
      }));
    } catch(err) {}
  }
  // Path B: main process starts watching the cursor.
  if (window.electronAPI && window.electronAPI.tabDragStarted) {
    try { window.electronAPI.tabDragStarted(tabId); } catch(err) {}
  }
}

function _tearEndDrag(e, tabId) {
  var wasActive = _tearDragActive;
  _tearDragActive = null;
  _tearHideHint();
  document.body.classList.remove('tear-dragging');
  if (window.electronAPI && window.electronAPI.tabDragEnded) {
    try { window.electronAPI.tabDragEnded(); } catch(err) {}
  }
  // Path C fallback: drag ended with no drop anywhere (released outside on
  // platforms where dragend fires there, or a cancelled drag).
  if (wasActive && !_tearDropHandled) _maybeTearOutAfterDrag(e, tabId);
}

function _tearInStrip(target) {
  return !!(target && target.closest && target.closest('.tabs-bar'));
}

// Path A: the whole window except the tab strip is a detach drop-zone.
document.addEventListener('dragover', function(e) {
  if (!_tearDragActive) return;
  if (!_tearInStrip(e.target)) {
    // Cancel dragover so a drop is allowed here; signal the intent.
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
    _tearShowHint();
  } else {
    _tearHideHint();
  }
}, true);

// Suspect-certificate swap: when the main process records a certificate
// problem for a host (the verify proc holds the verdict instead of rejecting
// it — rejections are cached per session and would make a later "Proceed"
// impossible), every tab currently navigating to that host is rerouted to the
// security page BEFORE the content renders.
(function setupSuspectCertSwap() {
  if (window.electronAPI && window.electronAPI.onSuspectCertsChanged) {
    window.electronAPI.onSuspectCertsChanged(function(hosts) {
      try {
        if (!hosts || typeof hosts !== 'object') return;
        tabs.forEach(function(t) {
          if (!t || !t.webview) return;
          var u = '';
          try { u = t.webview.src || ''; } catch(e) { return; }
          if (!u || u.indexOf('https://') !== 0) return;
          var h = '';
          try { h = new URL(u).hostname; } catch(e) { return; }
          if (!h || !Object.prototype.hasOwnProperty.call(hosts, h)) return;
          // Already showing the security page for this host? (its src is a
          // file:// URL then, so the https:// check above already skipped it)
          t._lastFailedUrl = u;
          var secUrl = window.location.href.replace(/\/[^/]*$/, '/') + 'ErrorPage/security.html' +
            '?url=' + encodeURIComponent(u) +
            '&reason=' + encodeURIComponent(hosts[h] || 'unknown');
          try { t.webview.src = secUrl; } catch(e) {}
          if (t.id === activeTabId) { _urlBarRevealed = false; setUrlBarDisplay(u); }
        });
      } catch(e) {}
    });
  }
})();

// ============== FILE DROP ON TAB STRIP ==============
// Drag an HTML (or any viewable) file onto the tab bar to open it in a new
// tab. Uses screen coordinates to detect the tab-bar zone (the actual event
// target can be a webview which swallows drags). Webviews get
// pointer-events:none during the drag — same approach as tear-out.
var _fileDropIndicator = null;
var _fileDropActive = false;

function _fileDropHasFiles(e) {
  try {
    return !!(e.dataTransfer && e.dataTransfer.types &&
      Array.from(e.dataTransfer.types).indexOf('Files') !== -1);
  } catch (err) { return false; }
}

// Dragged LINKS / plain text (from other apps, or from a page): open as a
// new tab. Internal drags are excluded — own tab drags are covered by the
// _tearDragActive guard, cross-window tab moves carry the custom MIME, and
// toolbar-customization pool items mark themselves with .dragging.
// ALL of the browser's own customize-mode drags are excluded the same way:
// they carry internal ids in text/plain ('hmSettings', 'library'…) and,
// dropped anywhere, opened a SEARCH for that id; the capture-phase drop
// interception below also killed the customize drop zones themselves.
function _fileDropHasUrl(e) {
  try {
    if (_tearDragActive) return false;
    if (typeof _customizeActive !== 'undefined' && _customizeActive) return false;
    if (window._menuCustomizeModeActive && window._menuCustomizeModeActive()) return false;
    var t = e.dataTransfer && e.dataTransfer.types;
    if (!t) return false;
    var arr = Array.from(t);
    if (arr.indexOf('application/x-startpozi-tab') !== -1) return false;
    // Drags started on the browser's own internal pages (marked by
    // preload-webview) — never "dropped links/text".
    if (arr.indexOf('application/x-startpozi-ui-drag') !== -1) return false;
    if (document.querySelector('.customize-pool-item.dragging,.toolbar-btn-slot.dragging,.nav-btn.dragging,.hm-item.dragging,.hm-cust-chip.dragging')) return false;
    return arr.indexOf('text/uri-list') !== -1 ||
           (arr.indexOf('Files') === -1 && arr.indexOf('text/plain') !== -1);
  } catch (err) { return false; }
}

function _fileDropAcceptable(e) {
  return _fileDropHasFiles(e) || _fileDropHasUrl(e);
}

function _urlFromDataTransfer(dt) {
  try {
    var uri = dt.getData('text/uri-list');
    if (uri) {
      uri = uri.split('\n')[0].trim(); // comments start with '#'
      if (uri && uri.charAt(0) !== '#') return uri;
    }
    return (dt.getData('text/plain') || '').trim();
  } catch (err) { return ''; }
}

// Open a dropped link/text: http(s)/ftp/file/about → as-is; "site.com" →
// https://; anything else → search for the phrase (Firefox-style drop).
function _openDroppedText(raw) {
  try {
    if (!raw) return;
    var s = String(raw).split('\n')[0].trim();
    if (!s) return;
    if (/^(https?|ftp|file):\/\//i.test(s) || /^about:/i.test(s)) {
      createNewTab(s);
      return;
    }
    if (!/\s/.test(s) && s.indexOf('.') !== -1) {
      createNewTab('https://' + s);
      return;
    }
    createNewTab(buildSearchUrl(s));
  } catch (err) {}
}

function _inTabStripZone(e) {
  try {
    var bar = document.querySelector('.tabs-bar');
    if (!bar) return false;
    var rect = bar.getBoundingClientRect();
    return e.clientY >= rect.top - 8 && e.clientY <= rect.bottom + 8 &&
           e.clientX >= rect.left && e.clientX <= rect.right;
  } catch (err) { return false; }
}

function _fileDropShow() {
  if (!_fileDropIndicator) {
    _fileDropIndicator = document.createElement('div');
    _fileDropIndicator.id = 'fileDropHint';
    _fileDropIndicator.innerHTML = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg><span>Drop to open</span>';
    document.body.appendChild(_fileDropIndicator);
  }
  _fileDropIndicator.classList.add('visible');
  _fileDropActive = true;
  document.body.classList.add('file-drop-hover');
  if (!_tearDragActive) document.body.classList.add('tear-dragging');
}

function _fileDropHide() {
  if (_fileDropIndicator) _fileDropIndicator.classList.remove('visible');
  _fileDropActive = false;
  document.body.classList.remove('file-drop-hover');
  if (!_tearDragActive) document.body.classList.remove('tear-dragging');
}

document.addEventListener('dragenter', function(e) {
  if (_tearDragActive) return;
  if (!_fileDropAcceptable(e)) return;
  e.preventDefault();
}, true);

document.addEventListener('dragover', function(e) {
  if (_tearDragActive) return;
  if (!_fileDropAcceptable(e)) return;
  e.preventDefault();
  // Files are accepted on the tab strip only; links/text anywhere on the
  // browser chrome (dropping over a page stays native — the guest navigates
  // itself, exactly like Chrome).
  if (_inTabStripZone(e) || _fileDropHasUrl(e)) {
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
    _fileDropShow();
  } else {
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'none';
    _fileDropHide();
  }
}, true);

document.addEventListener('dragleave', function(e) {
  if (!_fileDropActive) return;
  if (e.relatedTarget === null || !document.contains(e.relatedTarget)) {
    _fileDropHide();
  }
}, true);

document.addEventListener('drop', function(e) {
  if (!_fileDropActive || _tearDragActive) return;
  e.preventDefault();
  e.stopPropagation();
  _fileDropHide();
  var files = e.dataTransfer ? e.dataTransfer.files : null;
  if (!files || !files.length) {
    // No files — a dragged link/text: open it as a new tab.
    _openDroppedText(_urlFromDataTransfer(e.dataTransfer || {}));
    return;
  }
  for (var fi = 0; fi < files.length; fi++) {
    var f = files[fi];
    if (!f || !f.path) continue;
    var ext = (f.name || '').split('.').pop().toLowerCase();
    var openable = ['html', 'htm', 'xhtml', 'svg', 'md', 'markdown', 'txt',
                    'json', 'geojson', 'har', 'xml', 'css', 'js', 'pdf',
                    'png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'avif', 'ico',
                    'ttf', 'otf', 'woff', 'woff2'].indexOf(ext) !== -1;
    if (openable) {
      createNewTab('file://' + f.path.replace(/\\/g, '/'));
    }
  }
}, true);

document.addEventListener('drop', function(e) {
  if (!_tearDragActive) return;
  if (_tearInStrip(e.target)) {
    _tearDropHandled = true; // reorder drop — let the tab's own handler run
    return;
  }
  e.preventDefault();
  e.stopPropagation();
  _tearDropHandled = true;
  var id = _tearDragActive;
  _tearDragActive = null;
  _tearHideHint();
  document.body.classList.remove('tear-dragging');
  if (window.electronAPI && window.electronAPI.tabDragEnded) {
    try { window.electronAPI.tabDragEnded(); } catch(err) {}
  }
  _tearOutTab(id, { x: e.screenX, y: e.screenY });
}, true);

function _maybeTearOutAfterDrag(e, tabId) {
  try {
    if (!window.electronAPI || !window.electronAPI.isCursorOutsideWindow) return;
    window.electronAPI.isCursorOutsideWindow().then(function(outside) {
      if (!outside) return;
      // Delayed: when the tab was dropped INTO another shell window, the
      // cross-window move notice arrives within milliseconds — creating a
      // duplicate new window then would be wrong. If the tab is already
      // gone from this window, the move won the race.
      setTimeout(function() {
        var stillHere = tabs.some(function(t) { return t.id === tabId; }) ||
          (typeof _incognitoTabs !== 'undefined' && _incognitoTabs.some(function(t) { return t.id === tabId; }));
        if (stillHere && typeof _tearOutTab === 'function') _tearOutTab(tabId);
      }, 250);
    }).catch(function() {});
  } catch(err) {}
}

// ===== CROSS-WINDOW TAB MOVE (drop a tab onto another shell window) =====
var _foreignTabOver = false;
function _isForeignTabDrag(e) {
  if (_tearDragActive) return false; // our own drag — not a foreign one
  try {
    var t = e.dataTransfer && e.dataTransfer.types;
    if (!t || !t.length) return false;
    for (var i = 0; i < t.length; i++) {
      if (t[i] === 'application/x-startpozi-tab') return true;
    }
  } catch(err) {}
  return false;
}

// Accept a tab dragged from another window. Highlight the tab strip and let
// webviews become transparent to the drag so the drop lands on the host.
document.addEventListener('dragover', function(e) {
  if (!_isForeignTabDrag(e)) return;
  e.preventDefault();
  if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
  if (!_foreignTabOver) {
    _foreignTabOver = true;
    document.body.classList.add('foreign-tab-over');
  }
}, true);

document.addEventListener('dragleave', function(e) {
  if (_foreignTabOver && !e.relatedTarget) {
    _foreignTabOver = false;
    document.body.classList.remove('foreign-tab-over');
  }
}, true);

document.addEventListener('drop', function(e) {
  if (!_foreignTabOver) return;
  var raw = '';
  try { raw = e.dataTransfer.getData('application/x-startpozi-tab'); } catch(err) {}
  _foreignTabOver = false;
  document.body.classList.remove('foreign-tab-over');
  if (!raw) return;
  var d = null;
  try { d = JSON.parse(raw); } catch(err) {}
  if (!d || d.v !== 1 || !d.tabId || !d.url) return;
  e.preventDefault();
  e.stopPropagation();
  // Create the tab here, then ask the main process to tell the source
  // window to drop it (no new window, no incognito partition wipe — the
  // session simply moves here).
  if (d.incognito) {
    if (window.createIncognitoTab) {
      window.createIncognitoTab(d.url, d.partition ? { partition: d.partition } : undefined);
    }
  } else {
    createNewTab(d.url);
  }
  if (window.electronAPI && window.electronAPI.moveTabToWindow) {
    try { window.electronAPI.moveTabToWindow({ tabId: d.tabId }); } catch(err) {}
  }
}, true);

// The drag ended somewhere without a dragend (dropped into another window,
// Wayland quirk) — any later click restores normal state.
document.addEventListener('mousedown', function() {
  if (_tearDragActive) {
    _tearDragActive = null;
    _tearDropHandled = true;
    _tearHideHint();
    document.body.classList.remove('tear-dragging', 'foreign-tab-over');
    if (window.electronAPI && window.electronAPI.tabDragEnded) {
      try { window.electronAPI.tabDragEnded(); } catch(err) {}
    }
  }
  if (_foreignTabOver) {
    _foreignTabOver = false;
    document.body.classList.remove('foreign-tab-over');
  }
}, true);

function _tearOutTab(tabId, cursorPos) {
  cursorPos = cursorPos || {};
  // Regular tabs
  var idx = tabs.findIndex(function(t) { return t.id === tabId; });
  if (idx !== -1) {
    var tab = tabs[idx];
    var url = getTabUrlForSave(tab);
    if ((!url || url === 'about:blank') && tab._sleepUrl) url = tab._sleepUrl;
    if (!url || url === 'about:blank') return;
    var title = tab.title || '';
    var wasActive = (tabId === activeTabId);
    // Manual removal — closeTab() refuses to close the last tab, but tearing
    // out the last tab is legal (the window gets a fresh start page).
    try { tab.element.remove(); } catch(e) {}
    try { tab.webview.remove(); } catch(e) {}
    delete _tabPreviewCache[tabId];
    delete _tabAudioPlaying[tabId];
    delete _tabMuted[tabId];
    delete _tabZoom[tabId];
    if (_tabSleepTimers[tabId]) { clearTimeout(_tabSleepTimers[tabId]); delete _tabSleepTimers[tabId]; }
    try { stopLoadingBar(tabId); } catch(e) {}
    tabs.splice(idx, 1);
    if (wasActive) {
      if (tabs.length) setActiveTab(tabs[Math.min(idx, tabs.length - 1)].id);
      else createNewTab('MainPage/index.html');
    }
    // Persist immediately (not debounced) so the primary session never
    // resurrects the moved tab.
    try { autoSaveTabs(); } catch(e) {}
    if (window.electronAPI && window.electronAPI.openWindowWithTab) {
      window.electronAPI.openWindowWithTab(url, { title: title, x: cursorPos.x, y: cursorPos.y });
    }
    return;
  }
  // Incognito tabs: remove WITHOUT wiping the partition — the session moves
  // to the new incognito window.
  if (typeof _incognitoTabs !== 'undefined') {
    var iIdx = _incognitoTabs.findIndex(function(t) { return t.id === tabId; });
    if (iIdx !== -1) {
      var itab = _incognitoTabs[iIdx];
      var iurl = '';
      try { iurl = itab.webview.getURL ? itab.webview.getURL() : (itab.webview.src || ''); } catch(e) {}
      if ((!iurl || iurl === 'about:blank') && itab._sleepUrl) iurl = itab._sleepUrl;
      if (!iurl || iurl === 'about:blank') return;
      var partition = itab.partition;
      var iTitle = '';
      try {
        var tEl = itab.element.querySelector('.tab-title');
        if (tEl) iTitle = (tEl.textContent || '').trim();
      } catch(e) {}
      try { itab.element.remove(); } catch(e) {}
      try { itab.webview.remove(); } catch(e) {}
      _incognitoTabs.splice(iIdx, 1);
      if (_activeIncognitoId === tabId) {
        _activeIncognitoId = null;
        if (_incognitoTabs.length) switchToIncognitoTab(_incognitoTabs[_incognitoTabs.length - 1].id);
        else if (tabs.length) setActiveTab(tabs[tabs.length - 1].id);
        else createNewTab('MainPage/index.html');
      }
      if (window.electronAPI && window.electronAPI.openWindowWithTab) {
        window.electronAPI.openWindowWithTab(iurl, { title: iTitle, incognito: true, partition: partition, x: cursorPos.x, y: cursorPos.y });
      }
    }
  }
}

// Primary tear-off path: the main-process cursor poller detected the dragged
// tab leaving the window (fires on every platform, including Linux where
// dragend never fires for outside releases). The tab may already be gone if
// the secondary dragend path won the race — _tearOutTab no-ops then.
if (window.electronAPI && window.electronAPI.onTearOutTab) {
  window.electronAPI.onTearOutTab(function(d) {
    if (d && d.tabId && typeof _tearOutTab === 'function') {
      _tearOutTab(d.tabId, { x: d.x, y: d.y });
    }
  });
}

// This window's tab was dropped INTO another shell window: remove it here
// silently — no new window, and for incognito tabs NO partition wipe, the
// session now lives in the window that accepted the drop.
if (window.electronAPI && window.electronAPI.onCloseForeignDroppedTab) {
  window.electronAPI.onCloseForeignDroppedTab(function(d) {
    var tabId = d && d.tabId;
    if (!tabId) return;
    // Restore chrome state if this window still thinks the drag is running.
    if (_tearDragActive === tabId) {
      _tearDragActive = null;
      _tearDropHandled = true;
      _tearHideHint();
      document.body.classList.remove('tear-dragging');
      if (window.electronAPI && window.electronAPI.tabDragEnded) {
        try { window.electronAPI.tabDragEnded(); } catch(err) {}
      }
    }
    var idx = tabs.findIndex(function(t) { return t.id === tabId; });
    if (idx !== -1) {
      var tab = tabs[idx];
      var wasActive = (tabId === activeTabId);
      try { tab.element.remove(); } catch(e) {}
      try { tab.webview.remove(); } catch(e) {}
      delete _tabPreviewCache[tabId];
      delete _tabAudioPlaying[tabId];
      delete _tabMuted[tabId];
      delete _tabZoom[tabId];
      if (_tabSleepTimers[tabId]) { clearTimeout(_tabSleepTimers[tabId]); delete _tabSleepTimers[tabId]; }
      try { stopLoadingBar(tabId); } catch(e) {}
      tabs.splice(idx, 1);
      if (wasActive) {
        if (tabs.length) setActiveTab(tabs[Math.min(idx, tabs.length - 1)].id);
        else createNewTab('MainPage/index.html');
      }
      try { autoSaveTabs(); } catch(e) {}
      return;
    }
    if (typeof _incognitoTabs !== 'undefined') {
      var iIdx = _incognitoTabs.findIndex(function(t) { return t.id === tabId; });
      if (iIdx !== -1) {
        var itab = _incognitoTabs[iIdx];
        try { itab.element.remove(); } catch(e) {}
        try { itab.webview.remove(); } catch(e) {}
        _incognitoTabs.splice(iIdx, 1);
        if (_activeIncognitoId === tabId) {
          _activeIncognitoId = null;
          if (_incognitoTabs.length) switchToIncognitoTab(_incognitoTabs[_incognitoTabs.length - 1].id);
          else if (tabs.length) setActiveTab(tabs[tabs.length - 1].id);
          else createNewTab('MainPage/index.html');
        }
      }
    }
  });
}

// ============== INCOGNITO ==============
var _incognitoTabs = [];
var _activeIncognitoId = null;

function switchToIncognitoTab(tabId) {
  tabs.forEach(function(t) {
    t.webview.style.display = 'none';
    t.element.classList.remove('active');
  });
  _incognitoTabs.forEach(function(t) {
    t.webview.style.display = 'none';
    t.element.classList.remove('active');
  });
  var tab = _incognitoTabs.find(function(t) { return t.id === tabId; });
  if (tab) {
    tab.webview.style.display = 'flex';
    tab.element.classList.add('active');
    activeTabId = null;
    // Remember which incognito tab is currently on screen so that
    // openInCurrentTab from inside the page (search bar, links) knows where
    // to navigate. activeTabId=null is intentional — it tells the rest of
    // the chrome UI that no regular tab is active — but we still need a
    // pointer for navigation IPCs.
    _activeIncognitoId = tabId;
    // Re-evaluate frosted glass for the incognito page.
    if (window._refreshTranslucent) { try { window._refreshTranslucent(); } catch(e) {} }
    try {
      var u = tab.webview.getURL ? tab.webview.getURL() : '';
      _urlBarRevealed = false;
      setUrlBarDisplay(u);
      updateUrlIcon(u);
    } catch(e) {}
  }
}

function closeIncognitoTab(tabId) {
  var idx = _incognitoTabs.findIndex(function(t) { return t.id === tabId; });
  if (idx === -1) return;
  var tab = _incognitoTabs[idx];
  // Capture the partition BEFORE removing the webview — we still need it
  // to wipe the session storage for this tab.
  var partition = tab.partition;
  // Visually remove the tab right away so the user gets instant feedback.
  try { tab.webview.remove(); } catch(e) {}
  try { tab.element.remove(); } catch(e) {}
  _incognitoTabs.splice(idx, 1);

  // Play the "magnifier shatter" animation so the user SEES that the
  // incognito session is being wiped — same visual as Break Loupe.
  try { if (typeof _playBreakLoupeAnimation === 'function') _playBreakLoupeAnimation(); } catch(e) {}

  // Auto-wipe: clear all cookies/cache/localStorage the tab accumulated.
  // This is the "incognito promise" — closing the tab erases every trace.
  if (partition && window.electronAPI && window.electronAPI.clearIncognitoPartition) {
    window.electronAPI.clearIncognitoPartition(partition).catch(function() {});
  }

  if (_incognitoTabs.length > 0) {
    switchToIncognitoTab(_incognitoTabs[_incognitoTabs.length - 1].id);
  } else {
    if (tabs.length > 0) setActiveTab(tabs[tabs.length - 1].id);
  }
}

// ============== INCOGNITO LAUNCH MODES ==============
// "Incognito" without a URL asks how to open it: a separate always-incognito
// window, or by replacing the regular tabs of the current window. Opening a
// specific link in incognito (context menu / QC) keeps the old behavior —
// an incognito tab inside the current window.
function _closeAllRegularTabsForce() {
  tabs.slice().forEach(function(t) {
    try { t.element.remove(); } catch(e) {}
    try { t.webview.remove(); } catch(e) {}
    delete _tabPreviewCache[t.id];
    delete _tabAudioPlaying[t.id];
    delete _tabMuted[t.id];
    delete _tabZoom[t.id];
    if (_tabSleepTimers[t.id]) { clearTimeout(_tabSleepTimers[t.id]); delete _tabSleepTimers[t.id]; }
    try { stopLoadingBar(t.id); } catch(e) {}
    var i = tabs.indexOf(t);
    if (i > -1) tabs.splice(i, 1);
  });
  activeTabId = null;
}

function _replaceWindowWithIncognito() {
  // Persist the regular session BEFORE the tabs disappear — autoSaveTabs is
  // disabled afterwards (window becomes incognito-only).
  try { autoSaveTabs(); } catch(e) {}
  window.createIncognitoTab();
  _closeAllRegularTabsForce();
  window._incognitoWindowMode = true;
  window._canSaveSession = false;
  try { _showToast('This window is now incognito — close it to get your tabs back', 'incognito-mode'); } catch(e) {}
}

function _showIncognitoModeDialog() {
  var overlay = document.getElementById('incognitoModeOverlay');
  if (!overlay) {
    // Fallback for unexpected markup problems — plain confirm flow.
    _replaceWindowWithIncognito();
    return;
  }
  overlay.style.display = '';
  overlay.classList.add('active');
  var btnNew = document.getElementById('incognitoNewWindow');
  var btnReplace = document.getElementById('incognitoReplaceWindow');
  var btnCancel = document.getElementById('incognitoModeCancel');
  function done(action) {
    overlay.classList.remove('active');
    overlay.style.display = 'none';
    btnNew.onclick = btnReplace.onclick = btnCancel.onclick = null;
    if (action === 'new-window' && window.electronAPI && window.electronAPI.openIncognitoWindow) {
      window.electronAPI.openIncognitoWindow();
    } else if (action === 'replace') {
      _replaceWindowWithIncognito();
    }
  }
  btnNew.onclick = function() { done('new-window'); };
  btnReplace.onclick = function() { done('replace'); };
  btnCancel.onclick = function() { done('cancel'); };
  overlay.onclick = function(e) { if (e.target === overlay) done('cancel'); };
  setTimeout(function() { try { btnNew.focus(); } catch(e) {} }, 30);
}

window.startIncognitoMode = function(url) {
  // A concrete link always opens as an incognito tab in this window.
  if (url && url !== '') { window.createIncognitoTab(url); return; }
  // Already a dedicated incognito window → just add another incognito tab.
  if (window._incognitoWindowMode) { window.createIncognitoTab(); return; }
  _showIncognitoModeDialog();
};

window.createIncognitoTab = function(url, opts) {
  var tabId = 'incognito-' + Date.now();
  // Each incognito tab gets its OWN partition — completely isolated from
  // the main browser session AND from other incognito tabs. Exception: a
  // torn-out tab reuses its original partition so its cookies survive the
  // move to the new window.
  var partition = (opts && opts.partition) || ('incognito-' + Date.now());
  var browserContent = document.querySelector('.browser-content');

  var wv = document.createElement('webview');
  wv.setAttribute('partition', partition);
  wv.setAttribute('allowpopups', '');
  wv.setAttribute('webpreferences', 'backgroundThrottling=false');
  if (webviewPreloadPath) wv.setAttribute('preload', webviewPreloadPath);
  wv.style.cssText = 'flex:1;display:none;';
  browserContent.appendChild(wv);

  var tabEl = document.createElement('div');
  tabEl.className = 'tab incognito-tab';
  tabEl.dataset.tabId = tabId;
  tabEl.innerHTML =
    '<span class="tab-favicon">' + _icon('🕵') + '</span>' +
    '<span class="tab-title">Incognito</span>' +
    '<span class="tab-close">&times;</span>';

  var tabData = { id: tabId, webview: wv, element: tabEl, isReady: false, isIncognito: true, partition: partition };

  tabEl.addEventListener('click', function(e) {
    if (e.target.classList.contains('tab-close')) {
      closeIncognitoTab(tabId);
    } else {
      switchToIncognitoTab(tabId);
    }
  });

  // Drag & drop tear-out: releasing the tab outside the tab strip moves it
  // to a new incognito window (partition travels along → cookies are kept).
  tabEl.draggable = true;
  tabEl.addEventListener('dragstart', function(e) {
    var mUrl = '';
    try { mUrl = wv.getURL ? wv.getURL() : (wv.src || ''); } catch(err) {}
    if ((!mUrl || mUrl === 'about:blank') && tabData._sleepUrl) mUrl = tabData._sleepUrl;
    var mTitle = '';
    try {
      var tl = tabEl.querySelector('.tab-title');
      if (tl) mTitle = (tl.textContent || '').trim();
    } catch(err) {}
    try {
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', tabId);
    } catch(err) {}
    tabEl.classList.add('dragging');
    _tearBeginDrag(tabId, e, { url: mUrl, title: mTitle, incognito: true, partition: partition });
  });
  tabEl.addEventListener('dragend', function(e) {
    tabEl.classList.remove('dragging');
    _tearEndDrag(e, tabId);
  });

  document.querySelector('.tabs-bar').insertBefore(tabEl, document.getElementById('newTabBtn'));
  _incognitoTabs.push(tabData);
  switchToIncognitoTab(tabId);

  // Default landing page: a stripped-down grey page with just the logo and
  // a search bar — no shortcuts, no wallpapers. (Like Chrome's incognito.)
  // If a URL was explicitly passed (e.g. via right-click → "open in incognito"),
  // load that instead.
  if (url && url !== '') {
    wv.src = url;
  } else {
    var incPagePath = window.location.href.replace(/\/[^/]*$/, '/') + 'MainPage/IncognitoPage.html';
    wv.src = incPagePath;
  }

  // CRITICAL: set the Chrome User-Agent, otherwise incognito tabs
  // send the default Electron UA (with "Electron" inside) — Google
  // immediately detects "This browser or app may not be secure".
  wv.addEventListener('dom-ready', function() {
    tabData.isReady = true;
    try { if (wv.setUserAgent) wv.setUserAgent(userAgent); } catch(e) {}
  });

  wv.addEventListener('did-finish-load', function() {
    tabData.isReady = true;
    try {
      var t = wv.getTitle();
      var titleEl = tabEl.querySelector('.tab-title');
      titleEl.innerHTML = _icon('🕵', 14, 14);
      titleEl.appendChild(document.createTextNode(' ' + (t || '') + ' '));
    } catch(e) {}
  });

  wv.addEventListener('did-navigate', function() {
    try {
      var t = wv.getTitle();
      var titleEl = tabEl.querySelector('.tab-title');
      titleEl.innerHTML = _icon('🕵', 14, 14);
      titleEl.appendChild(document.createTextNode(' ' + (t || '') + ' '));
    } catch(e) {}
  });

  wv.addEventListener('page-title-updated', function(e) {
    var titleEl = tabEl.querySelector('.tab-title');
    titleEl.innerHTML = _icon('🕵', 14, 14);
    titleEl.appendChild(document.createTextNode(' ' + (e.title || 'Incognito')));
  });
};

function promptIncognitoUrl() {
  var opts = tabs.map(function(t, i) {
    var u = '';
    try { u = t.webview.getURL ? t.webview.getURL() : (t.webview.src || ''); } catch(e) { u = ''; }
    var ti = '';
    try { ti = t.webview.getTitle ? t.webview.getTitle() : ''; } catch(e) {}
    return (i + 1) + '. ' + (ti || u).substring(0, 60);
  });
  var msg = 'Choose a tab (number) or enter a URL:\n\n' + opts.join('\n');
  customPrompt(msg).then(function(input) {
    if (!input) return;
    var num = parseInt(input.trim());
    if (!isNaN(num) && num >= 1 && num <= tabs.length) {
      var t = tabs[num - 1];
      var u = '';
      try { u = t.webview.getURL ? t.webview.getURL() : (t.webview.src || ''); } catch(e) {}
      if (u) window.createIncognitoTab(u);
    } else {
      var url = input.trim();
      if (url && !/^https?:\/\//i.test(url)) url = 'https://' + url;
      window.createIncognitoTab(url);
    }
  });
}

(function setupIncognito() {
  if (window.electronAPI && window.electronAPI.onIncognitoTab) {
    window.electronAPI.onIncognitoTab(function(url) {
      if (url) window.createIncognitoTab(url);
      else if (window.startIncognitoMode) window.startIncognitoMode();
      else promptIncognitoUrl();
    });
  }
})();

// ============== CONTAINER TABS ==============
// Firefox-style cookie-isolated containers. Each container tab runs in a
// persistent partition "persist:container-<id>" — cookies, localStorage and
// cache never mix with the default session or other containers. The feature
// is enabled and the container list is managed in Settings → Containers.
var _containersCfg = { enabled: false, containers: [] };
(function loadContainersCfg() {
  if (window.electronAPI && window.electronAPI.getContainers) {
    window.electronAPI.getContainers().then(function(c) {
      if (c) _containersCfg = c;
    }).catch(function() {});
  }
})();

window.refreshContainersCfg = function(cb) {
  if (!window.electronAPI || !window.electronAPI.getContainers) { if (cb) cb(); return Promise.resolve(); }
  return window.electronAPI.getContainers().then(function(c) {
    if (c) _containersCfg = c;
    if (cb) cb();
  }).catch(function() { if (cb) cb(); });
};

function _findContainer(id) {
  if (!id) return null;
  for (var i = 0; i < _containersCfg.containers.length; i++) {
    if (_containersCfg.containers[i].id === id) return _containersCfg.containers[i];
  }
  return null;
}

// Colored underline + icon on the tab strip so the user can tell container
// tabs apart at a glance (like Firefox's container underline).
function _applyContainerBadge(tabData) {
  var c = tabData.containerId ? _findContainer(tabData.containerId) : null;
  if (!c || !tabData.element) return;
  try {
    tabData.element.style.borderBottom = '2px solid ' + c.color;
    var fav = tabData.element.querySelector('.tab-favicon-placeholder') ||
              tabData.element.querySelector('.tab-favicon');
    if (fav) {
      fav.innerHTML = _icon(c.icon || '🗂', 10, 10);
      fav.style.color = c.color;
      fav.title = c.name || c.id;
    }
  } catch(e) {}
}

// Open a new tab inside a container. Regular tab in every other way: lives
// in tabs[], participates in workspaces/groups/sleep — only the session is
// partitioned.
window.createContainerTab = function(containerId, url) {
  if (!_findContainer(containerId)) {
    // Config may be stale (container just added in Settings) — refresh once.
    window.refreshContainersCfg(function() {
      if (_findContainer(containerId)) window.createContainerTab(containerId, url);
      else createNewTab(url || '');
    });
    return;
  }
  createNewTab(url || '', false, { containerId: containerId });
};

// ============== READ ALOUD (TTS) ==============
// Speaks the active page (or the current selection, when it is long enough)
// with the Chromium speech engine. Text is extracted in the webview, split
// into sentence chunks (long single utterances are cut off by Chromium) and
// spoken from THIS renderer — the main window always has speechSynthesis
// available, webviews may not.
var _ttsState = {
  chunks: [], idx: 0,
  speaking: false, paused: false,
  voices: [], voiceURI: '',
  lang: '', tabId: null,
  rate: 1,
  engineMode: 'system'  // resolved: 'system' | 'offline'
};
try { _ttsState.rate = parseFloat(localStorage.getItem('spz-tts-rate')) || 1; } catch(e) {}
try { _ttsState.voiceURI = localStorage.getItem('spz-tts-voice') || ''; } catch(e) {}
var _ttsEnginePref = 'auto'; // user preference: auto | system | offline
try { _ttsEnginePref = localStorage.getItem('spz-tts-engine') || 'auto'; } catch(e) {}
var _ttsOfflineAvailable = null; // null = unknown, true/false after probe
if (window.electronAPI && window.electronAPI.ttsOfflineAvailable) {
  window.electronAPI.ttsOfflineAvailable().then(function (r) {
    _ttsOfflineAvailable = !!(r && r.available);
  }).catch(function() { _ttsOfflineAvailable = false; });
}

// Offline engine (espeak-ng WASM in the main process): synthesized WAVs are
// cached per chunk index; the next chunk is prefetched while the current
// one plays, hiding the ~300 ms synthesis latency after the first chunk.
var _ttsOffline = { cache: {}, pending: {}, audio: null };

function _ttsOfflineFetch(idx) {
  var st = _ttsState;
  // NOTE: always return a Promise — callers chain .then(); a raw string on
  // the cache-hit path used to crash with ".then is not a function".
  if (_ttsOffline.cache[idx]) return Promise.resolve(_ttsOffline.cache[idx]);
  if (_ttsOffline.pending[idx]) return _ttsOffline.pending[idx];
  if (!window.electronAPI || !window.electronAPI.ttsSynthesize) {
    return Promise.reject(new Error('offline engine unavailable'));
  }
  _ttsOffline.pending[idx] = window.electronAPI.ttsSynthesize(st.chunks[idx], st.lang, st.rate).then(function (r) {
    delete _ttsOffline.pending[idx];
    if (!r || !r.ok || !r.wav) throw new Error((r && r.error) || 'synthesis failed');
    _ttsOffline.cache[idx] = r.wav;
    return r.wav;
  }).catch(function (e) {
    delete _ttsOffline.pending[idx];
    throw e;
  });
  return _ttsOffline.pending[idx];
}

function _ttsOfflineStopAudio() {
  if (_ttsOffline.audio) {
    try { _ttsOffline.audio.onended = null; _ttsOffline.audio.onerror = null; } catch(e) {}
    try { _ttsOffline.audio.pause(); } catch(e) {}
    _ttsOffline.audio = null;
  }
}

(function initTtsVoices() {
  if (!('speechSynthesis' in window)) return;
  function load() { try { _ttsState.voices = speechSynthesis.getVoices() || []; } catch(e) {} }
  load();
  try { speechSynthesis.addEventListener('voiceschanged', load); } catch(e) {}
})();

// Extract readable text: current selection when substantial, otherwise the
// article body. Walks VISIBLE text nodes (TreeWalker), skipping
// nav/header/footer/aside menus, code blocks and hidden elements, then
// filters out lines that look like CSS/JS source — pages rendering code
// samples must not be "read" as class names.
var _TTS_EXTRACT_SCRIPT =
  '(function(){' +
  'try{var sel=window.getSelection?String(window.getSelection()):"";' +
  'if(sel&&sel.trim().length>80)return JSON.stringify({lang:document.documentElement.lang||"",text:sel.trim().slice(0,40000)});}catch(e){}' +
  'function score(el){if(!el||!el.tagName)return 0;var t=(el.innerText||"").trim();' +
  'if(t.length<50)return 0;var tag=el.tagName.toLowerCase();' +
  'var b=0;if(tag==="article")b=200;if(tag==="main")b=150;' +
  'if(el.id&&/content|article|post|entry/i.test(el.id))b+=100;' +
  'if(el.className&&typeof el.className==="string"&&/content|article|post|entry/i.test(el.className))b+=80;' +
  'var p=0;if(/nav|header|footer|aside|form|sidebar|comment|social|share|related/i.test(tag+" "+(el.id||"")+" "+(el.className||"")))p=500;' +
  'return t.length+t.split(/[.!?]/).length*20+b-p;}' +
  'var cand=document.querySelectorAll("article,main,section,div");var best=null,bs=-1;' +
  'for(var i=0;i<cand.length;i++){var s=score(cand[i]);if(s>bs){bs=s;best=cand[i];}}' +
  'if(!best||bs<50)best=document.body;' +
  'if(!best)return JSON.stringify({lang:"",text:""});' +
  'var SKIP=/^(script|style|noscript|svg|canvas|template|iframe|object|embed|nav|header|footer|aside|form|select|textarea|button|input|code|pre|kbd|samp)$/i;' +
  'var BLOCK=/^(p|h1|h2|h3|h4|h5|h6|li|blockquote|figcaption|dd|dt|tr)$/i;' +
  'function inSkipped(el){var cur=el,g=0;' +
  'while(cur&&cur!==best&&g<40){if(SKIP.test(cur.tagName))return true;cur=cur.parentElement;g++;}' +
  'return SKIP.test(best.tagName);}' +
  'function visible(el){try{var cs=getComputedStyle(el);if(cs.visibility==="hidden"||cs.display==="none")return false;' +
  'var r=el.getBoundingClientRect();return r.width>0&&r.height>0;}catch(e){return false;}}' +
  'var visCache=[],visOk=[];' +
  'function visibleCached(el){var i=visCache.indexOf(el);if(i!==-1)return visOk[i];' +
  'visCache.push(el);var ok=visible(el);visOk.push(ok);return ok;}' +
  'var parts=[],chars=0;' +
  'var tw=document.createTreeWalker(best,NodeFilter.SHOW_TEXT,{acceptNode:function(node){' +
  'var p=node.parentElement;if(!p)return NodeFilter.FILTER_REJECT;' +
  'if(SKIP.test(p.tagName)||inSkipped(p))return NodeFilter.FILTER_REJECT;' +
  'if(!visibleCached(p))return NodeFilter.FILTER_REJECT;' +
  'var v=node.nodeValue;if(!v||!v.trim())return NodeFilter.FILTER_SKIP;' +
  'return NodeFilter.FILTER_ACCEPT;}});' +
  'while(tw.nextNode()&&chars<40000){var t=tw.currentNode.nodeValue.replace(/\\s+/g," ").trim();' +
  'if(!t)continue;chars+=t.length;' +
  'var pe=tw.currentNode.parentElement;' +
  'if(BLOCK.test(pe?pe.tagName:"")||parts.length===0)parts.push(t);' +
  'else{var prev=parts[parts.length-1];' +
  'if(prev.length+t.length<400)parts[parts.length-1]=prev+" "+t;else parts.push(t);}}' +
  // Drop repeated boilerplate lines and code/CSS-looking lines.
  'var seen={},lines=[];' +
  'for(var k=0;k<parts.length;k++){var l=parts[k];' +
  'if(seen[l])continue;seen[l]=1;lines.push(l);}' +
  'var text=lines.filter(function(l){' +
  'if(!l)return false;' +
  'if(/!important/.test(l))return false;' +
  'if(/[{}]/.test(l))return false;' +
  'if(/^\\s*[.#@:][\\w-]+/.test(l)&&/[:;{]/.test(l))return false;' +
  'if(/^(function|var|let|const|import|export|return)\\s/.test(l))return false;' +
  'if(/^\\s*[\\w-]+\\s*:\\s*[^.;{}]{0,60};?\\s*$/.test(l)&&/[a-z]-[a-z]/i.test(l))return false;' +
  'var words=l.split(/\\s+/);var odd=0;' +
  'for(var w=0;w<words.length;w++){var wd=words[w];' +
  'if(/^[.#][\w-]+$/.test(wd)||/^[a-z]+[A-Z]/.test(wd))odd++;}' +
  'if(words.length>3&&odd/words.length>0.5)return false;' +
  'return true;}).join("\\n").slice(0,40000);' +
  'return JSON.stringify({lang:document.documentElement.lang||"",text:text});})()';

function _ttsSplitChunks(text) {
  var out = [];
  var re = /[^.!?…\n]+[.!?…]*\n*/g, m;
  var buf = '';
  function flush() { if (buf.trim()) out.push(buf.trim()); buf = ''; }
  function hardSplit(s) {
    var words = s.split(' ');
    var line = '';
    for (var i = 0; i < words.length; i++) {
      if ((line + ' ' + words[i]).length > 380) { out.push(line.trim()); line = words[i]; }
      else line = line ? line + ' ' + words[i] : words[i];
    }
    if (line.trim()) out.push(line.trim());
  }
  while ((m = re.exec(text)) !== null) {
    var s = m[0].trim();
    if (!s) continue;
    if (s.length > 400) { flush(); hardSplit(s); continue; }
    if (buf.length + s.length + 1 <= 220) buf = buf ? buf + ' ' + s : s;
    else { flush(); buf = s; }
  }
  flush();
  return out;
}

function _ttsPickVoice() {
  var st = _ttsState;
  if (!st.voices.length) return null;
  // Explicit user choice first.
  if (st.voiceURI) {
    for (var i = 0; i < st.voices.length; i++) {
      if (st.voices[i].voiceURI === st.voiceURI) return st.voices[i];
    }
  }
  // Otherwise: match the page language prefix (ru → ru-RU), prefer local.
  var lang = (st.lang || '').toLowerCase().split('-')[0];
  var best = null, bestScore = -1;
  for (var j = 0; j < st.voices.length; j++) {
    var v = st.voices[j];
    var vl = String(v.lang || '').toLowerCase();
    var score = 0;
    if (lang && vl.indexOf(lang) === 0) score += 10;
    if (v.localService) score += 2;
    if (v.default) score += 1;
    if (score > bestScore) { bestScore = score; best = v; }
  }
  return best;
}

function _ttsUpdatePanel() {
  var panel = document.getElementById('ttsPanel');
  var textEl = document.getElementById('ttsCurrent');
  var posEl = document.getElementById('ttsPos');
  var playBtn = document.getElementById('ttsPlayBtn');
  if (!panel) return;
  var st = _ttsState;
  if (playBtn) playBtn.textContent = st.paused ? '▶' : (st.speaking ? '⏸' : '▶');
  // Clamp the displayed position — idx must never render beyond the end
  // (rapid onend/onerror double-fire used to show "25/24").
  var shown = Math.min(Math.max(st.idx, 0), Math.max(st.chunks.length - 1, 0));
  if (textEl) textEl.textContent = st.chunks[shown] || (st.chunks.length ? '…' : '');
  if (posEl) posEl.textContent = st.chunks.length ? (shown + 1) + ' / ' + st.chunks.length : '';
}

// Called ONCE per finished utterance (see the done-flag in _ttsSpeakCurrent).
function _ttsChunkDone() {
  var st = _ttsState;
  if (!st.speaking || st.paused) return;
  // Rapid-failure guard: a chunk that "ended" almost instantly means the
  // engine produced no audio (e.g. Linux without speech-dispatcher voices).
  // After 3 such failures stop instead of silently racing through the text.
  var dt = Date.now() - (st._speakStart || 0);
  if (dt < 250) {
    st._failCount = (st._failCount || 0) + 1;
    if (st._failCount >= 3) {
      _ttsStop();
      var msg = 'The speech engine produced no audio. No usable system voices were found.\n\n' +
        'Linux: install the speech stack and restart the browser:\n' +
        '  sudo apt install speech-dispatcher espeak-ng\n' +
        'Windows/macOS: check the system text-to-speech settings.';
      if (typeof customAlert === 'function') customAlert(msg);
      else if (typeof _showToast === 'function') _showToast('Speech engine produced no audio — install system voices');
      return;
    }
  } else {
    st._failCount = 0;
  }
  st.idx++;
  _ttsUpdatePanel();
  _ttsSpeakCurrent();
}

function _ttsSpeakCurrent() {
  var st = _ttsState;
  if (!st.speaking || st.paused) return;
  if (st.idx >= st.chunks.length || st.idx < 0) { _ttsFinish(); return; }
  if (st.engineMode === 'offline') { _ttsSpeakCurrentOffline(); return; }
  try {
    var u = new SpeechSynthesisUtterance(st.chunks[st.idx]);
    var v = _ttsPickVoice();
    if (v) { u.voice = v; u.lang = v.lang; }
    else if (st.lang) u.lang = st.lang;
    u.rate = st.rate;
    // Single-shot completion: without the done flag Chromium fires BOTH
    // onend and onerror for a failed utterance → idx advanced twice.
    var done = false;
    u.onend = function() { if (done) return; done = true; _ttsChunkDone(); };
    u.onerror = function(ev) {
      if (done) return;
      var err = ev && ev.error;
      // 'interrupted'/'canceled' = OUR cancel() from skip/rate change —
      // must NOT advance the position.
      if (err === 'interrupted' || err === 'canceled') { done = true; return; }
      done = true;
      _ttsChunkDone();
    };
    st._speakStart = Date.now();
    speechSynthesis.speak(u);
    _ttsUpdatePanel();
  } catch(e) { _ttsFinish(); }
}

function _ttsSpeakCurrentOffline() {
  var st = _ttsState;
  _ttsOfflineStopAudio();
  _ttsOfflineFetch(st.idx).then(function (b64) {
    if (!st.speaking || st.paused || st.engineMode !== 'offline') return;
    var audio = new Audio('data:audio/wav;base64,' + b64);
    _ttsOffline.audio = audio;
    var done = false;
    audio.onended = function () { if (done) return; done = true; if (st._ttsOfflineAudio === audio) st._ttsOfflineAudio = null; _ttsChunkDone(); };
    audio.onerror = function () {
      if (done) return; done = true;
      if (st._ttsOfflineAudio === audio) st._ttsOfflineAudio = null;
      _ttsChunkDone(); // counts toward the rapid-fail guard (instant end)
    };
    st._speakStart = Date.now();
    st._ttsOfflineAudio = audio;
    audio.play().catch(function () { if (!done) { done = true; _ttsChunkDone(); } });
    _ttsUpdatePanel();
    // Prefetch the next chunk while this one plays.
    if (st.idx + 1 < st.chunks.length) {
      _ttsOfflineFetch(st.idx + 1).catch(function () {});
    }
  }).catch(function (e) {
    if (!st.speaking) return;
    if (typeof _showToast === 'function') _showToast('Offline speech engine failed: ' + (e && e.message || e));
    _ttsStop();
  });
}

// cancel() + immediate speak() stalls on Chromium — speak the next chunk
// after a small delay instead.
function _ttsRestartCurrent() {
  var st = _ttsState;
  try { speechSynthesis.cancel(); } catch(e) {}
  st._restartTimer = setTimeout(function() { _ttsSpeakCurrent(); }, 80);
}

function _ttsFinish() {
  var st = _ttsState;
  st.speaking = false;
  st.paused = false;
  st._failCount = 0;
  st._ttsOfflineAudio = null;
  if (st._restartTimer) { clearTimeout(st._restartTimer); st._restartTimer = null; }
  _ttsOfflineStopAudio();
  _ttsOffline.cache = {};
  _ttsOffline.pending = {};
  try { if (st._navWv && st._navFn) st._navWv.removeEventListener('did-navigate', st._navFn); } catch(e) {}
  st._navWv = null; st._navFn = null;
  try { speechSynthesis.cancel(); } catch(e) {}
  _ttsUpdatePanel();
}

function _ttsStart() {
  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (!tab || !tab.webview || !canExecInWebview(tab.webview)) {
    if (typeof customAlert === 'function') customAlert('Read aloud is unavailable for this page');
    return;
  }
  // Resolve the engine BEFORE extraction so failures surface immediately.
  //   auto   → system voices when present, else the offline espeak engine
  //   system → speechSynthesis only (needs installed system voices)
  //   offline→ espeak-ng WASM package (always available, robotic quality)
  var useOffline;
  if (_ttsEnginePref === 'offline') useOffline = true;
  else if (_ttsEnginePref === 'system') useOffline = false;
  else useOffline = !_ttsState.voices.length;
  if (!useOffline && !('speechSynthesis' in window)) {
    if (_ttsOfflineAvailable) useOffline = true;
    else {
      if (typeof customAlert === 'function') customAlert('Speech synthesis is not available in this build');
      return;
    }
  }
  if (useOffline) {
    if (_ttsOfflineAvailable === false) {
      if (typeof customAlert === 'function') customAlert('The offline speech engine is not installed in this build.');
      return;
    }
    _ttsState.engineMode = 'offline';
  } else {
    _ttsState.engineMode = 'system';
  }
  _ttsUpdateEngineUi();
  _ttsFinish();
  tab.webview.executeJavaScript(_TTS_EXTRACT_SCRIPT).then(function(result) {
    var data = null;
    try { data = JSON.parse(result); } catch(e) {}
    if (!data || !data.text || data.text.trim().length < 40) {
      if (typeof customAlert === 'function') customAlert('No readable text found on this page');
      return;
    }
    var st = _ttsState;
    st.chunks = _ttsSplitChunks(data.text);
    if (!st.chunks.length) {
      if (typeof customAlert === 'function') customAlert('No readable text found on this page');
      return;
    }
    st.idx = 0;
    st.lang = data.lang || '';
    st.tabId = activeTabId;
    st.speaking = true;
    st.paused = false;
    st._failCount = 0;
    var panel = document.getElementById('ttsPanel');
    if (panel) panel.classList.add('open');
    _ttsPopulateVoices();
    if (st.engineMode === 'offline' && _ttsEnginePref === 'auto' && !_ttsState.voices.length) {
      if (typeof _showToast === 'function') _showToast('No system voices found — using the built-in offline engine');
    }
    // Stop reading automatically when the page navigates away — the text
    // no longer matches what is on screen.
    try {
      st._navWv = tab.webview;
      st._navFn = function() { _ttsStop(); };
      tab.webview.addEventListener('did-navigate', st._navFn);
    } catch(e) {}
    _ttsSpeakCurrent();
  }).catch(function() {
    if (typeof customAlert === 'function') customAlert('Failed to extract page text');
  });
}

function _ttsTogglePause() {
  var st = _ttsState;
  if (!st.speaking) { _ttsStart(); return; }
  try {
    if (st.engineMode === 'offline') {
      var a = st._ttsOfflineAudio;
      if (st.paused) { st.paused = false; if (a) a.play().catch(function() {}); }
      else { st.paused = true; if (a) a.pause(); }
    } else {
      if (st.paused) { speechSynthesis.resume(); st.paused = false; }
      else { speechSynthesis.pause(); st.paused = true; }
    }
  } catch(e) {}
  _ttsUpdatePanel();
}

function _ttsSkip(delta) {
  var st = _ttsState;
  if (!st.chunks.length) return;
  st.idx = Math.max(0, Math.min(st.chunks.length - 1, st.idx + delta));
  if (st._restartTimer) { clearTimeout(st._restartTimer); st._restartTimer = null; }
  if (st.engineMode === 'offline') {
    _ttsOfflineStopAudio();
    st._ttsOfflineAudio = null;
    if (st.speaking && !st.paused) _ttsSpeakCurrentOffline();
    else _ttsUpdatePanel();
    return;
  }
  // cancel() now fires onerror('interrupted') which is ignored by the
  // utterance guard — safe to restart the new chunk directly.
  if (st.speaking && !st.paused) _ttsRestartCurrent();
  else {
    try { speechSynthesis.cancel(); } catch(e) {}
    _ttsUpdatePanel();
  }
}

function _ttsStop() {
  _ttsFinish();
  var panel = document.getElementById('ttsPanel');
  if (panel) panel.classList.remove('open');
}

function _ttsPopulateVoices() {
  var sel = document.getElementById('ttsVoice');
  if (!sel) return;
  var st = _ttsState;
  sel.innerHTML = '';
  var auto = document.createElement('option');
  auto.value = '';
  auto.textContent = 'Auto (page language)';
  sel.appendChild(auto);
  st.voices.forEach(function(v) {
    var o = document.createElement('option');
    o.value = v.voiceURI;
    o.textContent = (v.name || 'Voice') + ' (' + (v.lang || '') + ')';
    if (v.voiceURI === st.voiceURI) o.selected = true;
    sel.appendChild(o);
  });
}

window._ttsToggle = function() {
  var panel = document.getElementById('ttsPanel');
  if (panel && panel.classList.contains('open') && _ttsState.speaking) { _ttsStop(); return; }
  _ttsStart();
};

(function setupTtsPanel() {
  var panel = document.getElementById('ttsPanel');
  if (!panel) return;
  var playBtn = document.getElementById('ttsPlayBtn');
  var stopBtn = document.getElementById('ttsStopBtn');
  var prevBtn = document.getElementById('ttsPrevBtn');
  var nextBtn = document.getElementById('ttsNextBtn');
  var closeBtn = document.getElementById('ttsCloseBtn');
  var rateSel = document.getElementById('ttsRate');
  var voiceSel = document.getElementById('ttsVoice');
  var engineSel = document.getElementById('ttsEngine');
  if (playBtn) playBtn.addEventListener('click', _ttsTogglePause);
  if (stopBtn) stopBtn.addEventListener('click', _ttsStop);
  if (closeBtn) closeBtn.addEventListener('click', _ttsStop);
  if (prevBtn) prevBtn.addEventListener('click', function() { _ttsSkip(-1); });
  if (nextBtn) nextBtn.addEventListener('click', function() { _ttsSkip(1); });
  if (engineSel) {
    engineSel.value = _ttsEnginePref;
    engineSel.addEventListener('change', function() {
      _ttsEnginePref = engineSel.value === 'system' ? 'system' : (engineSel.value === 'offline' ? 'offline' : 'auto');
      try { localStorage.setItem('spz-tts-engine', _ttsEnginePref); } catch(e) {}
      // Restart the current reading with the new engine (if any).
      if (_ttsState.speaking) {
        var resumeIdx = _ttsState.idx;
        var resumeLang = _ttsState.lang;
        var resumeChunks = _ttsState.chunks.slice();
        var resumeTab = _ttsState.tabId;
        _ttsStop();
        _ttsState.chunks = resumeChunks;
        _ttsState.idx = Math.min(resumeIdx, Math.max(resumeChunks.length - 1, 0));
        _ttsState.lang = resumeLang;
        _ttsState.tabId = resumeTab;
        _ttsState.speaking = true;
        _ttsState.paused = false;
        // engine preference: offline | system | auto (auto = system when
        // voices are available, offline otherwise)
        var useOffline = _ttsEnginePref === 'offline' ? true :
          (_ttsEnginePref === 'system' ? false : !_ttsState.voices.length);
        _ttsState.engineMode = useOffline ? 'offline' : 'system';
        _ttsUpdateEngineUi();
        var p = document.getElementById('ttsPanel');
        if (p) p.classList.add('open');
        _ttsSpeakCurrent();
      } else {
        _ttsUpdateEngineUi();
      }
    });
  }
  if (rateSel) {
    rateSel.value = String(_ttsState.rate);
    rateSel.addEventListener('change', function() {
      _ttsState.rate = parseFloat(rateSel.value) || 1;
      try { localStorage.setItem('spz-tts-rate', String(_ttsState.rate)); } catch(e) {}
      // Re-speak the current chunk at the new rate. The offline engine bakes
      // the rate into the WAV — drop the cache so chunks re-synthesize.
      if (_ttsState.speaking && !_ttsState.paused) {
        if (_ttsState.engineMode === 'offline') {
          _ttsOffline.cache = {};
          _ttsOfflineStopAudio();
          _ttsSpeakCurrentOffline();
        } else {
          _ttsRestartCurrent();
        }
      } else if (_ttsState.engineMode === 'offline') {
        _ttsOffline.cache = {};
      }
    });
  }
  if (voiceSel) {
    voiceSel.addEventListener('change', function() {
      _ttsState.voiceURI = voiceSel.value;
      try { localStorage.setItem('spz-tts-voice', _ttsState.voiceURI); } catch(e) {}
      if (_ttsState.speaking && !_ttsState.paused && _ttsState.engineMode === 'system') {
        _ttsRestartCurrent();
      }
    });
  }
  _ttsUpdateEngineUi();
})();

// Reflect the active engine in the panel: the voice picker applies to the
// system engine only; show which engine is actually speaking.
function _ttsUpdateEngineUi() {
  var voiceSel = document.getElementById('ttsVoice');
  var engineSel = document.getElementById('ttsEngine');
  var title = document.getElementById('ttsVoice') || null;
  if (voiceSel) voiceSel.style.display = (_ttsState.engineMode === 'offline') ? 'none' : '';
  if (engineSel) {
    // Gray out the system option when no system voices exist.
    var sysOpt = engineSel.querySelector('option[value="system"]');
    if (sysOpt) sysOpt.disabled = !_ttsState.voices.length;
  }
  if (title && _ttsState.engineMode === 'offline') {
    title.dataset.sysTitle = title.title || '';
  }
}

// Stop reading when the user switches to another tab (the text belongs to
// the page it was extracted from).
(function hookTtsTabSwitch() {
  var _origSetActive2 = setActiveTab;
  setActiveTab = function(id) {
    if (_ttsState.speaking && _ttsState.tabId && _ttsState.tabId !== id) _ttsStop();
    return _origSetActive2(id);
  };
})();

// ============== FIND IN ALL TABS ==============
var _findallVisible = false;
var _findallAbort = false;

function toggleFindAll() {
  var overlay = document.getElementById('findallOverlay');
  if (!overlay) return;
  if (_findallVisible) {
    overlay.classList.remove('visible');
    _findallVisible = false;
    _findallAbort = true;
  } else {
    overlay.classList.add('visible');
    _findallVisible = true;
    _findallAbort = false;
    var input = document.getElementById('findallInput');
    input.value = '';
    document.getElementById('findallResults').innerHTML = '<div class="findall-empty">Enter a query to search all tabs</div>';
    document.getElementById('findallCount').textContent = '';
    setTimeout(function() { input.focus(); }, 50);
  }
}

(function setupFindAll() {
  var input = document.getElementById('findallInput');
  var results = document.getElementById('findallResults');
  var countEl = document.getElementById('findallCount');
  var overlay = document.getElementById('findallOverlay');
  var closeBtn = document.getElementById('findallClose');
  if (!input || !overlay) return;

  var searchTimer = null;

  closeBtn.addEventListener('click', function() { toggleFindAll(); });
  overlay.addEventListener('click', function(e) { if (e.target === overlay) toggleFindAll(); });

  input.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') { toggleFindAll(); e.preventDefault(); }
  });

  input.addEventListener('input', function() {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(function() { doFindAll(input.value.trim()); }, 300);
  });

  function doFindAll(query) {
    if (!query || query.length < 2) {
      results.innerHTML = '<div class="findall-empty">Enter at least 2 characters</div>';
      countEl.textContent = '';
      return;
    }
    _findallAbort = false;
    results.innerHTML = '<div class="findall-empty">Searching...</div>';
    countEl.textContent = '';
    var qLower = query.toLowerCase();
    var totalMatches = 0;
    var tabResults = [];
    // Snapshot the tab count: comparing `checked` against the LIVE
    // tabs.length breaks when tabs open/close mid-search (double render or
    // a panel stuck on "Searching…" forever).
    var total = tabs.length;
    var checked = 0;

    tabs.forEach(function(tab) {
      if (_findallAbort) return;
      if (!tab.webview || !canExecInWebview(tab.webview) || tab._isSleeping) {
        checked++;
        if (checked === total) renderFindAllResults(tabResults, totalMatches);
        return;
      }
      try {
        tab.webview.executeJavaScript(
          '(function(){' +
          'var q=' + JSON.stringify(qLower) + ';' +
          'var body=document.body?document.body.innerText:"";' +
          'var lower=body.toLowerCase();' +
          'var count=0;var idx=0;' +
          'while((idx=lower.indexOf(q,idx))!==-1){count++;idx+=q.length;}' +
          'var snippets=[];' +
          'if(count>0){' +
          'var si=0;while(snippets.length<5&&(si=lower.indexOf(q,si))!==-1){' +
          'var s=Math.max(0,si-40);var e=Math.min(body.length,si+q.length+40);' +
          'snippets.push(body.substring(s,e));' +
          'si+=q.length;}}' +
          'return{count:count,snippets:snippets,url:location.href,title:document.title};' +
          '})()'
        ).then(function(r) {
          checked++;
          if (_findallAbort) return;
          if (r && r.count > 0) {
            totalMatches += r.count;
            tabResults.push({ tabId: tab.id, title: r.title || '', url: r.url || '', count: r.count, snippets: r.snippets });
          }
          if (checked === total) renderFindAllResults(tabResults, totalMatches);
        }).catch(function() {
          checked++;
          if (checked === total) renderFindAllResults(tabResults, totalMatches);
        });
      } catch(e) {
        checked++;
        if (checked === total) renderFindAllResults(tabResults, totalMatches);
      }
    });

    if (tabs.length === 0) renderFindAllResults([], 0);
  }

  function renderFindAllResults(tabResults, totalMatches) {
    countEl.textContent = totalMatches > 0 ? (totalMatches + ' in ' + tabResults.length + ' tabs') : 'not found';
    if (tabResults.length === 0) {
      results.innerHTML = '<div class="findall-empty">Nothing found</div>';
      return;
    }
    tabResults.sort(function(a, b) { return b.count - a.count; });
    var html = '';
    tabResults.forEach(function(tr) {
      html += '<div class="findall-tab-group">';
      html += '<div class="findall-tab-header" data-tabid="' + tr.tabId + '">';
      html += '<span class="findall-tab-icon">&#9654;</span>';
      html += '<span class="findall-tab-title">' + escapeHtmlSimple(tr.title || tr.url) + '</span>';
      html += '<span class="findall-tab-count">' + tr.count + '</span>';
      html += '</div>';
      if (tr.snippets) {
        tr.snippets.forEach(function(snip) {
          var highlighted = highlightSnippet(snip, input.value.trim());
          html += '<div class="findall-snippet" data-tabid="' + tr.tabId + '">' + highlighted + '</div>';
        });
      }
      html += '</div>';
    });
    results.innerHTML = html;
    results.querySelectorAll('.findall-tab-header').forEach(function(el) {
      el.addEventListener('click', function() {
        var tabId = el.getAttribute('data-tabid');
        toggleFindAll();
        setActiveTab(tabId);
        setTimeout(function() { toggleFindBar(); }, 200);
      });
    });
    results.querySelectorAll('.findall-snippet').forEach(function(el) {
      el.addEventListener('click', function() {
        var tabId = el.getAttribute('data-tabid');
        toggleFindAll();
        setActiveTab(tabId);
        setTimeout(function() {
          var findInput = document.getElementById('findInput');
          if (findInput) findInput.value = input.value.trim();
          toggleFindBar();
        }, 200);
      });
    });
  }

  function highlightSnippet(text, query) {
    var escaped = escapeHtmlSimple(text);
    var qEsc = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    var re = new RegExp('(' + qEsc + ')', 'gi');
    return escaped.replace(re, '<mark>$1</mark>');
  }
})();

// ============== AUTOSCROLL ==============
var _autoscrollActive = false;
var _autoscrollSpeed = 2;
var _autoscrollTimerId = null;

function startAutoscroll() {
  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (!tab || !tab.webview) return;
  _autoscrollActive = true;
  _autoscrollSpeed = 2;
  showAutoscrollIndicator();
  injectAutoscroll(tab);
}

function stopAutoscroll() {
  _autoscrollActive = false;
  if (_autoscrollTimerId) { clearTimeout(_autoscrollTimerId); _autoscrollTimerId = null; }
  hideAutoscrollIndicator();
  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (tab && tab.webview) {
    tab.webview.executeJavaScript('(function(){if(window.__asRaf){cancelAnimationFrame(window.__asRaf);window.__asRaf=null;}return 0})()').catch(function() {});
  }
}

function showAutoscrollIndicator() {
  var indicator = document.getElementById('autoscrollIndicator');
  if (indicator) indicator.classList.add('visible');
  updateAutoscrollLabel();
}

function hideAutoscrollIndicator() {
  var indicator = document.getElementById('autoscrollIndicator');
  if (indicator) indicator.classList.remove('visible');
}

function updateAutoscrollLabel() {
  var label = document.getElementById('autoscrollLabel');
  if (label) label.textContent = 'x' + _autoscrollSpeed;
}

function injectAutoscroll(tab) {
  if (!tab || !tab.webview) return;
  var speed = _autoscrollSpeed;
  tab.webview.executeJavaScript(
    '(function(){' +
    'if(window.__asRaf){cancelAnimationFrame(window.__asRaf);window.__asRaf=null;}' +
    'var sp=' + speed + ';' +
    'var last=null;' +
    'function step(ts){' +
    'if(last===null){last=ts;window.__asRaf=requestAnimationFrame(step);return;}' +
    'var dt=ts-last;' +
    'last=ts;' +
    'window.scrollBy(0,sp*dt*0.05);' +
    'if((window.innerHeight+window.scrollY)>=document.documentElement.scrollHeight-2){window.__asRaf=null;return;}' +
    'window.__asRaf=requestAnimationFrame(step);}' +
    'window.__asRaf=requestAnimationFrame(step);' +
    'return "as-ok"})()'
  ).then(function(r) {
    console.log('[Autoscroll] injected, result:', r);
  }).catch(function(e) {
    console.log('[Autoscroll] inject error:', e);
  });
}

(function setupAutoscroll() {
  var stopBtn = document.getElementById('autoscrollStop');
  var fasterBtn = document.getElementById('autoscrollFaster');
  var slowerBtn = document.getElementById('autoscrollSlower');
  if (stopBtn) stopBtn.addEventListener('click', function() { stopAutoscroll(); });
  if (fasterBtn) fasterBtn.addEventListener('click', function() {
    _autoscrollSpeed = Math.min(20, _autoscrollSpeed + 1);
    updateAutoscrollLabel();
    var tab = tabs.find(function(t) { return t.id === activeTabId; });
    injectAutoscroll(tab);
  });
  if (slowerBtn) slowerBtn.addEventListener('click', function() {
    _autoscrollSpeed = Math.max(1, _autoscrollSpeed - 1);
    updateAutoscrollLabel();
    var tab = tabs.find(function(t) { return t.id === activeTabId; });
    injectAutoscroll(tab);
  });
})();
// ============== AUDIO EQUALIZER ==============
var _eqBands = [
  { freq: 60, type: 'lowshelf' },
  { freq: 170, type: 'peaking' },
  { freq: 310, type: 'peaking' },
  { freq: 600, type: 'peaking' },
  { freq: 1000, type: 'peaking' },
  { freq: 3000, type: 'peaking' },
  { freq: 6000, type: 'peaking' },
  { freq: 12000, type: 'peaking' },
  { freq: 16000, type: 'highshelf' }
];

var _eqPresets = {
  flat: [0,0,0,0,0,0,0,0,0],
  bass: [8,5,3,1,0,0,0,0,0],
  treble: [0,0,0,0,0,1,3,5,8],
  rock: [5,4,2,0,-1,1,3,4,5],
  pop: [-1,2,4,5,4,2,0,-1,-2],
  jazz: [3,2,1,2,0,-1,0,1,3],
  classical: [4,3,2,1,0,0,0,2,4],
  vocal: [-2,0,2,5,5,4,2,0,-2],
  electronic: [6,5,2,0,-2,0,2,5,6]
};

var _eqState = {
  enabled: false, // MUST default to false: the saved state loads asynchronously,
                  // and with enabled=true the EQ injected during the startup
                  // race (before settings arrive) and captured <video>/<audio>
                  // into a suspended AudioContext — silently killing ALL sound.
  preamp: 0,
  gains: _eqPresets.flat.slice(),
  preset: 'flat'
};

var _eqInjectedTabs = {};

function eqLoadSettings() {
  if (!window.electronAPI || !window.electronAPI.getCustomizationSettings) return;
  window.electronAPI.getCustomizationSettings().then(function(s) {
    if (s && s.settings && s.settings.equalizer) {
      _eqState = Object.assign(_eqState, s.settings.equalizer);
      _eqState.gains = _eqState.gains || _eqPresets.flat.slice();
      eqUpdateUI();
      // Apply a SAVED-ENABLED EQ to tabs that loaded during the startup race
      // (_eqState defaults to false precisely so nothing injects before the
      // settings arrive). Without this the equalizer stayed "on" in the panel
      // but silent until the next navigation — "EQ does nothing" after restart.
      if (_eqState.enabled) eqApplyToAllTabs();
    }
  }).catch(function() {});
}

function eqSaveSettings() {
  if (!window.electronAPI || !window.electronAPI.saveCustomizationSettings) return;
  window.electronAPI.saveCustomizationSettings({ equalizer: JSON.parse(JSON.stringify(_eqState)) }).catch(function() {});
}

function eqUpdateUI() {
  var toggle = document.getElementById('eqToggle');
  var preset = document.getElementById('eqPreset');
  var preamp = document.getElementById('eqPreamp');
  var preampVal = document.getElementById('eqPreampVal');
  if (toggle) toggle.checked = _eqState.enabled;
  if (preset) preset.value = _eqState.preset || 'flat';
  if (preamp) preamp.value = _eqState.preamp;
  if (preampVal) preampVal.textContent = (_eqState.preamp > 0 ? '+' : '') + _eqState.preamp + ' dB';
  var bandsContainer = document.getElementById('eqBands');
  if (bandsContainer) {
    var sliders = bandsContainer.querySelectorAll('.eq-band-slider');
    var vals = bandsContainer.querySelectorAll('.eq-band-val');
    for (var i = 0; i < sliders.length; i++) {
      sliders[i].value = _eqState.gains[i] || 0;
      vals[i].textContent = ((_eqState.gains[i] || 0) > 0 ? '+' : '') + (_eqState.gains[i] || 0);
    }
  }
}

function eqApplyToAllTabs() {
  tabs.forEach(function(tab) {
    if (tab.webview && !tab._isSleeping) {
      eqInject(tab);
    }
  });
}

function eqInject(tab, _retried) {
  if (!tab || !tab.webview || !canExecInWebview(tab.webview)) return;
  var gains = JSON.stringify(_eqState.gains);
  var preamp = _eqState.preamp;
  var enabled = _eqState.enabled;
  var bands = JSON.stringify(_eqBands.map(function(b) { return { freq: b.freq, type: b.type }; }));
  // userGesture=true: the user clicked the EQ toggle/sliders in the BROWSER
  // CHROME, not on the page. Without passing the gesture down, the page's
  // AudioContext stays suspended (autoplay policy) and the equalizer graph
  // sat dead — "EQ does nothing". The gesture flag grants user activation.
  tab.webview.executeJavaScript(
    '(function(){' +
    'var G=' + gains + ',PA=' + preamp + ',EN=' + enabled + ',B=' + bands + ';' +
    'if(!EN){' +
    '  if(window.__eqCtx){try{if(window.__eqCtx.state==="suspended"&&window.__eqCtx.resume)window.__eqCtx.resume();}catch(e){}}' +
    '  if(window.__eqFilters){for(var i=0;i<window.__eqFilters.length;i++){window.__eqFilters[i].gain.value=0;}}' +
    '  if(window.__eqGain){window.__eqGain.gain.value=1.0;}' +
    '  window.__eqActive=false;return "eq-bypass";' +
    '}' +
    'if(!window.__eqCtx){window.__eqCtx=new(window.AudioContext||window.webkitAudioContext)();}' +
    'var ctx=window.__eqCtx;' +
    // AudioContext starts suspended unless created during a user gesture.
    // Without resume(), captured media plays through a dead graph = silence.
    'try{if(ctx.state==="suspended"&&ctx.resume){ctx.resume();}}catch(e){}' +
    'if(!window.__eqResumeBound){window.__eqResumeBound=true;' +
    '  ["pointerdown","keydown","touchstart","click"].forEach(function(ev){' +
    '    document.addEventListener(ev,function(){try{if(ctx.state==="suspended"&&ctx.resume)ctx.resume();}catch(e){}},{once:false});});}' +
    'if(!window.__eqFilters||window.__eqFilters.length!==B.length){' +
    '  var filters=[];' +
    '  for(var i=0;i<B.length;i++){' +
    '    var f=ctx.createBiquadFilter();' +
    '    f.type=B[i].type;' +
    '    f.frequency.value=B[i].freq;' +
    '    if(B[i].type==="peaking")f.Q.value=1.4;' +
    '    f.gain.value=G[i]||0;' +
    '    filters.push(f);}' +
    '  window.__eqFilters=filters;' +
    '  window.__eqGain=ctx.createGain();' +
    '  for(var i=0;i<filters.length;i++){if(i===0)continue;filters[i-1].connect(filters[i]);}' +
    '  filters[filters.length-1].connect(window.__eqGain);' +
    '  window.__eqGain.connect(ctx.destination);' +
    '}' +
    'for(var i=0;i<window.__eqFilters.length;i++){window.__eqFilters[i].gain.value=G[i]||0;}' +
    'window.__eqGain.gain.value=Math.pow(10,PA/20);' +
    'window.__eqOk=window.__eqOk||[];' +
    'window.__eqSkip=window.__eqSkip||[];' +
    'function connectEl(el){' +
    '  for(var c=0;c<window.__eqOk.length;c++){if(window.__eqOk[c]===el)return;}' +
    '  for(var c2=0;c2<window.__eqSkip.length;c2++){if(window.__eqSkip[c2]===el)return;}' +
    '  try{' +
    '    var src=ctx.createMediaElementSource(el);' +
    '    src.connect(window.__eqFilters[0]);' +
    '    window.__eqOk.push(el);' +
    // createMediaElementSource throws InvalidStateError when the site ALREADY
    // routes the element through its own AudioContext (some players do) —
    // count it so the UI can tell the user WHY the EQ has no effect there.
    '  }catch(e){window.__eqSkip.push(el);}}' +
    'var els=document.querySelectorAll("video,audio");' +
    'for(var j=0;j<els.length;j++){connectEl(els[j]);}' +
    'if(!window.__eqObs){' +
    '  window.__eqObs=new MutationObserver(function(mutations){' +
    '    for(var m=0;m<mutations.length;m++){' +
    '      for(var n=0;n<mutations[m].addedNodes.length;n++){' +
    '        var nd=mutations[m].addedNodes[n];' +
    '        if(nd.tagName==="VIDEO"||nd.tagName==="AUDIO"){connectEl(nd);}' +
    '        if(nd.querySelectorAll){var sub=nd.querySelectorAll("video,audio");for(var s=0;s<sub.length;s++){connectEl(sub[s]);}}' +
    '  }}});' +
    '  window.__eqObs.observe(document.documentElement,{childList:true,subtree:true});' +
    '}' +
    'window.__eqActive=true;' +
    'return "eq-ok:"+window.__eqOk.length+":"+window.__eqSkip.length;' +
    '})()',
    true
  ).then(function(res) {
    // Diagnostics + mid-load retry. The script may run while the DOM is still
    // empty (did-navigate fires before the player creates its <video>) —
    // retry once so the EQ actually attaches instead of silently no-op'ing.
    var m = /^eq-ok:(\d+):(\d+)$/.exec(String(res || ''));
    if (!m) return;
    var attached = parseInt(m[1], 10) || 0;
    var failed = parseInt(m[2], 10) || 0;
    if (attached === 0 && failed === 0 && !_retried) {
      setTimeout(function() { eqInject(tab, true); }, 1500);
      return;
    }
    if (attached === 0 && failed > 0 && typeof _showToast === 'function') {
      _showToast(' Equalizer cannot attach on this site: the player routes audio through its own WebAudio graph.', 'eq-attach-info', null, 'info');
    }
  }).catch(function() {
    if (!_retried) setTimeout(function() { eqInject(tab, true); }, 1500);
  });
}

function eqRemoveFromAllTabs() {
  tabs.forEach(function(tab) {
    if (tab.webview && !tab._isSleeping) {
      tab.webview.executeJavaScript(
        '(function(){' +
        'if(window.__eqCtx){try{if(window.__eqCtx.state==="suspended"&&window.__eqCtx.resume)window.__eqCtx.resume();}catch(e){}}' +
        'if(window.__eqFilters){for(var i=0;i<window.__eqFilters.length;i++){window.__eqFilters[i].gain.value=0;}}' +
        'if(window.__eqGain){window.__eqGain.gain.value=1.0;}' +
        'window.__eqActive=false;' +
        'return 0})()',
        true
      ).catch(function() {});
    }
  });
}

function toggleEqPanel() {
  var panel = document.getElementById('eqPanel');
  if (!panel) return;
  if (panel.classList.contains('open')) {
    panel.classList.remove('open');
  } else {
    document.querySelectorAll('.media-panel.open,.scripts-panel.open,.download-panel.open,.autofill-panel.open,.adblock-panel.open,.site-info-panel.open').forEach(function(p) { p.classList.remove('open'); });
    panel.classList.add('open');
    eqUpdateUI();
  }
}

(function setupEqualizer() {
  var panel = document.getElementById('eqPanel');
  var bandsContainer = document.getElementById('eqBands');
  var toggle = document.getElementById('eqToggle');
  var preset = document.getElementById('eqPreset');
  var preamp = document.getElementById('eqPreamp');
  var preampVal = document.getElementById('eqPreampVal');
  if (!panel) return;

  var freqLabels = ['60', '170', '310', '600', '1k', '3k', '6k', '12k', '16k'];
  var html = '';
  for (var i = 0; i < _eqBands.length; i++) {
    html += '<div class="eq-band">' +
      '<div class="eq-band-val">' + (_eqState.gains[i] > 0 ? '+' : '') + (_eqState.gains[i] || 0) + '</div>' +
      '<input type="range" class="eq-band-slider" min="-12" max="12" value="' + (_eqState.gains[i] || 0) + '" step="1" data-idx="' + i + '">' +
      '<div class="eq-band-freq">' + freqLabels[i] + '</div>' +
      '</div>';
  }
  bandsContainer.innerHTML = html;

  bandsContainer.querySelectorAll('.eq-band-slider').forEach(function(sl) {
    sl.addEventListener('input', function() {
      var idx = parseInt(this.getAttribute('data-idx'));
      var val = parseFloat(this.value);
      _eqState.gains[idx] = val;
      _eqState.preset = 'custom';
      if (preset) preset.value = 'custom';
      this.previousElementSibling.textContent = (val > 0 ? '+' : '') + val;
      eqApplyToAllTabs();
      eqSaveSettings();
    });
  });

  if (toggle) toggle.addEventListener('change', function() {
    _eqState.enabled = toggle.checked;
    if (_eqState.enabled) {
      eqApplyToAllTabs();
    } else {
      eqRemoveFromAllTabs();
    }
    eqSaveSettings();
  });

  if (preset) preset.addEventListener('change', function() {
    var p = preset.value;
    if (p === 'custom') return;
    _eqState.preset = p;
    _eqState.gains = (_eqPresets[p] || _eqPresets.flat).slice();
    eqUpdateUI();
    eqApplyToAllTabs();
    eqSaveSettings();
  });

  if (preamp) preamp.addEventListener('input', function() {
    _eqState.preamp = parseFloat(this.value);
    if (preampVal) preampVal.textContent = (_eqState.preamp > 0 ? '+' : '') + _eqState.preamp + ' dB';
    eqApplyToAllTabs();
    eqSaveSettings();
  });

  // Sync the checkbox with the real (false) state BEFORE the async settings
  // load — the HTML used to ship checked="checked" while _eqState.enabled
  // was false, so the panel showed ON while the EQ was actually off.
  eqUpdateUI();
  eqLoadSettings();
})();

// ============== HOVER TRANSLATE ==============
var _hoverTranslateSettings = {
  enabled: false,
  targetLang: 'ru',
  trigger: 'hover',
  delay: 600
};

function htLoadSettings() {
  if (!window.electronAPI || !window.electronAPI.getCustomizationSettings) return;
  window.electronAPI.getCustomizationSettings().then(function(s) {
    if (s && s.settings && s.settings.hoverTranslate) {
      _hoverTranslateSettings = Object.assign(_hoverTranslateSettings, s.settings.hoverTranslate);
      htUpdateUI();
    }
  }).catch(function() {});
}

function htSaveSettings() {
  if (!window.electronAPI || !window.electronAPI.saveCustomizationSettings) return;
  window.electronAPI.saveCustomizationSettings({ hoverTranslate: JSON.parse(JSON.stringify(_hoverTranslateSettings)) }).catch(function() {});
}

function htConfigString() {
  return JSON.stringify({
    targetLang: _hoverTranslateSettings.targetLang,
    trigger: _hoverTranslateSettings.trigger,
    delay: parseInt(_hoverTranslateSettings.delay, 10) || 600
  });
}

function injectHoverTranslate(tabData) {
  if (!tabData || !tabData.webview || !tabData.isReady) return;
  if (!canExecInWebview(tabData.webview)) return;
  if (!_hoverTranslateSettings.enabled) return;
  var cfg = htConfigString();
  tabData.webview.executeJavaScript(
    '(function(){' +
    'try{Object.defineProperty(window,"__htCFG",{value:' + cfg + ',enumerable:false,configurable:true,writable:true});}catch(e){window.__htCFG=' + cfg + ';}' +
    'if(window.__htActive)return "active";try{Object.defineProperty(window,"__htActive",{value:true,enumerable:false,configurable:true});}catch(e){window.__htActive=true;}' +
    'if(!document.getElementById("__ht_style")){var st=document.createElement("style");st.id="__ht_style";st.textContent=".__ht-popup{position:fixed;z-index:2147483647;max-width:320px;min-width:110px;background:rgba(30,30,46,0.96);color:#e6e6e6;border:1px solid rgba(255,255,255,0.15);border-radius:10px;padding:9px 13px;font-size:13px;font-family:system-ui,-apple-system,sans-serif;line-height:1.5;box-shadow:0 8px 28px rgba(0,0,0,0.5);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);pointer-events:none;opacity:0;transition:opacity 0.15s ease}.__ht-popup.__ht-show{opacity:1}.__ht-w{font-weight:600;color:#7aa2f7;display:block;margin-bottom:2px}.__ht-t{color:#e6e6e6}.__ht-l{font-size:10px;color:#7a8290;margin-top:5px;display:block}.__ht-lo{color:#888}";document.documentElement.appendChild(st);}' +
    'try{Object.defineProperty(window,"__htCache",{value:{},enumerable:false,configurable:true,writable:true});}catch(e){window.__htCache={};}' +
    'var _popup=null,_curWord="",_pending=false,_timer=null;' +
    'function isWordChar(c){return !!c && /[\\w\\u00C0-\\u00FF\\u0400-\\u04FF]/.test(c);}' +
    'function getWordAt(x,y){' +
    '  var r=null;' +
    '  if(document.caretRangeFromPoint){r=document.caretRangeFromPoint(x,y);}' +
    '  else if(document.caretPositionFromPoint){var p=document.caretPositionFromPoint(x,y);if(p){r=document.createRange();try{r.setStart(p.offsetNode,p.offset);r.setEnd(p.offsetNode,p.offset);}catch(e){r=null;}}}' +
    '  if(!r||!r.startContainer||r.startContainer.nodeType!==3)return "";' +
    '  var node=r.startContainer,text=node.nodeValue||"",off=r.startOffset;' +
    '  if(off>text.length)off=text.length;' +
    '  var start=off;while(start>0&&isWordChar(text[start-1]))start--;' +
    '  var end=off;while(end<text.length&&isWordChar(text[end]))end++;' +
    '  if(end-start<2||end-start>50)return "";' +
    '  return text.substring(start,end);' +
    '}' +
    'function showPopup(html,x,y){' +
    '  if(!_popup){_popup=document.createElement("div");_popup.className="__ht-popup";document.documentElement.appendChild(_popup);}' +
    '  _popup.innerHTML=html;' +
    '  var px=x+14;if(px+_popup.offsetWidth>window.innerWidth-8)px=Math.max(8,x-_popup.offsetWidth-14);' +
    '  var py=y+18;if(py+_popup.offsetHeight>window.innerHeight-8)py=Math.max(8,y-_popup.offsetHeight-12);' +
    '  _popup.style.left=px+"px";_popup.style.top=py+"px";_popup.classList.add("__ht-show");' +
    '}' +
    'function hidePopup(){if(_popup)_popup.classList.remove("__ht-show");}' +
    'function escHtml(s){return String(s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;","\\"":"&quot;"}[c];});}' +
    'function doTranslate(word,x,y){' +
    '  if(window.__htCache[word]){showPopup(window.__htCache[word],x,y);return;}' +
    '  if(_pending)return;' +
    '  if(!window.__spzSend){return;}' +
    '  _pending=true;' +
    '  showPopup("<span class=\\"__ht-lo\\">Translating…</span>",x,y);' +
    '  window.__spzSend("translate",{text:word,from:"auto",to:window.__htCFG.targetLang},function(r){' +
    '    _pending=false;' +
    '    if(r&&r.success&&r.translated&&r.translated!==word){' +
    '      var lang=r.from&&r.to?"<span class=\\"__ht-l\\">"+escHtml(r.from)+" \\u2192 "+escHtml(r.to)+"</span>":"";' +
    '      var html="<span class=\\"__ht-w\\">"+escHtml(word)+"</span><span class=\\"__ht-t\\">"+escHtml(r.translated)+"</span>"+lang;' +
    '      window.__htCache[word]=html;' +
    '      showPopup(html,x,y);' +
    '    }else{hidePopup();}' +
    '  });' +
    '}' +
    'var _htMove=function(e){' +
    '  var C=window.__htCFG;' +
    '  if(C.trigger!=="hover"){var held=C.trigger==="ctrl"?e.ctrlKey:(C.trigger==="alt"?e.altKey:false);if(!held){if(_timer){clearTimeout(_timer);_timer=null;}hidePopup();_curWord="";return;}}' +
    '  var word=getWordAt(e.clientX,e.clientY);' +
    '  if(!word){if(_timer){clearTimeout(_timer);_timer=null;}hidePopup();_curWord="";return;}' +
    '  if(word===_curWord)return;' +
    '  _curWord=word;' +
    '  if(_timer)clearTimeout(_timer);' +
    '  var px=e.clientX,py=e.clientY;' +
    '  _timer=setTimeout(function(){doTranslate(word,px,py);},C.delay);' +
    '};' +
    'var _htDismiss=function(){if(_timer){clearTimeout(_timer);_timer=null;}hidePopup();_curWord="";};' +
    'try{Object.defineProperty(window,"__htMove",{value:_htMove,enumerable:false,configurable:true,writable:true});}catch(e){window.__htMove=_htMove;}' +
    'try{Object.defineProperty(window,"__htDismiss",{value:_htDismiss,enumerable:false,configurable:true,writable:true});}catch(e){window.__htDismiss=_htDismiss;}' +
    'document.addEventListener("mousemove",window.__htMove,true);' +
    'document.addEventListener("mousedown",window.__htDismiss,true);' +
    'document.addEventListener("keydown",function(ev){if(ev.key==="Escape"){window.__htDismiss();}},true);' +
    'window.addEventListener("scroll",window.__htDismiss,true);' +
    'window.addEventListener("blur",window.__htDismiss);' +
    'return "ok";' +
    '})()'
  ).catch(function() {});
}

function removeHoverTranslate(webview) {
  if (!webview) return;
  webview.executeJavaScript(
    '(function(){' +
    'if(!window.__htActive)return;' +
    'window.__htActive=false;' +
    'if(window.__htMove){document.removeEventListener("mousemove",window.__htMove,true);window.__htMove=null;}' +
    'if(window.__htDismiss){document.removeEventListener("mousedown",window.__htDismiss,true);window.removeEventListener("scroll",window.__htDismiss,true);window.removeEventListener("blur",window.__htDismiss);window.__htDismiss=null;}' +
    'var p=document.querySelector(".__ht-popup");if(p)p.remove();' +
    '})()'
  ).catch(function() {});
}

function htApplyToAllTabs() {
  tabs.forEach(function(tab) {
    if (tab.webview && tab.isReady && !tab._isSleeping) {
      if (_hoverTranslateSettings.enabled) injectHoverTranslate(tab);
      else removeHoverTranslate(tab.webview);
    }
  });
}

function htUpdateUI() {
  var toggle = document.getElementById('htToggle');
  if (toggle) toggle.checked = _hoverTranslateSettings.enabled;
  var lang = document.getElementById('htLang');
  if (lang) lang.value = _hoverTranslateSettings.targetLang;
  var trigger = document.getElementById('htTrigger');
  if (trigger) trigger.value = _hoverTranslateSettings.trigger;
  var delay = document.getElementById('htDelay');
  if (delay) delay.value = _hoverTranslateSettings.delay;
  var delayVal = document.getElementById('htDelayVal');
  if (delayVal) delayVal.textContent = _hoverTranslateSettings.delay + ' ms';
  var hmCheck = document.getElementById('hmHoverTrCheck');
  if (hmCheck) hmCheck.className = 'hm-check' + (_hoverTranslateSettings.enabled ? ' active' : '');
}

function toggleHoverTranslate() {
  _hoverTranslateSettings.enabled = !_hoverTranslateSettings.enabled;
  htUpdateUI();
  htApplyToAllTabs();
  htSaveSettings();
}

function toggleHtPanel() {
  var panel = document.getElementById('htPanel');
  if (!panel) return;
  if (panel.classList.contains('open')) {
    panel.classList.remove('open');
  } else {
    document.querySelectorAll('.media-panel.open,.scripts-panel.open,.download-panel.open,.autofill-panel.open,.adblock-panel.open,.site-info-panel.open,.eq-panel.open').forEach(function(p) { p.classList.remove('open'); });
    panel.classList.add('open');
    htUpdateUI();
  }
}

(function setupHoverTranslate() {
  htLoadSettings();
  var panel = document.getElementById('htPanel');
  if (!panel) return;
  var toggle = document.getElementById('htToggle');
  if (toggle) toggle.addEventListener('change', function() {
    _hoverTranslateSettings.enabled = toggle.checked;
    htApplyToAllTabs();
    htSaveSettings();
    htUpdateUI();
  });
  var lang = document.getElementById('htLang');
  if (lang) lang.addEventListener('change', function() {
    _hoverTranslateSettings.targetLang = lang.value;
    htSaveSettings();
    htApplyToAllTabs();
  });
  var trigger = document.getElementById('htTrigger');
  if (trigger) trigger.addEventListener('change', function() {
    _hoverTranslateSettings.trigger = trigger.value;
    htSaveSettings();
    htApplyToAllTabs();
  });
  var delay = document.getElementById('htDelay');
  if (delay) delay.addEventListener('input', function() {
    _hoverTranslateSettings.delay = parseInt(delay.value, 10);
    var delayVal = document.getElementById('htDelayVal');
    if (delayVal) delayVal.textContent = _hoverTranslateSettings.delay + ' ms';
    htSaveSettings();
    htApplyToAllTabs();
  });
  document.addEventListener('click', function(e) {
    if (!panel.classList.contains('open')) return;
    var hmItem = document.getElementById('hmHoverTr');
    if (panel.contains(e.target)) return;
    if (hmItem && hmItem.contains(e.target)) return;
    panel.classList.remove('open');
  });
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && panel.classList.contains('open')) panel.classList.remove('open');
  });
})();

// Profile management is in Settings.html. Here we only expose helpers for QC commands.
window._profilesData = null;
if (window.electronAPI && window.electronAPI.getProfiles) {
  window.electronAPI.getProfiles().then(function(d) { window._profilesData = d; });
}

// ============== WORKSPACES ==============
var _workspaces = [];
var _activeWorkspaceId = 'ws-default';
var _wsSelectedIcon = '💼';
var _wsSelectedColor = '#667eea';
var _wsColorPalette = [
  '#667eea', '#764ba2', '#f093fb', '#4facfe', '#43e97b',
  '#fa709a', '#fee140', '#ff9a9e', '#a18cd1', '#fcb69f',
  '#ff9a76', '#00f2fe', '#fbc2eb', '#6a11cb', '#e44d26'
];
var _wsIconOptions = [
  '🌐', '💼', '🏠', '📚', '🎮', '🎵', '🛒', '🔧', '📝', '🎯',
  '💻', '🎨', '⚡', '🔥', '❤️', '🌟', '🎬', '📸', '🚀', '🎉'
];

function updateWorkspaceButton() {
  var btn = document.getElementById('workspaceBtn');
  var icon = document.getElementById('wsBtnIcon');
  var nameEl = document.getElementById('wsBtnName');
  var ws = _workspaces.find(function(w) { return w.id === _activeWorkspaceId; });
  if (!ws && _workspaces.length) ws = _workspaces[0];
  if (!ws) return;
  if (icon) icon.innerHTML = _icon(ws.icon || '🌐');
  if (nameEl) nameEl.textContent = ws.name || '';
  if (btn) {
    btn.style.setProperty('--ws-color', ws.color || '#667eea');
    btn.title = ws.name || 'Workspaces';
  }
}

function saveCurrentWorkspaceTabs() {
  if (!window.electronAPI || !window.electronAPI.setWorkspaceTabs) return;
  var tabsData = tabs.map(function(tab) {
    return { url: getTabUrlForSave(tab), title: tab.title };
  }).filter(function(t) { return t.url; });
  window.electronAPI.setWorkspaceTabs(_activeWorkspaceId, tabsData);
}

function switchWorkspace(targetId) {
  if (targetId === _activeWorkspaceId) { closeWorkspacePanel(); return; }
  if (!_workspaces.find(function(ws) { return ws.id === targetId; })) return;

  saveCurrentWorkspaceTabs();

  tabs.forEach(function(t) {
    t.element.remove();
    t.webview.remove();
    delete _tabPreviewCache[t.id];
    delete _tabAudioPlaying[t.id];
    delete _tabMuted[t.id];
    delete _tabZoom[t.id];
    stopLoadingBar(t.id);
  });
  tabs = [];
  activeTabId = null;

  _activeWorkspaceId = targetId;
  if (window.electronAPI && window.electronAPI.setActiveWorkspace) {
    window.electronAPI.setActiveWorkspace(targetId);
  }

  loadWorkspaceTabs(targetId);
  updateWorkspaceButton();
  closeWorkspacePanel();
}

function loadWorkspaceTabs(workspaceId) {
  if (!window.electronAPI || !window.electronAPI.getWorkspaceTabs) {
    createNewTab('MainPage/index.html');
    return;
  }
  window.electronAPI.getWorkspaceTabs(workspaceId).then(function(savedTabs) {
    if (savedTabs && savedTabs.length > 0) {
      _restoreTabs(savedTabs);
    } else {
      window.electronAPI.getSavedTabs().then(function(globalTabs) {
        _restoreTabs(globalTabs && globalTabs.length > 0 && workspaceId === 'ws-default' ? globalTabs : []);
      }).catch(function() { createNewTab('MainPage/index.html'); });
    }
  }).catch(function() { createNewTab('MainPage/index.html'); });
}

function createWorkspace(name, icon, color) {
  var newWs = {
    id: 'ws-' + Date.now(),
    name: name || 'New workspace',
    icon: icon || '💼',
    color: color || '#667eea',
    createdAt: Date.now()
  };
  _workspaces.push(newWs);
  if (window.electronAPI && window.electronAPI.saveWorkspaces) {
    window.electronAPI.saveWorkspaces(_workspaces);
  }
  renderWorkspacePanel();
  switchWorkspace(newWs.id);
}

function deleteWorkspace(id) {
  if (id === 'ws-default') return;
  var idx = _workspaces.findIndex(function(ws) { return ws.id === id; });
  if (idx === -1) return;
  _workspaces.splice(idx, 1);
  if (window.electronAPI && window.electronAPI.saveWorkspaces) {
    window.electronAPI.saveWorkspaces(_workspaces);
  }
  if (window.electronAPI && window.electronAPI.setWorkspaceTabs) {
    window.electronAPI.setWorkspaceTabs(id, []);
  }
  if (_activeWorkspaceId === id) {
    switchWorkspace('ws-default');
  } else {
    renderWorkspacePanel();
  }
}

function renderWorkspacePanel() {
  var list = document.getElementById('wsPanelList');
  if (!list) return;
  list.innerHTML = '';
  _workspaces.forEach(function(ws) {
    var item = document.createElement('div');
    item.className = 'ws-item' + (ws.id === _activeWorkspaceId ? ' active' : '');
    if (ws.id === _activeWorkspaceId) {
      item.style.setProperty('--ws-color', ws.color || '#667eea');
    }
    item.innerHTML = '<div class="ws-item-icon" style="background:' + (ws.color || '#667eea') + '22;color:' + (ws.color || '#667eea') + '">' + _icon(ws.icon || '🌐') + '</div>' +
      '<div class="ws-item-info"><div class="ws-item-name">' + escapeHtmlSimple(ws.name || 'Untitled') + '</div></div>' +
      (ws.id !== 'ws-default' ? '<button class="ws-item-delete" data-id="' + ws.id + '" title="Delete">&#10005;</button>' : '');
    if (ws.id === _activeWorkspaceId) {
      item.style.background = (ws.color || '#667eea') + '15';
      item.style.setProperty('--ws-accent', ws.color || '#667eea');
    }
    item.addEventListener('click', function(e) {
      if (e.target.closest('.ws-item-delete')) return;
      switchWorkspace(ws.id);
    });
    var delBtn = item.querySelector('.ws-item-delete');
    if (delBtn) {
      delBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        deleteWorkspace(ws.id);
      });
    }
    list.appendChild(item);
  });
  if (_workspaces.length <= 1) {
    document.getElementById('wsPanelAdd').textContent = '+ Create first workspace';
  } else {
    document.getElementById('wsPanelAdd').textContent = '+ New workspace';
  }
}

function closeWorkspacePanel() {
  var panel = document.getElementById('workspacePanel');
  if (panel) panel.classList.remove('open');
}

function openWorkspacePanel() {
  renderWorkspacePanel();
  var panel = document.getElementById('workspacePanel');
  var btn = document.getElementById('workspaceBtn');
  if (panel && btn) {
    var rect = btn.getBoundingClientRect();
    panel.style.top = rect.bottom + 'px';
    panel.style.left = Math.max(0, Math.min(rect.left, window.innerWidth - 260)) + 'px';
    panel.classList.add('open');
  } else if (panel) {
    panel.classList.add('open');
  }
}

function toggleWorkspacePanel() {
  var panel = document.getElementById('workspacePanel');
  if (panel && panel.classList.contains('open')) closeWorkspacePanel();
  else openWorkspacePanel();
}

document.getElementById('workspaceBtn').addEventListener('click', function(e) {
  e.stopPropagation();
  toggleWorkspacePanel();
});

document.addEventListener('click', function(e) {
  if (!e.target.closest('#workspacePanel') && !e.target.closest('#workspaceBtn')) {
    closeWorkspacePanel();
  }
});

window.addEventListener('pointerdown', function(e) {
  if (e.button === 3 || e.button === 4) {
    e.preventDefault();
  }
}, true);

window.addEventListener('pointerup', function(e) {
  if (e.button === 3) {
    e.preventDefault();
    var tab = getActiveTab();
    if (tab && tab.webview && tab.isReady) {
      try { if (tab.webview.canGoBack()) tab.webview.goBack(); } catch(err) {}
    }
  } else if (e.button === 4) {
    e.preventDefault();
    var tab2 = getActiveTab();
    if (tab2 && tab2.webview && tab2.isReady) {
      try { if (tab2.webview.canGoForward()) tab2.webview.goForward(); } catch(err) {}
    }
  }
}, true);

document.getElementById('wsPanelAdd').addEventListener('click', function() {
  closeWorkspacePanel();
  showCreateWorkspaceModal();
});

function showCreateWorkspaceModal() {
  var modal = document.getElementById('wsCreateModal');
  if (!modal) return;
  document.getElementById('wsCreateName').value = '';
  _wsSelectedIcon = '💼';
  _wsSelectedColor = _wsColorPalette[Math.floor(Math.random() * _wsColorPalette.length)];
  renderWsIconGrid();
  renderWsColorGrid();
  modal.classList.add('open');
  setTimeout(function() { document.getElementById('wsCreateName').focus(); }, 50);
}

function hideCreateWorkspaceModal() {
  var modal = document.getElementById('wsCreateModal');
  if (modal) modal.classList.remove('open');
}

function renderWsIconGrid() {
  var grid = document.getElementById('wsIconGrid');
  if (!grid) return;
  grid.innerHTML = '';
  _wsIconOptions.forEach(function(iconKey) {
    var el = document.createElement('span');
    el.className = 'ws-icon-item' + (iconKey === _wsSelectedIcon ? ' selected' : '');
    el.innerHTML = _icon(iconKey);
    el.addEventListener('click', function() {
      _wsSelectedIcon = iconKey;
      renderWsIconGrid();
    });
    grid.appendChild(el);
  });
}

function renderWsColorGrid() {
  var grid = document.getElementById('wsColorGrid');
  if (!grid) return;
  grid.innerHTML = '';
  _wsColorPalette.forEach(function(color) {
    var el = document.createElement('span');
    el.className = 'ws-color-item' + (color === _wsSelectedColor ? ' selected' : '');
    el.style.background = color;
    el.addEventListener('click', function() {
      _wsSelectedColor = color;
      renderWsColorGrid();
    });
    grid.appendChild(el);
  });
}

document.getElementById('wsCreateOk').addEventListener('click', function() {
  var name = document.getElementById('wsCreateName').value.trim() || 'New workspace';
  createWorkspace(name, _wsSelectedIcon, _wsSelectedColor);
  hideCreateWorkspaceModal();
});

document.getElementById('wsCreateCancel').addEventListener('click', hideCreateWorkspaceModal);
document.getElementById('wsCreateClose').addEventListener('click', hideCreateWorkspaceModal);

document.getElementById('wsCreateName').addEventListener('keydown', function(e) {
  if (e.key === 'Enter') { e.preventDefault(); document.getElementById('wsCreateOk').click(); }
  if (e.key === 'Escape') hideCreateWorkspaceModal();
});

function doMultiSearch(query) {
  if (!query) return;
  var api = window.electronAPI;
  if (!api || !api.getMultiSearchEngines) {
    navigateTo(query, activeTabId);
    return;
  }
  api.getMultiSearchEngines().then(function(enabled) {
    var ENGINES = {
      google: { name: 'Google', url: 'https://www.google.com/search?q=' },
      duckduckgo: { name: 'DuckDuckGo', url: 'https://duckduckgo.com/?q=' },
      bing: { name: 'Bing', url: 'https://www.bing.com/search?q=' },
      startpozi: { name: 'StartPOZI', url: 'https://startpozi.com/search.html?q=' }
    };
    var ids = [];
    Object.keys(enabled).forEach(function(id) {
      if (enabled[id] && ENGINES[id]) ids.push(id);
    });
    var customPromise = api.getMultiSearchCustomEngines
      ? api.getMultiSearchCustomEngines()
      : Promise.resolve([]);
    customPromise.then(function(customEngines) {
      if (Array.isArray(customEngines)) {
        customEngines.forEach(function(eng) {
          ENGINES[eng.id] = { name: eng.name, url: eng.url };
          if (enabled[eng.id]) ids.push(eng.id);
        });
      }
      if (ids.length === 0) {
        navigateTo(query, activeTabId);
        return;
      }
      openMultiSearchPanel(query, ids, ENGINES);
    });
  });
}

var _msPanel = null;
var _msWebviews = [];
var _msActiveIdx = 0;

function openMultiSearchPanel(query, ids, engines) {
  closeMultiSearchPanel();

  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (!tab) return;

  tab.webview.style.display = 'none';

  var bc = document.querySelector('.browser-content');

  var panel = document.createElement('div');
  panel.id = 'msPanel';
  panel.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;display:flex;flex-direction:column;background:var(--bg-color,#1a1a2e);z-index:100;';

  var toolbar = document.createElement('div');
  toolbar.style.cssText = 'display:flex;align-items:center;gap:0;padding:0 8px;background:rgba(30,30,45,0.95);border-bottom:1px solid rgba(255,255,255,0.12);flex-shrink:0;height:42px;';

  var closeBtn = document.createElement('button');
  closeBtn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
  closeBtn.style.cssText = 'background:none;border:none;color:rgba(255,255,255,0.6);cursor:pointer;padding:8px;border-radius:6px;display:flex;align-items:center;transition:background 0.15s;';
  closeBtn.title = 'Close multi-search';
  closeBtn.addEventListener('mouseenter', function() { closeBtn.style.background = 'rgba(255,255,255,0.1)'; });
  closeBtn.addEventListener('mouseleave', function() { closeBtn.style.background = 'none'; });
  closeBtn.addEventListener('click', function() { closeMultiSearchPanel(); });
  toolbar.appendChild(closeBtn);

  var queryLabel = document.createElement('span');
  queryLabel.style.cssText = 'font-size:13px;color:rgba(255,255,255,0.7);margin:0 12px 0 4px;white-space:nowrap;max-width:200px;overflow:hidden;text-overflow:ellipsis;';
  queryLabel.textContent = '\u00AB' + query + '\u00BB';
  toolbar.appendChild(queryLabel);

  var sep = document.createElement('div');
  sep.style.cssText = 'width:1px;height:24px;background:rgba(255,255,255,0.12);margin:0 8px;flex-shrink:0;';
  toolbar.appendChild(sep);

  var tabBtns = [];
  ids.forEach(function(id, idx) {
    var btn = document.createElement('button');
    btn.textContent = engines[id].name;
    btn.style.cssText = 'padding:8px 16px;border:none;background:' + (idx === 0 ? 'rgba(102,126,234,0.25)' : 'transparent') + ';color:' + (idx === 0 ? '#fff' : 'rgba(255,255,255,0.6)') + ';font-size:13px;font-weight:500;cursor:pointer;border-radius:6px;margin:0 2px;transition:all 0.15s;white-space:nowrap;';
    btn.addEventListener('mouseenter', function() { if (_msActiveIdx !== idx) btn.style.background = 'rgba(255,255,255,0.08)'; });
    btn.addEventListener('mouseleave', function() { if (_msActiveIdx !== idx) btn.style.background = 'transparent'; });
    btn.addEventListener('click', function() {
      _msActiveIdx = idx;
      tabBtns.forEach(function(b, i) {
        b.style.background = i === idx ? 'rgba(102,126,234,0.25)' : 'transparent';
        b.style.color = i === idx ? '#fff' : 'rgba(255,255,255,0.6)';
      });
      _msWebviews.forEach(function(w, i) {
        w.style.display = i === idx ? 'flex' : 'none';
      });
    });
    toolbar.appendChild(btn);
    tabBtns.push(btn);
  });

  var spacer = document.createElement('div');
  spacer.style.cssText = 'flex:1;';
  toolbar.appendChild(spacer);

  var gridToggle = document.createElement('button');
  gridToggle.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/></svg>';
  gridToggle.style.cssText = 'background:none;border:none;color:rgba(255,255,255,0.6);cursor:pointer;padding:8px;border-radius:6px;display:flex;align-items:center;transition:background 0.15s;';
  gridToggle.title = 'Show all at once';
  toolbar.appendChild(gridToggle);

  panel.appendChild(toolbar);

  var contentArea = document.createElement('div');
  contentArea.style.cssText = 'flex:1;position:relative;overflow:hidden;';
  panel.appendChild(contentArea);

  var isGrid = false;
  gridToggle.addEventListener('click', function() {
    isGrid = !isGrid;
    if (isGrid) {
      var cols = ids.length <= 2 ? ids.length : 2;
      var rows = Math.ceil(ids.length / cols);
      contentArea.style.display = 'grid';
      contentArea.style.gridTemplateColumns = 'repeat(' + cols + ', 1fr)';
      contentArea.style.gridTemplateRows = 'repeat(' + rows + ', 1fr)';
      _msWebviews.forEach(function(w) {
        w.style.display = 'flex';
        w.style.position = 'relative';
        w.style.width = '100%';
        w.style.height = '100%';
      });
    } else {
      contentArea.style.display = '';
      contentArea.style.gridTemplateColumns = '';
      contentArea.style.gridTemplateRows = '';
      _msWebviews.forEach(function(w, i) {
        w.style.position = 'absolute';
        w.style.width = '100%';
        w.style.height = '100%';
        w.style.display = i === _msActiveIdx ? 'flex' : 'none';
      });
    }
  });

  ids.forEach(function(id, idx) {
    var wv = document.createElement('webview');
    wv.setAttribute('autosize', 'on');
    wv.setAttribute('allowpopups', '');
    if (webviewPreloadPath) wv.setAttribute('preload', webviewPreloadPath);
    wv.src = engines[id].url + encodeURIComponent(query);
    wv.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;border:none;border-right:1px solid rgba(255,255,255,0.08);border-bottom:1px solid rgba(255,255,255,0.08);' + (idx === 0 ? 'display:flex;' : 'display:none;');
    wv.addEventListener('dom-ready', function() {
      try { if (wv.setUserAgent) wv.setUserAgent(userAgent); } catch(e) {}
    });
    contentArea.appendChild(wv);
    _msWebviews.push(wv);
  });

  bc.appendChild(panel);
  _msPanel = panel;
  _msActiveIdx = 0;
}

function closeMultiSearchPanel() {
  if (_msPanel) {
    _msPanel.remove();
    _msPanel = null;
  }
  _msWebviews = [];
  _msActiveIdx = 0;
  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (tab) {
    tab.webview.style.display = '';
  }
}

// ============== SCREENSHOT TOOL ==============
var _ssActive = false;
var _ssTool = 'rect';
var _ssColor = '#ff0000';
var _ssLineWidth = 3;
var _ssBaseImage = null;
var _ssAnnotations = [];
var _ssIsDrawing = false;
var _ssStartX = 0;
var _ssStartY = 0;
var _ssCurrentPath = [];
var _ssCropRect = null;

function openScreenshotTool() {
  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (!tab || !tab.webview) return;
  try { if (tab.webview.isDestroyed && tab.webview.isDestroyed()) return; } catch(e) { return; }

  tab.webview.capturePage().then(function(img) {
    _ssBaseImage = new Image();
    _ssBaseImage.onload = function() {
      _ssAnnotations = [];
      _ssCropRect = null;
      _ssActive = true;
      var overlay = document.getElementById('ssOverlay');
      overlay.classList.add('active');
      var canvas = document.getElementById('ssCanvas');
      var w = overlay.offsetWidth;
      var h = overlay.offsetHeight;
      canvas.width = w * (window.devicePixelRatio || 1);
      canvas.height = h * (window.devicePixelRatio || 1);
      canvas.style.width = w + 'px';
      canvas.style.height = h + 'px';
      var ctx = canvas.getContext('2d');
      ctx.scale(window.devicePixelRatio || 1, window.devicePixelRatio || 1);
      _ssRedraw(ctx, w, h);
    };
    _ssBaseImage.src = img.toDataURL();
  }).catch(function() {});
}

function _ssRedraw(ctx, w, h) {
  ctx.clearRect(0, 0, w, h);
  if (_ssBaseImage) {
    var imgW = _ssBaseImage.naturalWidth || _ssBaseImage.width;
    var imgH = _ssBaseImage.naturalHeight || _ssBaseImage.height;
    var scale = Math.min(w / imgW, h / imgH);
    var dw = imgW * scale;
    var dh = imgH * scale;
    var dx = (w - dw) / 2;
    var dy = (h - dh) / 2;
    ctx.drawImage(_ssBaseImage, dx, dy, dw, dh);
  }
  for (var i = 0; i < _ssAnnotations.length; i++) {
    _ssDrawAnnotation(ctx, _ssAnnotations[i]);
  }
}

function _ssDrawAnnotation(ctx, a) {
  ctx.save();
  if (a.type === 'rect') {
    ctx.strokeStyle = a.color;
    ctx.lineWidth = a.width;
    ctx.lineJoin = 'round';
    var x = Math.min(a.x1, a.x2);
    var y = Math.min(a.y1, a.y2);
    var w = Math.abs(a.x2 - a.x1);
    var h = Math.abs(a.y2 - a.y1);
    if (a.filled) {
      ctx.fillStyle = a.color + '33';
      ctx.fillRect(x, y, w, h);
    }
    ctx.strokeRect(x, y, w, h);
  } else if (a.type === 'arrow') {
    ctx.strokeStyle = a.color;
    ctx.fillStyle = a.color;
    ctx.lineWidth = a.width;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(a.x1, a.y1);
    ctx.lineTo(a.x2, a.y2);
    ctx.stroke();
    var angle = Math.atan2(a.y2 - a.y1, a.x2 - a.x1);
    var headLen = Math.max(12, a.width * 4);
    ctx.beginPath();
    ctx.moveTo(a.x2, a.y2);
    ctx.lineTo(a.x2 - headLen * Math.cos(angle - Math.PI / 6), a.y2 - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(a.x2 - headLen * Math.cos(angle + Math.PI / 6), a.y2 - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
  } else if (a.type === 'line') {
    ctx.strokeStyle = a.color;
    ctx.lineWidth = a.width;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(a.x1, a.y1);
    ctx.lineTo(a.x2, a.y2);
    ctx.stroke();
  } else if (a.type === 'freehand') {
    if (!a.path || a.path.length < 2) { ctx.restore(); return; }
    ctx.strokeStyle = a.color;
    ctx.lineWidth = a.width;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(a.path[0].x, a.path[0].y);
    for (var j = 1; j < a.path.length; j++) {
      ctx.lineTo(a.path[j].x, a.path[j].y);
    }
    ctx.stroke();
  } else if (a.type === 'text') {
    ctx.fillStyle = a.color;
    ctx.font = (a.fontSize || 16) + 'px sans-serif';
    ctx.textBaseline = 'top';
    var lines = (a.text || '').split('\n');
    for (var k = 0; k < lines.length; k++) {
      ctx.fillText(lines[k], a.x1, a.y1 + k * (a.fontSize || 16) * 1.3);
    }
  } else if (a.type === 'blur') {
    if (!a.path || a.path.length < 2) { ctx.restore(); return; }
    ctx.strokeStyle = 'rgba(200,200,200,0.7)';
    ctx.lineWidth = a.width * 4;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.globalCompositeOperation = 'source-over';
    ctx.beginPath();
    ctx.moveTo(a.path[0].x, a.path[0].y);
    for (var m = 1; m < a.path.length; m++) {
      ctx.lineTo(a.path[m].x, a.path[m].y);
    }
    ctx.stroke();
    ctx.globalCompositeOperation = 'destination-out';
    ctx.lineWidth = a.width * 3;
    ctx.beginPath();
    ctx.moveTo(a.path[0].x, a.path[0].y);
    for (var n = 1; n < a.path.length; n++) {
      ctx.lineTo(a.path[n].x, a.path[n].y);
    }
    ctx.stroke();
    ctx.globalCompositeOperation = 'source-over';
    var step = Math.max(2, a.width);
    for (var p = 0; p < a.path.length; p += 1) {
      var px = a.path[p].x;
      var py = a.path[p].y;
      for (var ox = -a.width * 2; ox < a.width * 2; ox += step) {
        for (var oy = -a.width * 2; oy < a.width * 2; oy += step) {
          if (ox * ox + oy * oy < a.width * a.width * 4) {
            ctx.fillStyle = 'rgba(40,40,50,' + (0.08 + Math.random() * 0.04) + ')';
            ctx.fillRect(px + ox, py + oy, step, step);
          }
        }
      }
    }
  } else if (a.type === 'crop') {
    var cx = Math.min(a.x1, a.x2);
    var cy = Math.min(a.y1, a.y2);
    var cw = Math.abs(a.x2 - a.x1);
    var ch = Math.abs(a.y2 - a.y1);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.setLineDash([6, 4]);
    ctx.strokeRect(cx, cy, cw, ch);
    ctx.setLineDash([]);
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.fillRect(0, 0, ctx.canvas.width, cy);
    ctx.fillRect(0, cy + ch, ctx.canvas.width, ctx.canvas.height - cy - ch);
    ctx.fillRect(0, cy, cx, ch);
    ctx.fillRect(cx + cw, cy, ctx.canvas.width - cx - cw, ch);
  }
  ctx.restore();
}

function closeScreenshotTool() {
  _ssActive = false;
  _ssAnnotations = [];
  _ssCropRect = null;
  document.getElementById('ssOverlay').classList.remove('active');
  document.getElementById('ssTextInput').style.display = 'none';
}

function _ssGetCoords(e) {
  var canvas = document.getElementById('ssCanvas');
  var rect = canvas.getBoundingClientRect();
  return { x: e.clientX - rect.left, y: e.clientY - rect.top };
}

function _ssCommitCrop(ann) {
  var cx = Math.min(ann.x1, ann.x2);
  var cy = Math.min(ann.y1, ann.y2);
  var cw = Math.abs(ann.x2 - ann.x1);
  var ch = Math.abs(ann.y2 - ann.y1);
  if (cw < 10 || ch < 10) return;
  var dpr = window.devicePixelRatio || 1;
  var canvas = document.getElementById('ssCanvas');
  var ctx = canvas.getContext('2d');
  _ssRedraw(ctx, canvas.offsetWidth, canvas.offsetHeight);
  var imgData = ctx.getImageData(cx * dpr, cy * dpr, cw * dpr, ch * dpr);
  var tmpCanvas = document.createElement('canvas');
  tmpCanvas.width = cw * dpr;
  tmpCanvas.height = ch * dpr;
  tmpCanvas.getContext('2d').putImageData(imgData, 0, 0);
  _ssBaseImage = new Image();
  _ssBaseImage.onload = function() {
    _ssAnnotations = [];
    var newCanvas = document.getElementById('ssCanvas');
    newCanvas.width = cw * dpr;
    newCanvas.height = ch * dpr;
    newCanvas.style.width = cw + 'px';
    newCanvas.style.height = ch + 'px';
    var newCtx = newCanvas.getContext('2d');
    newCtx.scale(dpr, dpr);
    newCtx.drawImage(_ssBaseImage, 0, 0, cw, ch);
  };
  _ssBaseImage.src = tmpCanvas.toDataURL();
}

function _ssExportCanvas(applyAnnotations) {
  var dpr = window.devicePixelRatio || 1;
  var canvas = document.getElementById('ssCanvas');
  if (applyAnnotations) {
    return canvas.toDataURL('image/png');
  }
  var exportCanvas = document.createElement('canvas');
  if (_ssBaseImage) {
    var imgW = _ssBaseImage.naturalWidth || _ssBaseImage.width;
    var imgH = _ssBaseImage.naturalHeight || _ssBaseImage.height;
    exportCanvas.width = imgW;
    exportCanvas.height = imgH;
    var ectx = exportCanvas.getContext('2d');
    ectx.drawImage(_ssBaseImage, 0, 0);
    var scaleX = imgW / canvas.offsetWidth;
    var scaleY = imgH / canvas.offsetHeight;
    for (var i = 0; i < _ssAnnotations.length; i++) {
      var a = Object.assign({}, _ssAnnotations[i]);
      a.x1 = (a.x1 || 0) * scaleX;
      a.y1 = (a.y1 || 0) * scaleY;
      a.x2 = (a.x2 || 0) * scaleX;
      a.y2 = (a.y2 || 0) * scaleY;
      a.width = (a.width || 3) * Math.min(scaleX, scaleY);
      if (a.path) {
        a.path = a.path.map(function(p) { return { x: p.x * scaleX, y: p.y * scaleY }; });
      }
      a.fontSize = (a.fontSize || 16) * Math.min(scaleX, scaleY);
      _ssDrawAnnotation(ectx, a);
    }
  }
  return exportCanvas.toDataURL('image/png');
}

(function setupScreenshotTool() {
  var overlay = document.getElementById('ssOverlay');
  if (!overlay) return;
  var canvasWrap = document.getElementById('ssCanvasWrap');
  var canvas = document.getElementById('ssCanvas');
  var textInput = document.getElementById('ssTextInput');
  var hint = document.getElementById('ssHint');

  document.getElementById('ssCancel').addEventListener('click', closeScreenshotTool);

  document.getElementById('ssSave').addEventListener('click', function() {
    var dataUrl = _ssExportCanvas(true);
    var base64 = dataUrl.replace(/^data:image\/png;base64,/, '');
    if (window.electronAPI && window.electronAPI.saveScreenshot) {
      window.electronAPI.saveScreenshot(base64).then(function(r) {
        if (r && r.success) closeScreenshotTool();
      });
    }
  });

  document.getElementById('ssClipboard').addEventListener('click', function() {
    var dataUrl = _ssExportCanvas(true);
    var base64 = dataUrl.replace(/^data:image\/png;base64,/, '');
    if (window.electronAPI && window.electronAPI.copyScreenshot) {
      window.electronAPI.copyScreenshot(base64).then(function() { closeScreenshotTool(); });
    } else {
      closeScreenshotTool();
    }
  });

  document.querySelectorAll('.ss-tool-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      document.querySelectorAll('.ss-tool-btn').forEach(function(b) { b.classList.remove('active'); });
      btn.classList.add('active');
      _ssTool = btn.dataset.tool;
      canvasWrap.className = 'ss-canvas-wrap drawing';
      if (_ssTool === 'text') canvasWrap.classList.add('ss-tool-text');
      var hints = {
        rect: 'Drag to draw a rectangle',
        arrow: 'Drag to draw an arrow',
        line: 'Drag to draw a line',
        freehand: 'Draw freely',
        text: 'Click to add text',
        blur: 'Brush the area to blur',
        crop: 'Select area to crop'
      };
      hint.textContent = hints[_ssTool] || '';
    });
  });

  document.getElementById('ssColor').addEventListener('input', function(e) {
    _ssColor = e.target.value;
  });

  document.querySelectorAll('.ss-width-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      document.querySelectorAll('.ss-width-btn').forEach(function(b) { b.classList.remove('active'); });
      btn.classList.add('active');
      _ssLineWidth = parseInt(btn.dataset.width) || 3;
    });
  });

  function getCtx() {
    var dpr = window.devicePixelRatio || 1;
    var ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return ctx;
  }

  canvasWrap.addEventListener('mousedown', function(e) {
    if (!_ssActive) return;
    e.preventDefault();
    var c = _ssGetCoords(e);
    if (_ssTool === 'text') {
      textInput.style.display = 'block';
      textInput.style.left = c.x + 'px';
      textInput.style.top = c.y + 'px';
      textInput.value = '';
      textInput.focus();
      textInput._ssX = c.x;
      textInput._ssY = c.y;
      return;
    }
    _ssIsDrawing = true;
    _ssStartX = c.x;
    _ssStartY = c.y;
    _ssCurrentPath = [{ x: c.x, y: c.y }];
  });

  canvasWrap.addEventListener('mousemove', function(e) {
    if (!_ssIsDrawing) return;
    var c = _ssGetCoords(e);
    var ctx = getCtx();
    var w = canvas.offsetWidth;
    var h = canvas.offsetHeight;
    _ssRedraw(ctx, w, h);
    if (_ssTool === 'freehand' || _ssTool === 'blur') {
      _ssCurrentPath.push({ x: c.x, y: c.y });
      _ssDrawAnnotation(ctx, { type: _ssTool, color: _ssColor, width: _ssLineWidth, path: _ssCurrentPath });
    } else {
      _ssDrawAnnotation(ctx, { type: _ssTool, color: _ssColor, width: _ssLineWidth, x1: _ssStartX, y1: _ssStartY, x2: c.x, y2: c.y });
    }
  });

  canvasWrap.addEventListener('mouseup', function(e) {
    if (!_ssIsDrawing) return;
    _ssIsDrawing = false;
    var c = _ssGetCoords(e);
    var ann;
    if (_ssTool === 'freehand' || _ssTool === 'blur') {
      _ssCurrentPath.push({ x: c.x, y: c.y });
      ann = { type: _ssTool, color: _ssColor, width: _ssLineWidth, path: _ssCurrentPath.slice() };
    } else {
      ann = { type: _ssTool, color: _ssColor, width: _ssLineWidth, x1: _ssStartX, y1: _ssStartY, x2: c.x, y2: c.y };
    }
    if (_ssTool === 'crop') {
      _ssCommitCrop(ann);
    } else {
      _ssAnnotations.push(ann);
    }
    _ssCurrentPath = [];
    var ctx = getCtx();
    _ssRedraw(ctx, canvas.offsetWidth, canvas.offsetHeight);
  });

  textInput.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      textInput.style.display = 'none';
      e.stopPropagation();
      return;
    }
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      var txt = textInput.value.trim();
      if (txt) {
        _ssAnnotations.push({ type: 'text', color: _ssColor, x1: textInput._ssX, y1: textInput._ssY, text: txt, fontSize: 16 });
        var ctx = getCtx();
        _ssRedraw(ctx, canvas.offsetWidth, canvas.offsetHeight);
      }
      textInput.style.display = 'none';
      e.stopPropagation();
    }
  });

  textInput.addEventListener('blur', function() {
    var txt = textInput.value.trim();
    if (txt) {
      _ssAnnotations.push({ type: 'text', color: _ssColor, x1: textInput._ssX, y1: textInput._ssY, text: txt, fontSize: 16 });
      var ctx = getCtx();
      _ssRedraw(ctx, canvas.offsetWidth, canvas.offsetHeight);
    }
    textInput.style.display = 'none';
  });

  document.addEventListener('keydown', function(e) {
    if (!_ssActive) return;
    if (e.key === 'Escape') { closeScreenshotTool(); e.stopPropagation(); return; }
    if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
      e.preventDefault();
      if (_ssAnnotations.length > 0) {
        _ssAnnotations.pop();
        var ctx = getCtx();
        _ssRedraw(ctx, canvas.offsetWidth, canvas.offsetHeight);
      }
    }
  });
})();

// ============== OCR TOOL ==============
// Works like the screenshot tool, but instead of an image returns text:
// capture the page → select an area → tesseract (offline after first run)
// → editable result with Copy. rus+eng when the UI is Russian, else eng.
var _ocrActive = false;
var _ocrImage = null;     // HTMLImageElement of the captured page
var _ocrDrag = null;      // {x1,y1,x2,y2} in VIEW coords
function openOcrTool() {
  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (!tab || !tab.webview) return;
  try { if (tab.webview.isDestroyed && tab.webview.isDestroyed()) return; } catch(e) { return; }
  tab.webview.capturePage().then(function(img) {
    if (!img || img.isEmpty()) return;
    _ocrImage = new Image();
    _ocrImage.onload = function() {
      _ocrActive = true;
      var overlay = document.getElementById('ocrOverlay');
      overlay.style.display = 'block';
      document.getElementById('ocrResult').style.display = 'none';
      document.getElementById('ocrHint').style.display = '';
      var dpr = window.devicePixelRatio || 1;
      var w = window.innerWidth, h = window.innerHeight;
      var canvas = document.getElementById('ocrCanvas');
      canvas.width = w * dpr; canvas.height = h * dpr;
      canvas.style.width = w + 'px'; canvas.style.height = h + 'px';
      var ctx = canvas.getContext('2d');
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      // Dim the page: user selects a bright hole in the dark layer.
      ctx.fillStyle = 'rgba(8,8,12,0.55)';
      ctx.fillRect(0, 0, w, h);
      _ocrRedrawSelection(ctx, w, h);
    };
    _ocrImage.src = img.toDataURL();
  }).catch(function() {});
}
function _ocrFit() {
  // Image fitted into the window (same as screenshot tool) → {dx,dy,scale}.
  var w = window.innerWidth, h = window.innerHeight;
  var iw = _ocrImage.naturalWidth || _ocrImage.width;
  var ih = _ocrImage.naturalHeight || _ocrImage.height;
  var scale = Math.min(w / iw, h / ih);
  return { dx: (w - iw * scale) / 2, dy: (h - ih * scale) / 2, scale: scale, iw: iw, ih: ih };
}
function _ocrRedrawSelection(ctx, w, h) {
  if (!_ocrImage) return;
  var f = _ocrFit();
  // Repaint the whole overlay each move — cheap enough for one drag.
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = 'rgba(8,8,12,0.55)';
  ctx.fillRect(0, 0, w, h);
  if (_ocrDrag) {
    var x = Math.min(_ocrDrag.x1, _ocrDrag.x2);
    var y = Math.min(_ocrDrag.y1, _ocrDrag.y2);
    var rw = Math.abs(_ocrDrag.x2 - _ocrDrag.x1);
    var rh = Math.abs(_ocrDrag.y2 - _ocrDrag.y1);
    // "Hole" — draw the corresponding part of the captured image.
    var sx = (x - f.dx) / f.scale, sy = (y - f.dy) / f.scale;
    var sw = rw / f.scale, sh = rh / f.scale;
    try { ctx.drawImage(_ocrImage, sx, sy, sw, sh, x, y, rw, rh); } catch(e) {}
    ctx.strokeStyle = '#1da1f2';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([6, 4]);
    ctx.strokeRect(x + 0.5, y + 0.5, rw, rh);
    ctx.setLineDash([]);
  } else {
    // Draw the fitted image beneath the dim (keeps context readable).
    try { ctx.drawImage(_ocrImage, f.dx, f.dy, f.iw * f.scale, f.ih * f.scale); } catch(e) {}
    ctx.fillStyle = 'rgba(8,8,12,0.55)';
    ctx.fillRect(0, 0, w, h);
  }
}
function _ocrClose() {
  _ocrActive = false;
  _ocrDrag = null;
  var overlay = document.getElementById('ocrOverlay');
  if (overlay) overlay.style.display = 'none';
}
(function setupOcrTool() {
  var overlay = document.getElementById('ocrOverlay');
  if (!overlay) return;
  var canvas = document.getElementById('ocrCanvas');
  var dpr = window.devicePixelRatio || 1;

  function evPos(e) {
    var r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  canvas.addEventListener('mousedown', function(e) {
    if (!_ocrActive || _ocrImage == null) return;
    var p = evPos(e);
    _ocrDrag = { x1: p.x, y1: p.y, x2: p.x, y2: p.y };
  });
  canvas.addEventListener('mousemove', function(e) {
    if (!_ocrActive || !_ocrDrag) return;
    var p = evPos(e);
    _ocrDrag.x2 = p.x; _ocrDrag.y2 = p.y;
    var ctx = canvas.getContext('2d');
    _ocrRedrawSelection(ctx, canvas.offsetWidth, canvas.offsetHeight);
  });
  canvas.addEventListener('mouseup', function(e) {
    if (!_ocrActive || !_ocrDrag) return;
    var p = evPos(e);
    _ocrDrag.x2 = p.x; _ocrDrag.y2 = p.y;
    var x = Math.min(_ocrDrag.x1, _ocrDrag.x2);
    var y = Math.min(_ocrDrag.y1, _ocrDrag.y2);
    var w = Math.abs(_ocrDrag.x2 - _ocrDrag.x1);
    var h = Math.abs(_ocrDrag.y2 - _ocrDrag.y1);
    var drag = _ocrDrag;
    _ocrDrag = null;
    if (w < 8 || h < 8) {
      var ctx = canvas.getContext('2d');
      _ocrRedrawSelection(ctx, canvas.offsetWidth, canvas.offsetHeight);
      return;
    }
    // Crop from the ORIGINAL image (natural resolution) for best OCR quality.
    var f = _ocrFit();
    var sx = (x - f.dx) / f.scale, sy = (y - f.dy) / f.scale;
    var sw = w / f.scale, sh = h / f.scale;
    var c = document.createElement('canvas');
    c.width = Math.max(1, Math.round(sw));
    c.height = Math.max(1, Math.round(sh));
    var cc = c.getContext('2d');
    // White background — JPEG-ish scans OCR better than transparent.
    cc.fillStyle = '#fff';
    cc.fillRect(0, 0, c.width, c.height);
    try { cc.drawImage(_ocrImage, sx, sy, sw, sh, 0, 0, c.width, c.height); } catch(err) { return; }
    var base64 = c.toDataURL('image/png').replace(/^data:image\/png;base64,/, '');
    // Show the result panel in "working" state.
    var res = document.getElementById('ocrResult');
    var ta = document.getElementById('ocrTextarea');
    var status = document.getElementById('ocrStatus');
    ta.value = '';
    status.textContent = 'Recognizing…';
    document.getElementById('ocrHint').style.display = 'none';
    res.style.display = 'flex';
    if (window.electronAPI && window.electronAPI.ocrRecognize) {
      window.electronAPI.ocrRecognize(base64).then(function(r) {
        if (!_ocrActive) return;
        if (r && r.ok) {
          ta.value = r.text || '';
          status.textContent = (r.text ? r.text.length + ' chars' : 'No text found');
        } else {
          status.textContent = 'Error: ' + ((r && r.error) || 'unknown');
        }
      }).catch(function() {
        if (_ocrActive) status.textContent = 'Recognition failed';
      });
    } else {
      status.textContent = 'OCR API unavailable';
    }
  });

  document.getElementById('ocrClose').addEventListener('click', _ocrClose);
  document.getElementById('ocrRetry').addEventListener('click', function() {
    document.getElementById('ocrResult').style.display = 'none';
    document.getElementById('ocrHint').style.display = '';
    var ctx = canvas.getContext('2d');
    _ocrRedrawSelection(ctx, canvas.offsetWidth, canvas.offsetHeight);
  });
  document.getElementById('ocrCopy').addEventListener('click', function() {
    var ta = document.getElementById('ocrTextarea');
    ta.select();
    try { document.execCommand('copy'); } catch(e) {}
    if (navigator.clipboard) navigator.clipboard.writeText(ta.value).catch(function() {});
    var b = this; b.textContent = 'Copied';
    setTimeout(function() { b.textContent = 'Copy text'; }, 1200);
  });
  document.addEventListener('keydown', function(e) {
    if (!_ocrActive) return;
    if (e.key === 'Escape') { _ocrClose(); e.stopPropagation(); }
  });
})();

// ============== TOOLBAR CUSTOMIZATION ==============
var _customizeActive = false;
var _customizeBtnMap = {
  workspace: { el: 'workspaceBtn', name: 'Workspaces', side: 'workspace' },
  library: { el: 'libraryBtn', name: 'Library', side: 'left' },
  home: { el: 'homeBtn', name: 'Home', side: 'left' },
  back: { el: 'backBtn', name: 'Back', side: 'left' },
  forward: { el: 'forwardBtn', name: 'Forward', side: 'left' },
  reload: { el: 'reloadBtn', name: 'Reload', side: 'left' },
  downloads: { el: 'downloadsBtn', name: 'Downloads', side: 'right' },
  autofill: { el: 'autofillBtn', name: 'Passwords', side: 'right' },
  adblock: { el: 'adblockBtn', name: 'Blocker', side: 'right' },
  scripts: { el: 'scriptsBtn', name: 'Scripts', side: 'right' },
  darkMode: { el: 'darkModeBtn', name: 'Dark mode', side: 'right' },
  media: { el: 'mediaBtn', name: 'Media', side: 'right' },
  equalizer: { el: 'eqBtn', name: 'Equalizer', side: 'right' },
  qrScan: { el: 'qrScanBtn', name: 'QR scanner', side: 'right' },
  split: { el: 'splitBtn', name: 'Split screen', side: 'right' },
  newTab: { el: 'newTabBarBtn', name: 'New tab', side: 'right' },
  bookmarks: { el: 'bookmarksBtn', name: 'Bookmarks', side: 'right' },
  history: { el: 'historyBtn', name: 'History', side: 'right' },
  reader: { el: 'readerBtn', name: 'Reader mode', side: 'right' },
  tts: { el: 'ttsBtn', name: 'Read aloud', side: 'right' },
  screenshot: { el: 'screenshotBtn', name: 'Screenshot', side: 'right' },
  incognito: { el: 'incognitoBtn', name: 'Incognito', side: 'right' },
  translate: { el: 'translateBtn', name: 'Translate', side: 'right' },
  findAll: { el: 'findAllBtn', name: 'Search tabs', side: 'right' },
  autoscroll: { el: 'autoscrollBtn', name: 'Autoscroll', side: 'right' },
  breakLoupe: { el: 'breakLoupeBtn', name: 'Break magnifier', side: 'right' },
  settings: { el: 'settingsBtn', name: 'Settings', side: 'right' }
};
var _defaultToolbarButtons = ['library','home','back','forward','reload','downloads','autofill','adblock','scripts'];
var _currentToolbarButtons = null;

function _getToolbarButtons() {
  if (_currentToolbarButtons) return _currentToolbarButtons;
  return _defaultToolbarButtons.slice();
}

function _applyToolbarLayout(buttons) {
  _currentToolbarButtons = buttons ? buttons.slice() : _defaultToolbarButtons.slice();
  // The blocker shield is a PERMANENT toolbar citizen with a FIXED home:
  // the end of the LEFT button group (right after Reload). Normalize every
  // layout — saved configs that already carry it on the right, reset,
  // drag&drop, missing entries — it is always (re)placed there and can be
  // neither moved away nor removed.
  _currentToolbarButtons = _currentToolbarButtons.filter(function(k) { return k !== 'adblock'; });
  var _lastLeftIdx = -1;
  for (var _pi = 0; _pi < _currentToolbarButtons.length; _pi++) {
    var _pk = _currentToolbarButtons[_pi];
    if (_customizeBtnMap[_pk] && _customizeBtnMap[_pk].side === 'left') _lastLeftIdx = _pi;
  }
  if (_lastLeftIdx === -1) _currentToolbarButtons.unshift('adblock');
  else _currentToolbarButtons.splice(_lastLeftIdx + 1, 0, 'adblock');
  var navControls = document.querySelector('.nav-controls');
  var navActions = document.querySelector('.nav-actions.right');
  var tabsBar = document.getElementById('tabsBar');
  var newTabBtn = document.getElementById('newTabBtn');
  if (!navControls || !navActions || !tabsBar || !newTabBtn) return;

  Object.keys(_customizeBtnMap).forEach(function(key) {
    if (key === 'workspace') return;
    var el = document.getElementById(_customizeBtnMap[key].el);
    if (!el) return;
    el.style.display = _currentToolbarButtons.indexOf(key) === -1 ? 'none' : '';
  });
  // Sync hamburger menu visibility with the new toolbar — buttons that are
  // already on the toolbar should disappear from the menu.
  if (window._updateHmVisibility) { try { window._updateHmVisibility(); } catch(e) {} }

  tabsBar.querySelectorAll('.nav-btn:not(.tab-new-btn):not(.tab)').forEach(function(btn) {
    if (btn.id !== 'newTabBtn' && !_customizeBtnMap[_currentToolbarButtons.find(function(k) { return _customizeBtnMap[k] && _customizeBtnMap[k].el === btn.id; })]) {
      btn.remove();
    }
  });

  var leftBtns = _currentToolbarButtons.filter(function(b) { return _customizeBtnMap[b] && _customizeBtnMap[b].side === 'left'; });
  leftBtns.forEach(function(key) {
    var el = document.getElementById(_customizeBtnMap[key].el);
    if (el) navControls.appendChild(el);
  });

  var hamburgerBtn = document.getElementById('hamburgerBtn');
  _currentToolbarButtons.forEach(function(key) {
    if (!_customizeBtnMap[key] || _customizeBtnMap[key].side !== 'right') return;
    var el = document.getElementById(_customizeBtnMap[key].el);
    if (el && hamburgerBtn) navActions.insertBefore(el, hamburgerBtn);
  });

  var hm = document.getElementById('hamburgerMenu');
  if (hm && hamburgerBtn) navActions.appendChild(hamburgerBtn);

  var tabbarBtns = _currentToolbarButtons.filter(function(b) { return _customizeBtnMap[b] && _customizeBtnMap[b].side === 'tabbar'; });
  var tabsBarBtns = document.getElementById('tabsBarBtns');
  if (tabsBarBtns) {
    tabbarBtns.forEach(function(key) {
      var el = document.getElementById(_customizeBtnMap[key].el);
      if (el) tabsBarBtns.appendChild(el);
    });
  }

  var wsZone = document.getElementById('workspaceZone');
  var wsBtn = document.getElementById('workspaceBtn');
  if (wsBtn) {
    var wsInToolbar = _currentToolbarButtons.indexOf('workspace') !== -1;
    wsBtn.style.display = '';
    if (wsInToolbar) {
      var wsSide = _customizeBtnMap.workspace.side;
      if (wsSide === 'left' && navControls) navControls.appendChild(wsBtn);
      else if (wsSide === 'right' && navActions) navActions.appendChild(wsBtn);
      else if (wsSide === 'tabbar' && tabsBarBtns) tabsBarBtns.appendChild(wsBtn);
      else if (wsZone) wsZone.appendChild(wsBtn);
    } else {
      if (wsZone) wsZone.appendChild(wsBtn);
    }
  }
  if (wsZone) {
    var wsSideBtns = _currentToolbarButtons.filter(function(b) {
      return b !== 'workspace' && _customizeBtnMap[b] && _customizeBtnMap[b].side === 'workspace';
    });
    wsSideBtns.forEach(function(key) {
      var el = document.getElementById(_customizeBtnMap[key].el);
      if (el) wsZone.appendChild(el);
    });
  }
}

function _saveToolbarConfig() {
  if (!_currentToolbarButtons) return;
  var data = _currentToolbarButtons.map(function(key) {
    return { key: key, side: _customizeBtnMap[key] ? _customizeBtnMap[key].side : 'right' };
  });
  try { localStorage.setItem('startpozi-toolbar-buttons', JSON.stringify(data)); } catch(e) {}
  if (window.electronAPI && window.electronAPI.saveToolbarButtons) {
    window.electronAPI.saveToolbarButtons(data);
  }
}

function _loadToolbarConfig() {
  var saved = null;
  try {
    var raw = localStorage.getItem('startpozi-toolbar-buttons');
    if (raw) {
      var parsed = JSON.parse(raw);
      if (parsed.length && typeof parsed[0] === 'object') {
        parsed.forEach(function(item) {
          if (_customizeBtnMap[item.key] && item.side) _customizeBtnMap[item.key].side = item.side;
        });
        saved = parsed.map(function(item) { return item.key; });
      } else if (parsed.length && typeof parsed[0] === 'string') {
        saved = parsed;
      }
    }
  } catch(e) {}
  if (saved) { _applyToolbarLayout(saved); return; }
  if (window.electronAPI && window.electronAPI.getToolbarButtons) {
    window.electronAPI.getToolbarButtons().then(function(r) {
      if (r && r.success && r.buttons && r.buttons.length) {
        var ipcButtons = r.buttons;
        if (ipcButtons.length && typeof ipcButtons[0] === 'object') {
          ipcButtons.forEach(function(item) {
            if (_customizeBtnMap[item.key] && item.side) _customizeBtnMap[item.key].side = item.side;
          });
          _applyToolbarLayout(ipcButtons.map(function(item) { return item.key; }));
        } else {
          _applyToolbarLayout(ipcButtons);
        }
      }
    }).catch(function() {});
  }
}

(function initToolbarLayout() {
  _loadToolbarConfig();
  if (window.electronAPI && window.electronAPI.onToolbarButtonsChanged) {
    window.electronAPI.onToolbarButtonsChanged(function(b) {
      if (b && b.length && typeof b[0] === 'object') {
        b.forEach(function(item) {
          if (_customizeBtnMap[item.key] && item.side) _customizeBtnMap[item.key].side = item.side;
        });
        _applyToolbarLayout(b.map(function(item) { return item.key; }));
      } else {
        _applyToolbarLayout(b);
      }
    });
  }
})();

// One-time wiring guard: the drop-zone and mousedown listeners below all
// no-op while !_customizeActive, so they only ever need to be attached ONCE.
// Previously every open of customize mode stacked another copy of each
// anonymous listener (closeCustomizeMode never removed them).
var _customizeZonesWired = false;

function toggleCustomizeMode() {
  if (_customizeActive) { closeCustomizeMode(); return; }
  _customizeActive = true;
  var overlay = document.getElementById('customizeOverlay');
  var navbar = document.querySelector('.navbar');
  var pool = document.getElementById('customizePool');
  if (!overlay || !navbar || !pool) return;

  overlay.style.display = '';
  navbar.classList.add('customize-active');
  var _tsb = document.getElementById('tabsBarBtns');
  if (_tsb) _tsb.classList.add('customize-active');
  var _wsZone = document.getElementById('workspaceZone');
  if (_wsZone) _wsZone.classList.add('customize-active');
  var titlebar = document.querySelector('.titlebar');
  if (titlebar) titlebar.style.webkitAppRegion = 'no-drag';

  navbar._custClickBlock = function(e) {
    if (_customizeActive && e.target.closest('.nav-btn')) {
      e.stopImmediatePropagation();
      e.preventDefault();
    }
  };
  navbar.addEventListener('click', navbar._custClickBlock, true);

  var tabsBarEl = document.getElementById('tabsBar');
  if (tabsBarEl) {
    tabsBarEl._custClickBlock = function(e) {
      if (_customizeActive && e.target.closest('#tabsBarBtns .nav-btn')) {
        e.stopImmediatePropagation();
        e.preventDefault();
      }
    };
    tabsBarEl.addEventListener('click', tabsBarEl._custClickBlock, true);
  }
  if (!_customizeZonesWired) {
    navbar.addEventListener('mousedown', function(e) {
      if (_customizeActive && e.target.closest('.nav-btn')) {
        e.target.closest('.nav-btn').draggable = true;
      }
    }, true);
    var _tsbDrag = document.getElementById('tabsBarBtns');
    if (_tsbDrag) {
      _tsbDrag.addEventListener('mousedown', function(e) {
        if (_customizeActive && e.target.closest('.nav-btn')) {
          e.target.closest('.nav-btn').draggable = true;
        }
      }, true);
    }
    if (_wsZone) {
      _wsZone.addEventListener('mousedown', function(e) {
        if (_customizeActive && (e.target.closest('.nav-btn') || e.target.closest('.workspace-btn'))) {
          var target = e.target.closest('.nav-btn') || e.target.closest('.workspace-btn');
          target.draggable = true;
        }
      }, true);
    }
  }
  if (_wsZone) {
    _wsZone._custClickBlock = function(e) {
      if (_customizeActive && (e.target.closest('.nav-btn') || e.target.closest('.workspace-btn'))) {
        e.stopImmediatePropagation();
        e.preventDefault();
      }
    };
    _wsZone.addEventListener('click', _wsZone._custClickBlock, true);
  }

  var activeButtons = _getToolbarButtons();
  Object.keys(_customizeBtnMap).forEach(function(key) {
    var el = document.getElementById(_customizeBtnMap[key].el);
    if (!el) return;
    if (key === 'workspace') {
      el.style.display = '';
    } else {
      el.style.display = activeButtons.indexOf(key) !== -1 ? '' : 'none';
    }
    _setupNavbarDrag(el, key);
  });

  pool.innerHTML = '';
  var hint = document.createElement('div');
  hint.className = 'customize-pool-hint';
  hint.textContent = 'Drag buttons onto the toolbar above, or double-click to add';
  pool.appendChild(hint);

  Object.keys(_customizeBtnMap).forEach(function(key) {
    if (activeButtons.indexOf(key) !== -1) return;
    _addPoolItem(key);
  });

  _setupDropZones();
  document.getElementById('customizeDone').onclick = closeCustomizeMode;
  document.getElementById('customizeReset').onclick = function() {
    _applyToolbarLayout(_defaultToolbarButtons.slice());
    _saveToolbarConfig();
    _refreshCustomizeUI();
  };
}

function _addPoolItem(key) {
  if (key === 'workspace') return;
  var pool = document.getElementById('customizePool');
  if (!pool) return;
  var cfg = _customizeBtnMap[key];
  var btn = document.getElementById(cfg.el);
  if (!btn) return;
  var item = document.createElement('div');
  item.className = 'customize-pool-item';
  item.dataset.btnKey = key;
  item.innerHTML = btn.innerHTML + '<span>' + escapeHtmlSimple(cfg.name) + '</span>';
  item.draggable = true;
  item.addEventListener('dragstart', function(e) {
    e.dataTransfer.setData('text/plain', key);
    e.dataTransfer.effectAllowed = 'move';
    item.classList.add('dragging');
  });
  item.addEventListener('dragend', function() {
    item.classList.remove('dragging');
    document.querySelectorAll('.drag-zone-active').forEach(function(z) { z.classList.remove('drag-zone-active'); });
  });
  item.addEventListener('dblclick', function() {
    var buttons = _getToolbarButtons();
    if (buttons.indexOf(key) === -1) { buttons.push(key); }
    _applyToolbarLayout(buttons);
    _saveToolbarConfig();
    _refreshCustomizeUI();
  });
  pool.appendChild(item);
}

function _refreshCustomizeUI() {
  if (!_customizeActive) return;
  var pool = document.getElementById('customizePool');
  if (!pool) return;
  pool.querySelectorAll('.customize-pool-item').forEach(function(el) { el.remove(); });
  pool.querySelectorAll('.customize-add-btn').forEach(function(el) { el.remove(); });
  var activeButtons = _getToolbarButtons();
  Object.keys(_customizeBtnMap).forEach(function(key) {
    if (activeButtons.indexOf(key) !== -1) return;
    _addPoolItem(key);
  });
  var hint = pool.querySelector('.customize-pool-hint');
  if (hint) hint.style.display = pool.querySelectorAll('.customize-pool-item').length ? 'none' : '';
  // Keep hamburger menu in sync — a button added/removed in Customize
  // Toolbar must immediately appear/disappear in the menu.
  if (window._updateHmVisibility) { try { window._updateHmVisibility(); } catch(e) {} }

  var addBtn = document.createElement('div');
  addBtn.className = 'customize-pool-item customize-add-btn';
  addBtn.style.background = 'rgba(102,126,234,0.15)';
  addBtn.style.border = '1px dashed rgba(102,126,234,0.4)';
  addBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg><span>Custom button</span>';
  addBtn.addEventListener('click', function() { _addCustomToolbarButton(); });
  pool.appendChild(addBtn);
}

function _setupNavbarDrag(btn, key) {
  btn._custDragStart = function(e) {
    if (!_customizeActive) return;
    e.dataTransfer.setData('text/plain', key);
    e.dataTransfer.effectAllowed = 'move';
    btn.classList.add('dragging');
  };
  btn._custDragEnd = function() {
    btn.classList.remove('dragging');
    document.querySelectorAll('.drag-over,.drag-zone-active').forEach(function(z) { z.classList.remove('drag-over','drag-zone-active'); });
  };
  btn._custDblClick = function() {
    if (!_customizeActive) return;
    if (key === 'workspace') {
      _customizeBtnMap[key].side = 'workspace';
      var buttons = _getToolbarButtons();
      _applyToolbarLayout(buttons);
      _saveToolbarConfig();
      _refreshCustomizeUI();
      return;
    }
    if (_customizeBtnMap[key]) _customizeBtnMap[key].side = 'right';
    var buttons = _getToolbarButtons();
    buttons = buttons.filter(function(b) { return b !== key; });
    _applyToolbarLayout(buttons);
    _saveToolbarConfig();
    _refreshCustomizeUI();
    Object.keys(_customizeBtnMap).forEach(function(k) {
      var el2 = document.getElementById(_customizeBtnMap[k].el);
      if (el2 && buttons.indexOf(k) === -1) el2.style.display = 'none';
    });
  };
  btn.addEventListener('dragstart', btn._custDragStart);
  btn.addEventListener('dragend', btn._custDragEnd);
  btn.addEventListener('dblclick', btn._custDblClick);
}

function _setupDropZones() {
  // Wire once per page lifetime — the handlers check _customizeActive, so
  // re-entry on every "Customize" open only piled up duplicates.
  if (_customizeZonesWired) return;
  _customizeZonesWired = true;
  var navControls = document.querySelector('.nav-controls');
  var navActions = document.querySelector('.nav-actions.right');
  var pool = document.getElementById('customizePool');

  [navControls, navActions].forEach(function(zone) {
    if (!zone) return;
    zone.addEventListener('dragover', function(e) {
      if (!_customizeActive) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      zone.classList.add('drag-zone-active');
    });
    zone.addEventListener('dragleave', function(e) {
      if (!zone.contains(e.relatedTarget)) zone.classList.remove('drag-zone-active');
    });
    zone.addEventListener('drop', function(e) {
      e.preventDefault();
      zone.classList.remove('drag-zone-active');
      if (!_customizeActive) return;
      var key = e.dataTransfer.getData('text/plain');
      if (!key || !_customizeBtnMap[key]) return;
      var isLeft = zone === navControls;
      _customizeBtnMap[key].side = isLeft ? 'left' : 'right';
      var buttons = _getToolbarButtons();
      if (buttons.indexOf(key) !== -1) {
        var target = e.target.closest('.nav-btn');
        if (target) {
          var targetKey = null;
          Object.keys(_customizeBtnMap).forEach(function(k) {
            if (_customizeBtnMap[k].el === target.id) targetKey = k;
          });
          if (targetKey && targetKey !== key) {
            buttons = buttons.filter(function(b) { return b !== key; });
            var idx = buttons.indexOf(targetKey);
            if (idx !== -1) buttons.splice(idx, 0, key);
            else buttons.push(key);
          }
        }
      } else {
        buttons.push(key);
      }
      _applyToolbarLayout(buttons);
      _saveToolbarConfig();
      _refreshCustomizeUI();
    });
  });

  if (pool) {
    pool.addEventListener('dragover', function(e) {
      if (!_customizeActive) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      pool.style.background = 'rgba(102,126,234,0.1)';
    });
    pool.addEventListener('dragleave', function(e) {
      if (!pool.contains(e.relatedTarget)) pool.style.background = '';
    });
    pool.addEventListener('drop', function(e) {
      e.preventDefault();
      pool.style.background = '';
      if (!_customizeActive) return;
      var key = e.dataTransfer.getData('text/plain');
      if (!key || !_customizeBtnMap[key] || key === 'workspace') return;
      var buttons = _getToolbarButtons();
      if (buttons.indexOf(key) !== -1) {
        if (_customizeBtnMap[key]) _customizeBtnMap[key].side = 'right';
        buttons = buttons.filter(function(b) { return b !== key; });
        _applyToolbarLayout(buttons);
        _saveToolbarConfig();
        _refreshCustomizeUI();
      }
    });
  }

  var _tabBarEl = document.getElementById('tabsBar');
  var _tabBarBtnsEl = document.getElementById('tabsBarBtns');
  var _navControlsEl = document.querySelector('.nav-controls');
  var _navActionsEl = document.querySelector('.nav-actions.right');
  if (_tabBarEl && _tabBarBtnsEl) {
    document.addEventListener('dragover', function(e) {
      if (!_customizeActive) return;
      if (_tabBarEl.contains(e.target) && !(_navControlsEl && _navControlsEl.contains(e.target)) && !(_navActionsEl && _navActionsEl.contains(e.target)) && !(pool && pool.contains(e.target))) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        _tabBarBtnsEl.style.outline = '2px dashed #667eea';
        _tabBarBtnsEl.style.outlineOffset = '2px';
      }
    }, true);
    document.addEventListener('drop', function(e) {
      if (!_customizeActive) return;
      _tabBarBtnsEl.style.outline = '';
      _tabBarBtnsEl.style.outlineOffset = '';
      if (!_tabBarEl.contains(e.target)) return;
      if (_navControlsEl && _navControlsEl.contains(e.target)) return;
      if (_navActionsEl && _navActionsEl.contains(e.target)) return;
      if (pool && pool.contains(e.target)) return;
      var key = e.dataTransfer.getData('text/plain');
      if (!key || !_customizeBtnMap[key]) return;
      e.preventDefault();
      e.stopPropagation();
      _customizeBtnMap[key].side = 'tabbar';
      var buttons = _getToolbarButtons();
      if (buttons.indexOf(key) === -1) buttons.push(key);
      _applyToolbarLayout(buttons);
      _saveToolbarConfig();
      _refreshCustomizeUI();
    }, true);
    document.addEventListener('dragend', function() {
      _tabBarBtnsEl.style.outline = '';
      _tabBarBtnsEl.style.outlineOffset = '';
    }, true);
  }

  var wsZone = document.getElementById('workspaceZone');
  if (wsZone) {
    wsZone.addEventListener('dragover', function(e) {
      if (!_customizeActive) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      wsZone.classList.add('drag-zone-active');
    });
    wsZone.addEventListener('dragleave', function(e) {
      if (!wsZone.contains(e.relatedTarget)) wsZone.classList.remove('drag-zone-active');
    });
    wsZone.addEventListener('drop', function(e) {
      e.preventDefault();
      wsZone.classList.remove('drag-zone-active');
      if (!_customizeActive) return;
      var key = e.dataTransfer.getData('text/plain');
      if (!key || !_customizeBtnMap[key]) return;
      _customizeBtnMap[key].side = 'workspace';
      var buttons = _getToolbarButtons();
      if (buttons.indexOf(key) === -1) buttons.push(key);
      _applyToolbarLayout(buttons);
      _saveToolbarConfig();
      _refreshCustomizeUI();
    });
  }
}

function closeCustomizeMode() {
  _customizeActive = false;
  var overlay = document.getElementById('customizeOverlay');
  var navbar = document.querySelector('.navbar');
  if (overlay) overlay.style.display = 'none';
  if (navbar) {
    navbar.classList.remove('customize-active');
    if (navbar._custClickBlock) navbar.removeEventListener('click', navbar._custClickBlock, true);
  }
  var tabsBarEl = document.getElementById('tabsBar');
  if (tabsBarEl && tabsBarEl._custClickBlock) tabsBarEl.removeEventListener('click', tabsBarEl._custClickBlock, true);
  var _tsb2 = document.getElementById('tabsBarBtns');
  if (_tsb2) _tsb2.classList.remove('customize-active');
  var _wsZone2 = document.getElementById('workspaceZone');
  if (_wsZone2) {
    _wsZone2.classList.remove('customize-active');
    if (_wsZone2._custClickBlock) _wsZone2.removeEventListener('click', _wsZone2._custClickBlock, true);
  }
  var titlebar = document.querySelector('.titlebar');
  if (titlebar) titlebar.style.webkitAppRegion = 'drag';

  Object.keys(_customizeBtnMap).forEach(function(key) {
    var el = document.getElementById(_customizeBtnMap[key].el);
    if (!el) return;
    if (el._custDragStart) el.removeEventListener('dragstart', el._custDragStart);
    if (el._custDragEnd) el.removeEventListener('dragend', el._custDragEnd);
    if (el._custDblClick) el.removeEventListener('dblclick', el._custDblClick);
  });

  var buttons = _getToolbarButtons();
  Object.keys(_customizeBtnMap).forEach(function(key) {
    var el = document.getElementById(_customizeBtnMap[key].el);
    if (!el) return;
    if (key === 'workspace') {
      el.style.display = '';
    } else {
      el.style.display = buttons.indexOf(key) === -1 ? 'none' : '';
    }
  });
}

var _customToolbarBtns = [];
try { var _ctb = localStorage.getItem('startpozi-custom-toolbar-btns'); if (_ctb) _customToolbarBtns = JSON.parse(_ctb); } catch(e) {}
function _saveCustomBtns() { try { localStorage.setItem('startpozi-custom-toolbar-btns', JSON.stringify(_customToolbarBtns)); } catch(e) {} }

function _createCustomButtonElement(cbtn) {
  var btn = document.createElement('button');
  btn.className = 'nav-btn';
  btn.id = cbtn.id;
  btn.title = cbtn.name;
  btn.style.display = 'none';
  btn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="8" y1="12" x2="16" y2="12"/></svg>';
  btn.addEventListener('click', function() {
    if (cbtn.type === 'url') {
      createNewTab(cbtn.value);
    } else if (cbtn.type === 'js') {
      var t = tabs.find(function(tt) { return tt.id === activeTabId; });
      if (t && t.webview && t.isReady && canExecInWebview(t.webview)) {
        t.webview.executeJavaScript(cbtn.value).catch(function() {});
      }
    }
  });
  return btn;
}

function _initCustomButtons() {
  var container = document.getElementById('customToolbarButtons');
  if (!container) return;
  container.innerHTML = '';
  _customToolbarBtns.forEach(function(cbtn) {
    var btn = _createCustomButtonElement(cbtn);
    container.appendChild(btn);
    _customizeBtnMap[cbtn.id] = { el: cbtn.id, name: cbtn.name, side: cbtn.side || 'right', custom: true };
  });
}
_initCustomButtons();

function _addCustomToolbarButton() {
  customPrompt('Button name:').then(function(name) {
    if (!name) return;
    customConfirm('Type: URL or JavaScript?\n\nOK = URL\nCancel = JavaScript').then(function(isUrl) {
      var type = isUrl ? 'url' : 'js';
      var hint = isUrl ? 'URL (e.g. https://...)' : 'JavaScript code';
      customPrompt(hint + ':').then(function(value) {
        if (!value) return;
        var id = 'customBtn-' + Date.now();
        var side = 'right';
        _customToolbarBtns.push({ id: id, name: name, type: type, value: value, side: side });
        _saveCustomBtns();
        _initCustomButtons();
        if (_customizeActive) _refreshCustomizeUI();
      });
    });
  });
}

// ============== BREAK LOUPE ==============
// Removes all cookies of external sites, but keeps cookies of internal pages (file://).
// Animation: a large magnifier appears in the center, a crack runs across it,
// the lens shatters into pieces (instead of DuckDuckGo fire).
function _playBreakLoupeAnimation() {
  if (document.getElementById('breakLoupeOverlay')) return;

  var overlay = document.createElement('div');
  overlay.id = 'breakLoupeOverlay';
  overlay.className = 'break-loupe-overlay';

  // Magnifier container (scales/shakes)
  var scope = document.createElement('div');
  scope.className = 'bl-scope';

  // SVG magnifier: round lens + handle
  scope.innerHTML =
    '<svg class="bl-svg" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">' +
      '<defs>' +
        '<radialGradient id="blGlass" cx="38%" cy="32%" r="70%">' +
          '<stop offset="0%" stop-color="rgba(255,255,255,0.55)"/>' +
          '<stop offset="55%" stop-color="rgba(180,210,255,0.18)"/>' +
          '<stop offset="100%" stop-color="rgba(120,160,220,0.05)"/>' +
        '</radialGradient>' +
      '</defs>' +
      // Lens (glass)
      '<circle class="bl-glass" cx="78" cy="78" r="56" fill="url(#blGlass)" stroke="#cfe2ff" stroke-width="5"/>' +
      // Glare
      '<ellipse class="bl-glare" cx="58" cy="56" rx="14" ry="8" fill="rgba(255,255,255,0.7)"/>' +
      // Rim
      '<circle class="bl-rim" cx="78" cy="78" r="56" fill="none" stroke="#9bb4d6" stroke-width="3"/>' +
      // Handle
      '<line class="bl-handle" x1="120" y1="120" x2="170" y2="170" stroke="#8aa0c0" stroke-width="11" stroke-linecap="round"/>' +
      '<line class="bl-handle-i" x1="124" y1="124" x2="166" y2="166" stroke="#aebfd8" stroke-width="4" stroke-linecap="round"/>' +
      // Crack (progressively appearing segments)
      '<g class="bl-crack" stroke="rgba(20,20,30,0.85)" stroke-width="2.2" fill="none" stroke-linecap="round">' +
        '<polyline class="bl-c1" points="40,70 60,82 50,98 72,104 65,118 86,122"/>' +
        '<polyline class="bl-c2" points="60,82 80,76 92,90 110,80"/>' +
        '<polyline class="bl-c3" points="50,98 36,108 30,126"/>' +
        '<polyline class="bl-c4" points="72,104 88,116 102,110 118,124"/>' +
        '<polyline class="bl-c5" points="92,90 100,108 96,128"/>' +
      '</g>' +
    '</svg>';

  overlay.appendChild(scope);

  // Shards — fly apart after impact
  var shardsWrap = document.createElement('div');
  shardsWrap.className = 'bl-shards';
  var shardCount = 14;
  for (var i = 0; i < shardCount; i++) {
    var sh = document.createElement('div');
    sh.className = 'bl-shard';
    // Random flight directions (stored as CSS variables)
    var angle = (Math.PI * 2 * i) / shardCount + (Math.random() - 0.5) * 0.6;
    var dist = 120 + Math.random() * 180;
    sh.style.setProperty('--dx', Math.cos(angle) * dist + 'px');
    sh.style.setProperty('--dy', Math.sin(angle) * dist + 'px');
    sh.style.setProperty('--rot', (Math.random() * 720 - 360) + 'deg');
    sh.style.setProperty('--sz', (10 + Math.random() * 16) + 'px');
    sh.style.setProperty('--delay', (Math.random() * 0.08) + 's');
    shardsWrap.appendChild(sh);
  }
  overlay.appendChild(shardsWrap);

  // Flash beam on impact
  var flash = document.createElement('div');
  flash.className = 'bl-flash';
  overlay.appendChild(flash);

  document.body.appendChild(overlay);
  void overlay.offsetWidth;
  overlay.classList.add('bl-running');

  // Remove the overlay after the animation ends
  setTimeout(function() {
    overlay.classList.add('bl-fading');
    setTimeout(function() {
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    }, 450);
  }, 1450);
}

(function() {
  var btn = document.getElementById('breakLoupeBtn');
  if (!btn) return;
  var _blT = function(s) { return (window.i18n && window.i18n.t(s)) || s; };
  btn.addEventListener('click', function() {
    customConfirm(_blT('🔍 Break the magnifier?\n\nThis will delete ALL cookies of external sites (tabs and history are kept). You will be signed out of all websites. Cookies of the browser\'s internal pages (file://) are preserved.')).then(function(ok) {
      if (!ok) return;
      _playBreakLoupeAnimation();
      if (window.electronAPI && window.electronAPI.breakLoupe) {
        window.electronAPI.breakLoupe().then(function(r) {
          var msg;
          var sev;
          if (r && r.success) {
            msg = _blT('🔍 Magnifier broken! Cookies removed:') + ' ' + (r.removed || 0) +
                  (r.kept ? ' ' + _blT('(kept for browser pages:') + ' ' + r.kept + ')' : '');
            sev = 'info';
          } else {
            msg = _blT('Error:') + ' ' + (r && r.message || _blT('unknown'));
            sev = 'danger';
          }
          if (typeof _showToast === 'function') {
            _showToast(msg, 'break-loupe', null, sev);
          } else {
            customAlert(msg);
          }
        }).catch(function(e) {
          customAlert(_blT('Error:') + ' ' + (e && e.message || e));
        });
      } else {
        customAlert(_blT('Unavailable'));
      }
    });
  });
})();

// ============== UNIVERSAL POPUP MANAGER ==============
// Every toolbar dropdown (downloads, adblock, autofill, scripts, media, eq,
// hover-translate, site-info) is anchored to the button that opened it and
// closes on any outside click. The previous per-panel CSS used a hard-coded
// "right:16px" which put every dropdown in the top-right corner regardless
// of which button was clicked.
//
// Mapping: panelId  →  buttonId that toggles it.
var _POPUP_BTN_MAP = {
  downloadPanel:  'downloadsBtn',
  autofillPanel:  'autofillBtn',
  adblockPanel:   'adblockBtn',
  darkReaderPanel: 'darkModeBtn',
  scriptsPanel:   'scriptsBtn',
  mediaPanel:     'mediaBtn',
  eqPanel:        'eqBtn',
  htPanel:        'translateBtn',
  siteInfoPanel:  'urlIconBtn',
  hamburgerMenu:  'hamburgerBtn'
};

// Position a panel directly beneath its triggering button, centered on it,
// clamped to the viewport so it never goes off-screen.
function _positionPanelUnderBtn(panel, btn, panelId) {
  if (!panel || !btn) return;
  // fixed positioning = viewport coordinates, so the panel lands exactly
  // where getBoundingClientRect() of the button says, regardless of scroll
  // or transformed ancestors. Override the hard-coded "right/top" CSS too.
  panel.style.position = 'fixed';
  panel.style.right = 'auto';
  panel.style.bottom = 'auto';
  // Clear transform so our left/top math is not visually shifted.
  panel.style.transform = 'none';
  // Measure the panel without flashing it in the wrong spot.
  var wasHidden = !panel.classList.contains('open');
  if (wasHidden) {
    panel.style.visibility = 'hidden';
    panel.style.display = 'flex';
  }
  var btnRect = btn.getBoundingClientRect();
  var pRect = panel.getBoundingClientRect();
  if (wasHidden) {
    panel.style.display = '';
    panel.style.visibility = '';
  }
  var left = btnRect.left + btnRect.width / 2 - pRect.width / 2;
  var top = btnRect.bottom + 6;
  var margin = 8;
  if (left < margin) left = margin;
  if (left + pRect.width > window.innerWidth - margin) left = window.innerWidth - margin - pRect.width;
  // If the panel would not fit below the button, flip it above.
  if (top + pRect.height > window.innerHeight - margin) {
    var aboveTop = btnRect.top - pRect.height - 6;
    if (aboveTop > margin) top = aboveTop;
  }
  panel.style.left = left + 'px';
  panel.style.top = top + 'px';
}

// Re-position open panels on viewport changes (resize, scroll, zoom).
window.addEventListener('resize', function() {
  Object.keys(_POPUP_BTN_MAP).forEach(function(panelId) {
    var p = document.getElementById(panelId);
    if (p && p.classList.contains('open')) {
      _positionPanelUnderBtn(p, document.getElementById(_POPUP_BTN_MAP[panelId]), panelId);
    }
  });
});

// Watch each panel for the .open class and position it underneath its button.
// We observe attributes (not children) so this works regardless of which
// existing handler toggled the class.
Object.keys(_POPUP_BTN_MAP).forEach(function(panelId) {
  var panel = document.getElementById(panelId);
  if (!panel) return;
  var btn = document.getElementById(_POPUP_BTN_MAP[panelId]);
  if (!btn) return;
  // Capture phase runs BEFORE the panel's own click handler, so we can:
  //   1. close every OTHER open popup (mutual exclusion — only one popup
  //      can be on screen at a time, otherwise they stack on top of each
  //      other in confusing ways)
  //   2. let the panel's handler toggle this one
  //   3. position this one underneath its button on the next frame
  btn.addEventListener('click', function() {
    Object.keys(_POPUP_BTN_MAP).forEach(function(otherId) {
      if (otherId === panelId) return;
      var other = document.getElementById(otherId);
      if (other && other.classList.contains('open')) other.classList.remove('open');
    });
    requestAnimationFrame(function() {
      if (panel.classList.contains('open')) _positionPanelUnderBtn(panel, btn, panelId);
    });
  }, true /* capture */);
});

// Universal "click outside closes everything" — replaces the per-panel
// outside-click handlers that compared e.target !== btn (which fails when
// the click lands on the SVG inside the button).
document.addEventListener('click', function(e) {
  Object.keys(_POPUP_BTN_MAP).forEach(function(panelId) {
    var panel = document.getElementById(panelId);
    if (!panel || !panel.classList.contains('open')) return;
    var btn = document.getElementById(_POPUP_BTN_MAP[panelId]);
    if (btn && btn.contains(e.target)) return; // the button's own handler toggles
    if (panel.contains(e.target)) return;       // inside the panel
    panel.classList.remove('open');
  });
});

// Escape closes every popup — common UX shortcut.
document.addEventListener('keydown', function(e) {
  if (e.key !== 'Escape') return;
  Object.keys(_POPUP_BTN_MAP).forEach(function(panelId) {
    var panel = document.getElementById(panelId);
    if (panel && panel.classList.contains('open')) panel.classList.remove('open');
  });
});

// ============== TOOLBAR BUTTON RIGHT-CLICK → "Customize toolbar" ==============
// ============== CHROME CONTEXT MENUS ==============
// Chrome-style right-click menus for the browser UI:
//   • Reload button  → normal reload / hard reload / empty cache + hard reload
//   • Back / Forward → the tab's navigation history + "Show all history"
//   • Toolbar shortcut buttons (Downloads, Passwords, …) → Unpin + Customize
//   • URL bar → Cut / Copy / Paste / Paste and search / Delete / Select all
//   • Plain chrome areas (empty panel space) → NO menu at all
// Websites keep their own page context menu (handled elsewhere).
(function installChromeContextMenus() {
  // One DOM popup, rebuilt per invocation.
  var menu = document.createElement('div');
  menu.className = 'tb-context-menu';
  menu.style.cssText = [
    'position:fixed','display:none','z-index:100001',
    'min-width:220px','max-width:340px','max-height:60vh','overflow-y:auto',
    'padding:6px 0',
    'background:var(--panel-bg,#2d2d2d)',
    'color:var(--text-primary,#fff)',
    'border:1px solid var(--border-color,#3d3d3d)',
    'border-radius:8px',
    'box-shadow:0 8px 24px rgba(0,0,0,0.4)',
    'font-family:inherit','font-size:13px','user-select:none'
  ].join(';');
  document.body.appendChild(menu);

  function close() { menu.style.display = 'none'; }
  document.addEventListener('click', function(e) {
    if (menu.style.display !== 'none' && !menu.contains(e.target)) close();
  });
  document.addEventListener('keydown', function(e) { if (e.key === 'Escape') close(); });
  window.addEventListener('blur', close);
  window.addEventListener('resize', close);

  function begin() { menu.innerHTML = ''; }
  function add(label, hint, fn, opts) {
    opts = opts || {};
    var it = document.createElement('div');
    it.style.cssText = 'padding:8px 14px;cursor:' + (opts.disabled ? 'default' : 'pointer') +
      ';display:flex;align-items:center;gap:10px;white-space:nowrap;overflow:hidden;' +
      (opts.disabled ? 'opacity:0.45;' : '');
    // Optional leading icon (favicon in the Back/Forward history menu).
    // onerror removes the broken image — the entry degrades to plain text.
    if (opts.icon) {
      var ic = document.createElement('img');
      ic.src = opts.icon;
      ic.style.cssText = 'width:16px;height:16px;flex:none;border-radius:3px;object-fit:contain;';
      ic.onerror = function() { ic.remove(); };
      it.appendChild(ic);
    }
    var span = document.createElement('span');
    span.textContent = label;
    span.style.cssText = 'flex:1;overflow:hidden;text-overflow:ellipsis;';
    it.appendChild(span);
    if (hint) {
      var h = document.createElement('span');
      h.textContent = hint;
      h.style.cssText = 'color:var(--text-secondary,#999);font-size:11px;flex:none;';
      it.appendChild(h);
    }
    if (!opts.disabled) {
      it.addEventListener('mouseenter', function() { it.style.background = 'var(--bg-hover, rgba(255,255,255,0.08))'; });
      it.addEventListener('mouseleave', function() { it.style.background = 'transparent'; });
      it.addEventListener('click', function(e0) {
        e0.stopPropagation();
        close();
        try { fn && fn(); } catch (e1) {}
      });
    }
    menu.appendChild(it);
    return it;
  }
  function sep() {
    var s = document.createElement('div');
    s.style.cssText = 'height:1px;margin:5px 10px;background:var(--border-color,#3d3d3d);';
    menu.appendChild(s);
  }
  function show(x, y) {
    menu.style.display = 'block';
    var w = menu.offsetWidth || 240, h = menu.offsetHeight || 60;
    menu.style.left = Math.max(4, Math.min(x, window.innerWidth - w - 6)) + 'px';
    menu.style.top = Math.max(4, Math.min(y, window.innerHeight - h - 6)) + 'px';
  }

  function activeWv() {
    var t = getActiveTab();
    return (t && t.isReady) ? t.webview : null;
  }

  // --- Window menu (right-click on the title bar) ---
  // Frameless windows have no system chrome, so the OS title-bar menu does
  // not exist — right-click on .titlebar used to do nothing at all. This is
  // the native-style replacement: Minimize / Maximize-Restore / Close.
  function windowMenu(e) {
    begin();
    var gs = (window.electronAPI && window.electronAPI.getWindowState)
      ? window.electronAPI.getWindowState() : Promise.resolve({});
    gs.then(function(state) {
      state = state || {};
      add('Minimize', null, function() { try { window.electronAPI.windowMinimize(); } catch (_) {} });
      add(state.maximized ? 'Restore' : 'Maximize', null, function() { try { window.electronAPI.windowMaximize(); } catch (_) {} });
      sep();
      add('Close window', null, function() { try { window.electronAPI.windowClose(); } catch (_) {} });
      show(e.clientX, e.clientY);
    }).catch(function() {
      add('Minimize', null, function() { try { window.electronAPI.windowMinimize(); } catch (_) {} });
      add('Maximize', null, function() { try { window.electronAPI.windowMaximize(); } catch (_) {} });
      sep();
      add('Close window', null, function() { try { window.electronAPI.windowClose(); } catch (_) {} });
      show(e.clientX, e.clientY);
    });
  }

  // --- Reload variants ---
  function reloadMenu(e) {
    begin();
    add('Normal reload', 'Ctrl+R', function() { var wv = activeWv(); if (wv) { try { wv.reload(); } catch (e0) {} } });
    add('Hard reload', 'Ctrl+Shift+R', function() { var wv = activeWv(); if (wv) { try { wv.reloadIgnoringCache(); } catch (e0) {} } });
    add('Empty cache and hard reload', null, function() {
      var wv = activeWv();
      if (!wv) return;
      var doReload = function() { try { wv.reloadIgnoringCache(); } catch (e0) {} };
      if (window.electronAPI && window.electronAPI.clearCacheReload) {
        window.electronAPI.clearCacheReload().then(doReload).catch(doReload);
      } else doReload();
    });
    show(e.clientX, e.clientY);
  }

  // --- Back / Forward history ---
  // Favicon source mirrors the tab favicons (Google s2 — resolves favicons
  // for Google/Yandex/Bing/DuckDuckGo and virtually any other site), gated
  // by the faviconsEnabled external-service toggle like everywhere else.
  function _menuFavicon(u) {
    try { return spzFaviconUrl(new URL(u).hostname); }
    catch (e) { return ''; }
  }
  function _hostOf(u) {
    try { return new URL(u).hostname.replace(/^www\./, ''); } catch (e) { return u; }
  }
  function historyMenu(e, dir) {
    var tab = getActiveTab();
    var nh = (tab && tab.navHistory) || [];
    var idx = (tab && typeof tab.navIndex === 'number') ? tab.navIndex : nh.length - 1;
    var entries = dir === -1 ? nh.slice(0, idx).reverse() : nh.slice(idx + 1);
    begin();
    if (!entries.length) {
      add(dir === -1 ? 'No back history' : 'No forward history', null, null, { disabled: true });
    } else {
      entries.slice(0, 15).forEach(function(en) {
        var i = nh.indexOf(en);
        var label = en.title || _hostOf(en.url);
        var it = add(label, null, function() {
          var wv = activeWv();
          if (!wv) return;
          try { wv.goToOffset(i - idx); } catch (e0) { try { wv.goBack(); } catch (e1) {} }
          tab.navIndex = i;
        }, { icon: _menuFavicon(en.url) });
        if (it) it.title = en.url; // full URL as a native tooltip
      });
      sep();
    }
    add('Show all history', null, function() { createNewTab('Library.html#history'); });
    show(e.clientX, e.clientY);
  }

  // --- Toolbar shortcut buttons: unpin + customize ---
  function pinMenu(e, key) {
    begin();
    if (key === 'adblock') {
      // Permanent button — never unpinnable.
      add('Blocker is always on the toolbar', null, null, { disabled: true });
      sep();
    } else if (key) {
      add('Unpin', null, function() {
        var cur = _getToolbarButtons().filter(function(k) { return k !== key; });
        if (window.electronAPI && window.electronAPI.saveToolbarButtons) {
          window.electronAPI.saveToolbarButtons(cur);
        }
        _applyToolbarLayout(cur);
      });
      sep();
    }
    add('Customize toolbar…', null, function() {
      var btn = document.getElementById('open-toolbar-customization');
      if (btn) btn.click();
      else createNewTab('Settings.html#customization');
    });
    show(e.clientX, e.clientY);
  }

  // --- URL bar text menu ---
  function urlMenu(e) {
    var inp = document.getElementById('urlInput');
    if (!inp) return;
    var hasSel = false;
    try { hasSel = inp.selectionEnd > inp.selectionStart; } catch (e0) {}
    begin();
    add('Cut', 'Ctrl+X', function() { try { document.execCommand('cut'); } catch (e0) {} }, { disabled: !hasSel });
    add('Copy', 'Ctrl+C', function() { try { document.execCommand('copy'); } catch (e0) {} }, { disabled: !hasSel });
    add('Paste', 'Ctrl+V', function() {
      if (window.electronAPI && window.electronAPI.readClipboard) {
        window.electronAPI.readClipboard().then(function(txt) {
          if (typeof txt !== 'string' || !txt) return;
          var s = inp.selectionStart, epos = inp.selectionEnd;
          inp.value = inp.value.slice(0, s) + txt + inp.value.slice(epos);
          var pos = s + txt.length;
          try { inp.setSelectionRange(pos, pos); } catch (e0) {}
          inp.focus();
        }).catch(function() {});
      }
    });
    add('Paste and search', null, function() {
      if (window.electronAPI && window.electronAPI.readClipboard) {
        window.electronAPI.readClipboard().then(function(txt) {
          if (typeof txt !== 'string' || !txt) return;
          inp.value = txt;
          inp.focus();
          try { inp.setSelectionRange(txt.length, txt.length); } catch (e0) {}
          inp.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true }));
        }).catch(function() {});
      }
    });
    add('Delete', 'Del', function() {
      var s = inp.selectionStart, epos = inp.selectionEnd;
      if (epos > s) {
        inp.value = inp.value.slice(0, s) + inp.value.slice(epos);
        try { inp.setSelectionRange(s, s); } catch (e0) {}
        inp.focus();
      }
    }, { disabled: !hasSel });
    add('Select all', 'Ctrl+A', function() { inp.focus(); inp.select(); });
    show(e.clientX, e.clientY);
  }

  // Map a DOM element to its customizable toolbar key (if any).
  function toolbarKeyOf(el) {
    var btn = el.closest('.nav-btn, .hamburger-btn, .workspace-btn');
    if (!btn || !btn.id) return null;
    var found = null;
    Object.keys(_customizeBtnMap).forEach(function(k) {
      if (_customizeBtnMap[k].el === btn.id) found = k;
    });
    if (!found && btn.classList.contains('workspace-btn')) found = 'workspace';
    return found;
  }

  document.addEventListener('contextmenu', function(e) {
    var t = e.target;
    if (!t || !t.closest) return;

    // URL bar — text menu.
    if (t.closest('#urlInput')) { e.preventDefault(); urlMenu(e); return; }

    // Reload — reload variants.
    if (t.closest('#reloadBtn')) { e.preventDefault(); reloadMenu(e); return; }

    // Back / Forward — tab history.
    if (t.closest('#backBtn')) { e.preventDefault(); historyMenu(e, -1); return; }
    if (t.closest('#forwardBtn')) { e.preventDefault(); historyMenu(e, 1); return; }

    // Toolbar shortcut buttons — Unpin + Customize. The workspace switcher
    // and navigation trio keep only "Customize toolbar…".
    var key = toolbarKeyOf(t);
    if (key) {
      e.preventDefault();
      pinMenu(e, (key === 'workspace' || key === 'back' || key === 'forward' || key === 'reload') ? null : key);
      return;
    }

    // Tabs keep their own rich menu; everything else in the chrome shows
    // NO context menu at all.
    if (t.closest('.tab, .tabs-bar')) return;
    if (t.closest('input, textarea')) { e.preventDefault(); return; }
    // Title bar (incl. the empty tab-strip space) → the native-style
    // window menu — frameless windows have no system chrome for this.
    if (t.closest('.titlebar')) { e.preventDefault(); windowMenu(e); return; }
    if (t.closest('.navbar, body')) { e.preventDefault(); return; }
  });
})();

// ============== FIRST-RUN WIZARD — REMOVED =============
// The 4-step onboarding overlay (and the Start.htm first-launch tab) were
// removed on request: the new tab page (MainPage) already serves as the
// first-run surface, and the wizard kept re-appearing on fresh profiles
// of new installs. Fresh profiles now open the MainPage directly; the
// master password is set in Settings → Security, presets — on the
// MainPage / Settings. The get/first-run IPC handlers stay (unused).

// ============== BROWSER STARTUP LOCK (appLock) ==============
// If the user enabled "Lock browser on startup" in Settings → Protection,
// the whole UI is covered by #appLockScreen until the master password
// (or fingerprint) is entered. One unlock per browser launch.
(function initAppLock() {
  function show() {
    var sc = document.getElementById('appLockScreen');
    if (!sc) return;
    sc.style.display = 'flex';
    var inp = document.getElementById('appLockInput');
    var err = document.getElementById('appLockError');
    if (err) err.textContent = '';
    if (inp) { inp.value = ''; setTimeout(function() { inp.focus(); }, 30); }
  }
  function hide() {
    var sc = document.getElementById('appLockScreen');
    if (sc) sc.style.display = 'none';
  }
  function attempt() {
    var inp = document.getElementById('appLockInput');
    var err = document.getElementById('appLockError');
    var btn = document.getElementById('appLockBtn');
    if (!inp || !window.electronAPI || !window.electronAPI.verifyAppLock) return;
    var pw = inp.value;
    if (!pw) { if (err) err.textContent = 'Enter your master password'; return; }
    if (btn) { btn.disabled = true; btn.textContent = 'Unlocking…'; }
    if (err) err.textContent = '';
    window.electronAPI.verifyAppLock(pw).then(function(res) {
      if (btn) { btn.disabled = false; btn.textContent = 'Unlock'; }
      if (res && res.success) { hide(); if (window.electronAPI.rearmIdleLock) window.electronAPI.rearmIdleLock(); }
      else { if (err) err.textContent = (res && res.message) || 'Wrong password'; if (inp) inp.focus(); }
    }).catch(function() {
      if (btn) { btn.disabled = false; btn.textContent = 'Unlock'; }
      if (err) err.textContent = 'Unlock failed';
    });
  }
  function run() {
    if (!window.electronAPI || !window.electronAPI.checkAppLock) return;
    window.electronAPI.checkAppLock().then(function(st) {
      if (!st || !st.needsAuth) return;
      var bio = document.getElementById('appLockBioBtn');
      if (bio && st.biometricRequired && st.biometricAvailable) bio.style.display = 'flex';
      show();
    }).catch(function() {});

    var btn = document.getElementById('appLockBtn');
    var inp = document.getElementById('appLockInput');
    var bio = document.getElementById('appLockBioBtn');
    if (btn) btn.addEventListener('click', attempt);
    if (inp) inp.addEventListener('keydown', function(e) { if (e.key === 'Enter') attempt(); });
    if (bio) bio.addEventListener('click', function() {
      var err = document.getElementById('appLockError');
      if (err) err.textContent = '';
      if (!window.electronAPI || !window.electronAPI.appBiometricAuth) return;
      window.electronAPI.appBiometricAuth().then(function(res) {
        if (res && res.success) { hide(); if (window.electronAPI.rearmIdleLock) window.electronAPI.rearmIdleLock(); }
        else if (err) err.textContent = (res && res.message) || 'Biometric failed';
      }).catch(function() { if (err) err.textContent = 'Biometric failed'; });
    });

    // Auto-lock on inactivity: main fires 'idle-lock-triggered' when the
    // system has been idle beyond the configured threshold — show the lock.
    if (window.electronAPI && window.electronAPI.onIdleLockTriggered) {
      window.electronAPI.onIdleLockTriggered(function() { show(); });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
  else run();
})();

// ============== HOTKEYS OVERLAY ==============
// A translucent cheat-sheet listing all configured shortcuts. Shown either by
// holding a bare modifier key (Ctrl/Shift/Alt) for ~500 ms (VS Code style) or
// by pressing '?' when not in an input field. Gated by the 'hotkeysOverlay'
// setting (default ON). Toggled in Settings → Hotkeys.
(function initHotkeysOverlay() {
  var _enabled = true;
  var _bindings = null;
  var _actions = null;
  var _overlay = document.getElementById('hotkeysOverlay');
  var _grid = document.getElementById('hotkeysOverlayGrid');
  var _holdTimer = null;
  var _visible = false;

  // Friendly labels for the action keys (mirrors _keybindingActions in main.js
  // but with shorter text suitable for a small overlay).
  function actionLabel(id) {
    var map = {
      newTab: 'New tab', closeTab: 'Close tab', focusUrl: 'Focus address bar',
      reload: 'Reload page', find: 'Find on page', print: 'Print',
      savePage: 'Save page', addBookmark: 'Add bookmark', goBack: 'Back',
      goForward: 'Forward', reopenClosed: 'Reopen closed tab',
      nextTab: 'Next tab', prevTab: 'Previous tab',
      quickCommands: 'Command palette', devTools: 'Developer tools',
      pip: 'Picture in picture', taskManager: 'Task manager'
    };
    return map[id] || id;
  }
  function comboStr(b) {
    if (!b || !b.key) return '—';
    var parts = [];
    if (b.ctrl) parts.push('Ctrl');
    if (b.alt) parts.push('Alt');
    if (b.shift) parts.push('Shift');
    var k = String(b.key);
    // Tidy arrow / special key names.
    k = k.replace('Arrow', '');
    parts.push(k.length === 1 ? k.toUpperCase() : k);
    return parts.join(' + ');
  }
  function renderGrid() {
    if (!_grid || !_bindings) return;
    var order = ['newTab','closeTab','nextTab','prevTab','reopenClosed','focusUrl',
                 'reload','find','goBack','goForward','addBookmark','savePage',
                 'print','pip','quickCommands','devTools','taskManager'];
    var html = '';
    order.forEach(function(id) {
      var b = _bindings[id];
      if (!b) return;
      html += '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px solid var(--border-color,rgba(255,255,255,0.06));">'
        + '<span style="color:var(--text-color,#fff);">' + actionLabel(id) + '</span>'
        + '<kbd style="font-family:monospace;font-size:11px;background:var(--input-bg,rgba(255,255,255,0.08));color:var(--text-color,#fff);padding:2px 8px;border-radius:6px;border:1px solid var(--border-color,rgba(255,255,255,0.1));white-space:nowrap;">' + comboStr(b) + '</kbd>'
        + '</div>';
    });
    _grid.innerHTML = html;
  }
  function loadBindings() {
    if (!window.electronAPI || !window.electronAPI.getKeybindings) return;
    window.electronAPI.getKeybindings().then(function(res) {
      if (!res) return;
      _enabled = res.overlayEnabled !== false;
      _bindings = res.bindings || {};
      _actions = res.actions || null;
    }).catch(function() {});
  }
  function show() {
    if (!_enabled || !_overlay) return;
    if (_visible) return;
    renderGrid();
    _overlay.style.display = 'flex';
    _visible = true;
  }
  function hide() {
    if (!_overlay || !_visible) return;
    _overlay.style.display = 'none';
    _visible = false;
  }
  function inEditable(el) {
    if (!el) return false;
    var tag = el.tagName;
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable;
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', loadBindings);
  else loadBindings();

  document.addEventListener('keydown', function(e) {
    // Esc closes the overlay (always — even from an input).
    if (e.key === 'Escape' && _visible) { hide(); return; }
    if (inEditable(e.target)) return;
    // '?' (Shift+/) toggles.
    if (e.key === '?' && !e.ctrlKey && !e.altKey && !e.metaKey) {
      e.preventDefault();
      if (_visible) hide(); else show();
      return;
    }
    // Hold-to-show: a BARE modifier key (no other key) held for 500 ms.
    // Detected by e.code so it works regardless of e.shiftKey/ctrlKey state.
    if (e.code === 'ControlLeft' || e.code === 'ControlRight' ||
        e.code === 'ShiftLeft' || e.code === 'ShiftRight' ||
        e.code === 'AltLeft' || e.code === 'AltRight' ||
        e.code === 'MetaLeft' || e.code === 'MetaRight') {
      if (_holdTimer) clearTimeout(_holdTimer);
      _holdTimer = setTimeout(function() { show(); }, 500);
    }
  });
  document.addEventListener('keyup', function(e) {
    if (_holdTimer) { clearTimeout(_holdTimer); _holdTimer = null; }
    if (_visible && (e.key === 'Control' || e.key === 'Shift' || e.key === 'Alt' || e.key === 'Meta')) {
      hide();
    }
  });
  // Click anywhere on the overlay backdrop closes it.
  if (_overlay) {
    _overlay.addEventListener('click', function(e) {
      if (e.target === _overlay) hide();
    });
  }
  // Reload bindings when returning to the window (user may have changed them).
  window.addEventListener('focus', loadBindings);
})();
